INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leto-labs/jarvis-template/crm', 'community', 'leto-labs', 'jarvis-template', 'leto-labs/jarvis-template', 'crm', 0, 0, 51, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:00.978Z', 'cf5da5bd51680d679353d5183a7140381f94bcaad1c2c341f2272b25c439729f', '{"id":"leto-labs/jarvis-template/crm","name":"crm","description":{"en":"The CRM skill is a Telegram-based tool that auto-detects entity types from queries, researching people and companies with intelligent linking and relationship discovery, benefiting developers and researchers.","zh":"CRM 技术允许自动检测实体类型、研究人员和公司，并将它们添加到数据库中","ja":"CRM スキルはエンティティタイプを自動で検出して、人物や会社を調査し、データベースに追加します","ko":"CRM 기술은 자동 实体 유형 감지, 사람 및 회사 연구, 데이터베이스 추가를 지원합니다","es":"La habilidad de CRM permite a los desarrolladores investigar y agregar personas o empresas a la base de datos con vinculación y descubrimiento de relaciones inteligentes","fr":"La compétence CRM permet aux développeurs de rechercher et d''ajouter des personnes ou des entreprises à la base de données avec un lien et une découverte de relations intelligents","de":"Die CRM-Fähigkeit ermöglicht es Entwicklern, Personen oder Unternehmen zu recherchieren und zur Datenbank hinzuzufügen, mit intelligenter Verknüpfung und Beziehungsfindung","pt":"O CRM é uma habilidade de inteligência artificial que pesquisa e adiciona pessoas ou empresas ao banco de dados com links inteligentes","ru":"CRM - это навык ИИ Агента, который исследует и добавляет людей или компании в базу данных с интеллектуальными ссылками","ar":"CRM هو مهارة ذكاء اصطناعي يبحث و يضيف الأشخاص أو الشركات إلى قاعدة البيانات مع الروابط الذكية"},"seo":{"title":{"en":"CRM Skill: Intelligent Linking and Relationship Discovery...","zh":"CRM 技术集成指南 - AIエージェント开发最佳实践","ja":"CRM Setup Guide - AIエージェントを使用した開発のベストプラクティス","ko":"CRM 개발 가이드 - AI 에이전트를 이용한 관계형 데이터베이스 연동","es":"Guía de configuración de CRM para desarrolladores","fr":"Guide de mise en place de la compétence CRM pour les déve...","de":"CRM-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do CRM: Integração com Inteligência ...","ru":"Настройка CRM: ИИ Агенты дляリンク и открытия отношений","ar":"دليل إعداد CRM: دمج الذكاء الاصطناعي للبحث والرابط"},"description":{"en":"Unlock the power of CRM with AI-driven entity detection and research. Learn how to invoke the /crm skill and discover its capabilities","zh":"了解如何使用 CRM 技术自动检测实体类型、研究人员和公司，并将它们添加到数据库中，实现智能链接和关系发现","ja":"CRM スキルを使用して、エンティティタイプを自動で検出して、人物や会社を調査し、データベースに追加する方法を学びます","ko":"CRM 개발을 위한 기술 가이드: 자동 实体 유형 감지, 사람 및 회사 연구, 데이터베이스 추가 및 지능형 링크","es":"Aprende a configurar la habilidad de CRM para desarrolladores con nuestra guía paso a paso y mejora tus habilidades de desarrollo","fr":"Découvrez comment configurer la compétence CRM pour les développeurs avec notre guide étape par étape et améliorez vos compétences en développement","de":"Erfahren Sie, wie Sie die CRM-Fähigkeit für Entwickler mit unserem Schritt-für-Schritt-Leitfaden konfigurieren und verbessern Sie Ihre Entwicklungsfähigkeiten","pt":"Descubra como configurar o CRM com inteligência artificial para pesquisar e adicionar pessoas ou empresas ao banco de dados com links inteligentes","ru":"Узнайте, как настроить CRM с ИИ Агентами для исследования и добавления людей или компаний в базу данных с интеллектуальными ссылками","ar":"تعرف على كيفية إعداد CRM مع الذكاء الاصطناعي للبحث وإضافة الأشخاص أو الشركات إلى قاعدة البيانات مع الروابط الذكية"},"definition":{"en":"crm is a Telegram skill that invokes with /crm, enabling entity research and database population with intelligent linking and relationship discovery","zh":"CRM 技术是指使用 AI エージェント自动检测实体类型并将其添加到关系数据库中的技术","ja":"CRM 技術とは、AIエージェントを使用してエンティティタイプを自動で検出して、関係データベースに追加する技術です","ko":"CRM 기술은 AI 에이전트를 이용한 자동 实体 유형 감지 및 관계형 데이터베이스 연동을 위한 기술입니다","es":"La habilidad de CRM es una herramienta de investigación y gestión de datos que utiliza técnicas de vinculación y descubrimiento de relaciones para mejorar la eficiencia del desarrollo","fr":"La compétence CRM est un outil de recherche et de gestion de données qui utilise des techniques de lien et de découverte de relations pour améliorer l''efficacité du développement","de":"Die CRM-Fähigkeit ist ein Forschungs- und Datenmanagement-Tool, das Verknüpfungs- und Beziehungsfindungstechniken verwendet, um die Entwicklungseffizienz zu verbessern","pt":"O que é CRM? É uma habilidade de inteligência artificial que pesquisa e adiciona pessoas ou empresas ao banco de dados","ru":"Что такое CRM? Это навык ИИ Агента, который исследует и добавляет людей или компании в базу данных","ar":"ما هو CRM? هو مهارة ذكاء اصطناعي يبحث و يضيف الأشخاص أو الشركات إلى قاعدة البيانات"},"features":{"en":["Auto-detects entity type from query using input detection","Researches people and companies from email domains","Supports invocation via /crm command in Telegram","Enables intelligent linking and relationship discovery","Populates database with researched entities","Handles different input types, including email and person names"],"zh":["自动检测实体类型","研究人员和公司","将实体添加到关系数据库中","智能链接和关系发现","支持 Email 和人员名称查询"],"ja":["エンティティタイプの自動検出","人物や会社の調査","関係データベースへのエンティティの追加","智能リンクと関係の発見","Email と人物名称のクエリをサポート"],"ko":["자동 实体 유형 감지","사람 및 회사 연구","관계형 데이터베이스 추가","지능형 링크 및 관계 발견","Email 및 사람 이름 쿼리 지원"],"es":["Detección automática de tipo de entidad desde la consulta","Investigación de personas y empresas con vinculación y descubrimiento de relaciones inteligentes","Compatibilidad con entradas de correo electrónico y nombres de personas","Invocación mediante el comando `/crm` en Telegram","Integración con bases de datos para agregar y gestionar datos","Descubrimiento de relaciones entre personas y empresas"],"fr":["Détection automatique du type d''entité depuis la requête","Recherche de personnes et d''entreprises avec lien et découverte de relations intelligents","Compatibilité avec les entrées de courriel et les noms de personnes","Invocation via la commande `/crm` sur Telegram","Intégration avec les bases de données pour ajouter et gérer des données","Découverte de relations entre personnes et entreprises"],"de":["Automatische Erkennung von Entitätstypen aus der Abfrage","Recherche von Personen und Unternehmen mit intelligenter Verknüpfung und Beziehungsfindung","Kompatibilität mit E-Mail-Eingaben und Personennamen","Aufruf über den Befehl `/crm` in Telegram","Integration mit Datenbanken zum Hinzufügen und Verwalten von Daten","Beziehungsfindung zwischen Personen und Unternehmen"],"pt":["Detecção automática de tipo de entidade a partir da consulta","Pesquisa de pessoas e empresas com links inteligentes","Adiciona pessoas ou empresas ao banco de dados com relacionamentos inteligentes","Suporte a consultas de e-mail e nome de pessoa","Integração com Telegram para invocar a habilidade com /crm"],"ru":["Автоматическое обнаружение типа сущности из запроса","Исследование людей и компаний с интеллектуальными ссылками","Добавление людей или компаний в базу данных с интеллектуальными отношениями","Поддержка запросов электронной почты и имени человека","Интеграция с Telegram для вызова навыка с /crm"],"ar":["اكتشاف 자동ي لنوع الكيان من الاستعلام","البحث عن الأشخاص والشركات مع الروابط الذكية","إضافة الأشخاص أو الشركات إلى قاعدة البيانات مع العلاقات الذكية","دعم استفسارات البريد الإلكتروني واسم الشخص","التكامل مع Telegram لاستدعاء المهارة مع /crm"]},"keywords":{"en":["how to use crm skill","crm alternative solutions","crm setup guide for telegram","what is crm skill","crm vs salesforce","crm install for ai agents","crm entity detection","crm relationship discovery","crm skill for developers","crm telegram integration"],"zh":["CRM 技术","AI エージェント","关系数据库","自动检测实体类型","研究人员和公司","智能链接","关系发现","Email 查询","人员名称查询"],"ja":["CRM 技術","AIエージェント","関係データベース","エンティティタイプの自動検出","人物や会社の調査","智能リンク","関係の発見","Email クエリ","人物名称クエリ"],"ko":["CRM 기술","AI 에이전트","관계형 데이터베이스","자동 实体 유형 감지","사람 및 회사 연구","지능형 링크","관계 발견","Email 쿼리","사람 이름 쿼리"],"es":["crm para desarrolladores","herramientas de crm","desarrollo de software","gestión de datos","vinculación de datos","descubrimiento de relaciones","telegram crm","crm inteligente","desarrollo de aplicaciones","integración de crm"],"fr":["crm pour développeurs","outils de crm","développement de logiciels","gestion de données","lien de données","découverte de relations","telegram crm","crm intelligent","développement d''applications","intégration de crm"],"de":["crm für entwickler","crm-tools","software-entwicklung","datenmanagement","datenverknüpfung","beziehungsfindung","telegram crm","intelligente crm","anwendungsentwicklung","crm-integration"],"pt":["crm inteligência artificial","configuração crm","pesquisa de pessoas e empresas","links inteligentes","detecção de entidade","telegram crm","desenvolvimento de crm"],"ru":["crm ии агенты","настройка crm","исследование людей и компаний","интеллектуальные ссылки","обнаружение сущности","telegram crm","разработка crm"],"ar":["crm ذكاء اصطناعي","إعداد crm","البحث عن الأشخاص والشركات","الروابط الذكية","اكتشاف الكيان","telegram crm","تطوير crm"]}},"owner":"leto-labs","repo":"jarvis-template","repoPath":"leto-labs/jarvis-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"crm","description":"Research people and companies, add to CRM database with smart linking","bodyPreview":"# CRM Skill\n\n**Telegram Skill** - Invoke with `/crm` (no parameters)\n\nThis is a Telegram skill. When invoked with `/crm`, the skill will prompt you for the query to research and add people or companies to the Database with intelligent linking and relationship discovery.\n\n## Input Detection\n\nThe skill auto-detects entity type from query:\n\n| Input Type | Example | Action |\n|------------|---------|--------|\n| Email | `john@anthropic.com` | Research person + company from domain |\n| Person name | `Jo","body":"# CRM Skill\n\n**Telegram Skill** - Invoke with `/crm` (no parameters)\n\nThis is a Telegram skill. When invoked with `/crm`, the skill will prompt you for the query to research and add people or companies to the Database with intelligent linking and relationship discovery.\n\n## Input Detection\n\nThe skill auto-detects entity type from query:\n\n| Input Type | Example | Action |\n|------------|---------|--------|\n| Email | `john@anthropic.com` | Research person + company from domain |\n| Person name | `John Doe` | Research person only |\n| Person + company | `John Doe at Anthropic` | Research both, link them |\n| Company name | `Anthropic` | Research company |\n| Company domain | `anthropic.com` | Research company |\n| LinkedIn URL (person) | `linkedin.com/in/username` | Research person |\n| LinkedIn URL (company) | `linkedin.com/company/name` | Research company |\n\n## Execution Flow\n\n### Phase 1: Entity Detection & Duplicate Check\n\n1. **Parse Input**: Determine if query is person, company, or both\n2. **Check Duplicates**:\n   - **People**: Match by email > LinkedIn URL > name (case-insensitive)\n   - **Companies**: Match by domain > LinkedIn > name\n   - If fuzzy match found, ask user to confirm\n   - If multiple matches, show differentiators and let user decide\n\n### Phase 2: Research\n\n#### For Person:\nUse web search to find:\n- LinkedIn profile (priority)\n- Current company and role\n- Email address (if not provided)\n- Twitter/X profile\n- Location\n- Professional background and achievements\n- Recent news or notable projects\n\n#### For Company:\nUse web search to find:\n- Company website\n- LinkedIn company page\n- Industry and description\n- Company stage (seed/series-a/public/etc)\n- Company size (employee count)\n- Location (headquarters)\n- Twitter/X handle\n- Recent news or funding announcements\n\n**Research Best Practices:**\n- Verify information from multiple sources\n- Focus on publicly available professional information only\n- Clearly indicate uncertain/unavailable information\n- Add research date and sources for reference\n\n### Phase 3: Smart Linking\n\n#### Person → Company Linking:\n1. If person''s company is found during research\n2. Check if company exists in `Database/Companies/`\n3. If company doesn''t exist:\n   - Ask user: \"Would you like me to create a company entry for [Company Name]?\"\n   - If yes, research and create company entry\n4. Link person to company via `company: \"[[Database/Companies/Company-Name]]\"` field\n\n#### Company → People Discovery:\nWhen researching a company, offer to find key people:\n- Ask user: \"Would you like me to research key people at [Company Name] (founders, executives, decision-makers)?\"\n- If yes:\n  - Search for 3-5 key people (founders, C-suite, VPs)\n  - Show list of found people with roles\n  - Ask: \"Which of these people should I add to the database?\"\n  - Create entries for selected people with company links\n\n#### Person → Coworkers Discovery:\nWhen researching a person, offer to find coworkers:\n- Ask user: \"Would you like me to search for [Person]''s coworkers at [Company]?\"\n- If yes:\n  - Search for people at the same company (LinkedIn, team pages)\n  - Show list of found coworkers with roles\n  - Ask: \"Which coworkers should I add to the database?\"\n  - Create entries for selected people with company links\n\n### Phase 4: Create or Update Entry\n\n#### If Updating Existing Entry:\n- Read current file completely\n- Merge new information with existing data\n- **PRESERVE** all user-added content:\n  - Notes section\n  - Interaction history\n  - Custom tags\n  - Relationship info\n  - Next actions\n- Add update note with date at bottom\n- Only update fields with new/better information\n\n#### If Creating New Entry:\n\n**Person Entry:**\n- Filename: `First-Last.md` (e.g., `John-Doe.md`)\n- Use `Database/People/Person-Template.md` structure\n- Include all found information\n- Link to company if identified\n- Set relationship type (contact by default)\n- Add research date and sources\n\n**Company Entry:**\n- Filename: `Company-Name.md` (e.g., `Anthropic.md`)\n- Use `Database/Companies/Company-Template.md` structure\n- Include all found information\n- Set relationship type (prospect by default)\n- Add research date and sources\n- Include Contacts Base query for dynamic people list\n\n## File Structure Templates\n\n### Person Entry:\n```markdown\n---\ntype: person\ncompany: \"[[Database/Companies/Company-Name]]\"\nrole: VP Engineering\nemail: person@company.com\nlinkedin: https://linkedin.com/in/username\ntwitter: https://twitter.com/username\nlocation: San Francisco, CA\nrelationship: contact\nlast_contact:\nnext_action:\ncreated: 2026-01-21\ntags:\n  - person\n  - contact\n---\n\n# Full Name\n\n## Role & Background\n\nCurrent role and background information.\n\n## Contact Information\n\n- Email: [[email]]\n- LinkedIn: [[linkedin]]\n- Twitter: [[twitter]]\n- Location: [[location]]\n- Company: [[company]]\n\n## Relationship\n\nType: [[relationship]]\nHow we know each other, context of relationship.\n\n## Interaction History\n\n### YYYY-MM-DD\nNotes from meeting/interaction...\n\n## Tasks & Projects\n\nRelated tasks or projects involving this person.\n\n```base\nfilters:\n  and:\n    - file.inFolder(\"Database/Tasks\")\n    - assignee == link(this.file)\nviews:\n  - type: table\n    name: Tasks\n    order:\n      - status\n      - priority\n```\n\n## Notes\n\nAdditional context, interests, preferences, etc.\n\n---\n*Research Date: [current date]*\n*Sources: [list sources]*\n```\n\n### Company Entry:\n```markdown\n---\ntype: company\nindustry: Industry Name\nstage: startup\nsize: 1-10\nlocation: City, Country\nwebsite: https://example.com\nlinkedin: https://linkedin.com/company/name\ntwitter: https://twitter.com/company\nrelationship: prospect\nlast_interaction:\nnext_action:\ntags:\n  - company\n  - prospect\n---\n\n# Company Name\n\n## Overview\n\nBrief description of what the company does.\n\n## Details\n\n- **Industry**: [[industry]]\n- **Stage**: [[stage]] (seed/series-a/series-b/public/etc)\n- **Size**: [[size]] employees\n- **Location**: [[location]]\n- **Website**: [[website]]\n\n## Relationship\n\nType: [[relationship]] (prospect/partner/client/vendor/investor/etc)\nContext of relationship.\n\n## Contacts\n\nPeople we know at this company:\n\n```base\nfilters:\n  and:\n    - file.inFolder(\"Database/People\")\n    - company == link(this.file)\nviews:\n  - type: table\n    name: Contacts\n    order:\n      - role\n      - file.name\n```\n\n## Interaction History\n\n### YYYY-MM-DD\nNotes from meeting/interaction...\n\n## Projects & Opportunities\n\nRelated projects or business opportunities.\n\n## Notes\n\nAdditional context, competitive intel, etc.\n\n---\n*Research Date: [current date]*\n*Sources: [list sources]*\n```\n\n## Response Format\n\n**IMPORTANT**: Never mention file paths (Database/People/, Database/Companies/) or file extensions (.md) in responses. Only mention entity names (person names, company names).\n\n### New Person Entry:\n```\n✅ Research completed for [Person Name]\n📍 Person profile created\n\nKey Info:\n• Role: [Job Title] at [Company]\n• Location: [Location]\n• Email: [Yes/No]\n• LinkedIn: [Yes/No]\n\n[2-3 sentence summary of background]\n\nCompany: [Created/Linked to existing] [Company Name]\nSources: [N] reviewed\n```\n\n### New Company Entry:\n```\n✅ Research completed for [Company Name]\n📍 Company profile created\n\nKey Info:\n• Industry: [Industry]\n• Stage: [Stage]\n• Size: [Size]\n• Location: [Location]\n\n[2-3 sentence summary of what they do]\n\nSources: [N] reviewed\n```\n\n### Updated Entry:\n```\n✅ Research completed for [Person/Company Name]\n📍 [Person/Company] profile updated\n\nUpdates:\n• [What changed]\n• [What changed]\n\nSources: [N] reviewed\n```\n\n### With Related Entities Added:\n```\n✅ Added [N] people from [Company Name]\n\n📍 [Person Name]\n→ [Role] | [Key background points]\n\n📍 [Person Name]\n→ [Role] | [Key background points]\n\nAll linked to [Company Name].\n```\n\n## User Interaction Examples\n\n### Example 1: Email Input with Company Creation\n```\nUser: /crm\nAssistant: Please provide the person or company you''d like to research.\nUser: john@anthropic.com\nAssistant: [Searches for John and Anthropic]\nAssistant: Found John Doe, VP of Engineering at Anthropic.\nAnthropic doesn''t exist in the database yet.\nWould you like me to create a company entry for Anthropic?\nUser: yes\nAssistant: [Creates both entries, links them]\n✅ Research completed for John Doe\n📍 Person profile created\n📍 Company profile created: Anthropic\n```\n\n### Example 2: Company with People Discovery\n```\nUser: /crm\nAssistant: Please provide the person or company you''d like to research.\nUser: Anthropic\nAssistant: [Researches Anthropic]\nWould you like me to research key people at Anthropic (founders, executives)?\nUser: yes\nAssistant: [Searches for key people]\nFound the following key people at Anthropic:\n1. Dario Amodei - CEO & Co-founder\n2. Daniela Amodei - President & Co-founder\n3. Tom Brown - Co-founder\n\nWhich of these people should I add to the database? (You can select multiple or say \"all\")\nUser: 1 and 2\nAssistant: [Creates entries for Dario and Daniela]\n✅ Added 2 people from Anthropic\n\n📍 Dario Amodei\n→ CEO & Co-founder\n\n📍 Daniela Amodei\n→ President & Co-founder\n\nAll linked to Anthropic.\n```\n\n### Example 3: Person with Coworkers Discovery\n```\nUser: /crm\nAssistant: Please provide the person or company you''d like to research.\nUser: Jane Smith at Example Corp\nAssistant: [Researches Jane Smith]\nWould you like me to search for Jane''s coworkers at Example Corp?\nUser: yes\nAssistant: [Searches for coworkers]\nFound the following coworkers:\n1. Bob Johnson - VP Sales\n2. Alice Chen - Director of Engineering\n3. Mike Davis - Product Manager\n\nWhich coworkers should I add? (You can select multiple or say \"all\")\nUser: skip\nAssistant: [Creates only Jane''s entry]\n✅ Research completed for Jane Smith\n📍 Person profile created\n```\n\n## Best Practices\n\n### Duplicate Prevention:\n- Always check duplicates BEFORE researching\n- Match by email (highest priority), then LinkedIn, then name\n- For names, check variations (John vs J., Smith vs Smyth)\n- If uncertain, ask user to confirm\n\n### Information Quality:\n- Verify from multiple sources when possible\n- Mark uncertain information clearly\n- Don''t invent information if not found\n- Save partial information rather than nothing\n\n### User Experience:\n- Always ask before adding related entities\n- Show clear options for user selection\n- Provide context (roles, differentiators) in choices\n- Allow \"skip\" or \"none\" as valid responses\n\n### File Management:\n- Use consistent filename conventions\n- Preserve all user-added content when updating\n- Document what changed and when\n- Include research date and sources\n\n### Relationship Context:\n- Default to \"contact\" for people, \"prospect\" for companies\n- If context suggests different relationship, use appropriate type\n- Document how/why entity was added in Relationship section\n\n## Relationship Types\n\n### For People:\n- `contact` - General external contact (default)\n- `colleague` - Team member or coworker\n- `client` - Customer or client contact\n- `partner` - Partnership or collaboration contact\n- `investor` - Investor or VC contact\n\n### For Companies:\n- `prospect` - Potential client or partner (default)\n- `partner` - Active partnership\n- `client` - Paying customer\n- `vendor` - Service provider to us\n- `investor` - Current or potential investor\n- `competitor` - Competitive intelligence\n\n## Tone\n\nProfessional, factual, organized, efficient. Focus on actionable information without fluff.\n"},"lastSynced":"2026-03-08T02:14:00.978Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing entity type detection and intelligent linking for people and companies.","zh":"非常适合需要实体类型检测和智能链接的研究代理，特别是对于人员和公司的链接。","ja":"研究エージェントがエンティティタイプ検出と人や企業のためのインテリジェントリンクを必要とする場合に最適です。","ko":"엔티티 유형 감지 및 사람과 회사에 대한 지능형 연결이 필요한 연구 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Investigación que necesitan detección de tipo de entidad y enlace inteligente para personas y empresas.","fr":"Parfait pour les Agents de Recherche ayant besoin de détection de type d''entité et de lien intelligent pour les personnes et les entreprises.","de":"Perfekt für Research-Agenten, die Entitätstyp-Erkennung und intelligente Verknüpfung für Personen und Unternehmen benötigen.","pt":"Perfeito para Agentes de Pesquisa que necessitam de detecção de tipo de entidade e linkagem inteligente para pessoas e empresas.","ru":"Идеально для исследовательских агентов, которым требуется обнаружение типа сущности и интеллектуальное связывание для людей и компаний.","ar":"مثالي للوكلاء البحثيين الذين يحتاجون إلى كشف نوع الكيان والربط الذكي للأشخاص والشركات."},"recommendation":{"en":"Empowers agents to research and add people or companies to the Database with intelligent linking and relationship discovery, utilizing entity type auto-detection from queries, including emails and person names, and facilitating Telegram-based interactions.","zh":"赋予代理研究和将人员或公司添加到数据库的能力，具有智能链接和关系发现，利用实体类型自动检测来自查询的电子邮件和人名，并通过Telegram实现交互。","ja":"エージェントが人や企業をデータベースに追加し、クエリからの電子メールや人名のエンティティタイプ自動検出を利用して、インテリジェントリンクと関係性の発見を行い、Telegramベースの相互作用を促進します。","ko":"에이전트가 데이터베이스에 사람이나 회사를 추가하고 쿼리에서 이메일 및 사람 이름의 엔티티 유형 자동 감지를 사용하여 지능형链接 및 관계 발견을 수행하며 텔레그램 기반 상호 작용을 가능하게 합니다.","es":"Habilita a los agentes a investigar y agregar personas o empresas a la Base de Datos con enlace inteligente y descubrimiento de relaciones, utilizando la detección automática de tipo de entidad desde consultas, incluyendo correos electrónicos y nombres de personas, y facilitando interacciones basadas en Telegram.","fr":"Permet aux agents de recherche et d''ajouter des personnes ou des entreprises à la Base de Données avec un lien intelligent et une découverte de relations, en utilisant la détection automatique de type d''entité à partir de requêtes, y compris les adresses e-mail et les noms de personnes, et en facilitant les interactions basées sur Telegram.","de":"Ermächtigt die Agenten, Personen oder Unternehmen zu recherchieren und zur Datenbank hinzuzufügen, mit intelligenter Verknüpfung und Beziehungsfindung, unter Nutzung der automatischen Entitätstyp-Erkennung aus Abfragen, einschließlich E-Mails und Personennamen, und unter Berücksichtigung von Telegram-basierten Interaktionen.","pt":"Habilita os agentes a pesquisar e adicionar pessoas ou empresas ao Banco de Dados com linkagem inteligente e descoberta de relacionamentos, utilizando detecção automática de tipo de entidade a partir de consultas, incluindo e-mails e nomes de pessoas, e facilitando interações baseadas no Telegram.","ru":"Наделяет агентов возможностью исследовать и добавлять людей или компании в Базу Данных с интеллектуальным связыванием и открытием отношений, используя автоматическое обнаружение типа сущности из запросов, включая электронные почты и имена людей, и облегчая взаимодействия на основе Telegram.","ar":"يمنح الوكلاء القدرة على البحث وإضافة الأشخاص أو الشركات إلى قاعدة البيانات بالربط الذكي واكتشاف العلاقات، باستخدام الكشف التلقائي عن نوع الكيان من الاستعلامات، بما في ذلك البريد الإلكتروني وأسماء الأشخاص، وتسهيل التفاعلات المستندة إلى تليجرام."},"useCases":{"en":["Researching companies from email domains","Automating person and company data entry","Discovering relationships between entities"],"zh":["通过电子邮件域名研究公司","自动化人员和公司数据输入","发现实体之间的关系"],"ja":["メールドメインから会社を調査する","人や企業のデータ入力を自動化する","エンティティ間の関係を発見する"],"ko":["이메일 도메인에서 회사 검색","사람 및 회사 데이터 입력 자동화","엔티티 간 관계 발견"],"es":["Investigación de empresas a partir de dominios de correo electrónico","Automatización de la entrada de datos de personas y empresas","Descubrimiento de relaciones entre entidades"],"fr":["Recherche d''entreprises à partir de domaines d''adresses e-mail","Automatisation de la saisie de données de personnes et d''entreprises","Découverte de relations entre les entités"],"de":["Untersuchung von Unternehmen anhand von E-Mail-Domains","Automatisierung der Dateneingabe für Personen und Unternehmen","Entdeckung von Beziehungen zwischen Entitäten"],"pt":["Pesquisando empresas a partir de domínios de e-mail","Automatizando a entrada de dados de pessoas e empresas","Descobrindo relacionamentos entre entidades"],"ru":["Исследование компаний по доменам электронной почты","Автоматизация ввода данных о людях и компаниях","Обнаружение отношений между сущностями"],"ar":["البحث عن الشركات من مجالات البريد الإلكتروني","آليّة إدخال بيانات الأشخاص والشركات","اكتشاف العلاقات بين الكيانات"]},"limitations":{"en":["Requires Telegram interaction","Limited to entity types such as emails and person names"],"zh":["需要Telegram交互","仅限于电子邮件和人名等实体类型"],"ja":["Telegramの相互作用が必要","電子メールや人名などのエンティティタイプに限定される"],"ko":["텔레그램 상호작용이 필요","이메일 또는 사람 이름과 같은 엔티티 유형으로 제한"],"es":["Requiere interacción con Telegram","Limitado a tipos de entidades como correos electrónicos y nombres de personas"],"fr":["Nécessite une interaction avec Telegram","Limité à des types d''entités tels que les adresses e-mail et les noms de personnes"],"de":["Benötigt Telegram-Interaktion","Beschränkt auf Entitätstypen wie E-Mails und Personennamen"],"pt":["Requer interação do Telegram","Limitado a tipos de entidades como e-mails e nomes de pessoas"],"ru":["Требует взаимодействия с Telegram","Ограничен типами сущностей, такими как электронные почты и имена людей"],"ar":["يتطلب تفاعلاً مع تليجرام","محدود بنوع الكيان مثل البريد الإلكتروني وأسماء الأشخاص"]},"version":4},"contentHash":"cf5da5bd51680d679353d5183a7140381f94bcaad1c2c341f2272b25c439729f","qualityScore":51}');
