INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bodangren/git-workflow/doc-indexer', 'community', 'bodangren', 'git-workflow', 'bodangren/git-workflow', 'doc-indexer', 0, 0, 51, '2026-03-08T01:57:15.615Z', '2026-03-08T02:14:34.978Z', 'c644f16429f24e3e1e180220fd4eb9fa0703c69d4884b344185d342bb923b753', '{"id":"bodangren/git-workflow/doc-indexer","name":"doc-indexer","description":{"en":"The doc-indexer skill provides just-in-time context about available project documentation, enabling efficient discovery of specs, plans, and other documentation for developers.","zh":"Doc-Indexer 是一个 Spec-Driven Git Workflow 插件，提供实时项目文档上下文，支持 GitHub 集成和 sprint 管理。","ja":"Doc-Indexer は Spec-Driven Git Workflow プラグインであり、プロジェクト文書化の実時間上下文を提供し、GitHub 統合とスプリント管理をサポートします。","ko":"Doc-Indexer는 Spec-Driven Git Workflow 플러그인으로서 실시간 프로젝트 문서 컨텍스트를 제공하며 GitHub 통합 및 스프린트 관리를 지원합니다.","es":"El skill doc-indexer proporciona un flujo de trabajo de Git integral con GitHub, gestión de sprints y soporte para migraciones brownfield","fr":"Le skill doc-indexer fournit un flux de travail Git complet avec GitHub, gestion de sprints et support pour les migrations brownfield","de":"Das doc-indexer-Skill bietet einen umfassenden Git-Workflow mit GitHub, Sprint-Management und Unterstützung für Brownfield-Migrationen","pt":"O doc-indexer é uma ferramenta de indexação de documentos que fornece contexto sobre a documentação do projeto sem carregar o conteúdo completo dos arquivos.","ru":"ИИ Агент doc-indexer - это плагин для Claude Code, который предоставляет контекст о документации проекта без загрузки полного содержания файлов.","ar":"أداة فهرسة الوثائق doc-indexer هي أداة تقدم سياقًا عن وثائق المشروع دون تحميل المحتوى الكامل للملفات."},"seo":{"title":{"en":"doc-indexer: Efficient Documentation Discovery for AI Age...","zh":"Doc-Indexer 设置指南：实时项目文档上下文","ja":"Doc-Indexer 導入ガイド：効率的なプロジェクト文書化","ko":"Doc-In