INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bodangren/git-workflow/doc-indexer', 'doc-indexer', 'bodangren', 'git-workflow', 'community', 'doc-indexer bodangren git-workflow community The doc-indexer skill provides just-in-time context about available project documentation, enabling efficient discovery of specs, plans, and other documentation for developers. Doc-Indexer 是一个 Spec-Driven Git Workflow 插件，提供实时项目文档上下文，支持 GitHub 集成和 sprint 管理。 Doc-Indexer は Spec-Driven Git Workflow プラグインであり、プロジェクト文書化の実時間上下文を提供し、GitHub 統合とスプリント管理をサポートします。 Doc-Indexer는 Spec-Driven Git Workflow 플러그인으로서 실시간 프로젝트 문서 컨텍스트를 제공하며 GitHub 통합 및 스프린트 관리를 지원합니다. El skill doc-indexer proporciona un flujo de trabajo de Git integral con GitHub, gestión de sprints y soporte para migraciones brownfield Le skill doc-indexer fournit un flux de travail Git complet avec GitHub, gestion de sprints et support pour les migrations brownfield Das doc-indexer-Skill bietet einen umfassenden Git-Workflow mit GitHub, Sprint-Management und Unterstützung für Brownfield-Migrationen O doc-indexer é uma ferramenta de indexação de documentos que fornece contexto sobre a documentação do projeto sem carregar o conteúdo completo dos arquivos. ИИ Агент doc-indexer - это плагин для Claude Code, который предоставляет контекст о документации проекта без загрузки полного содержания файлов. أداة فهرسة الوثائق doc-indexer هي أداة تقدم سياقًا عن وثائق المشروع دون تحميل المحتوى الكامل للملفات. how to use doc-indexer what is doc-indexer doc-indexer alternative doc-indexer vs GitHub workflow doc-indexer install doc-indexer setup guide doc-indexer for AI agents GitHub integration with doc-indexer Spec-Driven Git Workflow with doc-indexer Doc-Indexer AIエージェント Spec-Driven Git Workflow GitHub 集成 Sprint 管理 Markdown 文件扫描 YAML 前置元数据提取 Scans all markdown files in the `docs/` directory Extracts YAML frontmatter metadata Returns a structured map of available documentation Supports GitHub integration for comprehensive development workflow Enables efficient discovery of specs, plans, retrospectives, and other documentation Minimizes token usage by not loading full file content into the context window doc-indexer is a Spec-Driven Git Workflow plugin that scans markdown files, extracts YAML frontmatter metadata, and returns a structured map of available documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pjcau/agent-orchestrator/verify', 'community', 'pjcau', 'agent-orchestrator', 'pjcau/agent-orchestrator', 'verify', 0, 0, 51, '2026-03-07T22:27:55Z', '2026-03-08T02:17:50.676Z', '9f4a579627634541c1f8585bdc09dc4a4128ba241a0be4f633d8139bcbab5d7e', '{"id":"pjcau/agent-orchestrator/verify","name":"verify","description":{"en":"Verify is a comprehensive AI agent orchestration framework that enables swapping LLM providers, routing by cost, and mixing cloud and local models. It benefits developers and organizations seeking flexibility and efficiency in AI model deployment.","zh":"Verify AI Agent 是一个供应商无关性框架，支持多云混合部署和成本优化。通过 Verify，您可以轻松地在不同云平台和本地环境之间切换","ja":"Verify AIエージェントは、プロバイダー非依存フレームワークです。複数のクラウドとローカルモデルを混在させることができます","ko":"Verify AI 에이전트는 공급자 독립 프레임워크로 다중 클라우드와 로컬 모델을 혼합하여 배포할 수 있습니다","es":"El framework de verificación es una herramienta para verificar la calidad de los agentes de inteligencia artificial, que incluye comprobaciones de compilación, lint y formato","fr":"L''agent de vérification est un outil pour vérifier la qualité des agents de l''intelligence artificielle, qui inclut des vérifications de construction, de lint et de format","de":"Das Verify-Framework ist ein Werkzeug zur Überprüfung der Qualität von KI-Agents, das Build-, Lint- und Format-Checks umfasst","pt":"O Verify é um framework de orquestração de agentes de IA que permite uma verificação abrangente e flexível. Ele suporta a troca de provedores de LLM e a mistura de modelos em nuvem e locais","ru":"Verify - это рамки для оркестровки ИИ Агентов, которые обеспечивают всестороннюю и гибкую верификацию. Они поддерживают переключение между провайдерами LLM и смешивание облачных и локальных моделей","ar":"Verify هو إطار لتوجيه وكلاء الذكاء الاصطناعي الذي يوفر عمليات التحقق الشاملة والمطورة. يدعم تبديل مزودي LLM ودمج النماذج السحابية والمحلية"},"seo":{"title":{"en":"Verify: AI Agent Orchestration Framework Setup Guide | AI...","zh":"Verify AI Agent 设置指南 - 供应商无关性框架","ja":"Verify AIエージェントの設定方法 - プロバイダー非依存フレームワーク","ko":"Verify AI 에이전트 설정 가이드 - 공급자 독립 프레임워크","es":"Configuración de verificación de agentes de inteligencia ...","fr":"Guide d''installation de l''agent de vérification","de":"Einrichtung des Verify-Frameworks für KI-Agents","pt":"Guia de Configuração do Verify - Framework de Orquestraçã...","ru":"Настройка Verify - Рамки для оркестровки ИИ Агентов","ar":"دليل إعداد Verify - إطار لتوجيه وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock provider-agnostic AI agent orchestration with Verify. Learn how to route by cost and mix cloud and local models for optimal performance. Get started now!","zh":"Verify AI Agent 供应商无关性框架，实现多云混合部署和成本优化，了解更多","ja":"Verify AIエージェントのプロバイダー非依存フレームワークを使用して、コストとパフォーマンスを最適化する","ko":"Verify AI 에이전트 공급자 독립 프레임워크로 다중 클라우드 混合 배포와 비용 최적화를 구현하세요","es":"Aprende a configurar el framework de verificación de agentes de inteligencia artificial para optimizar tus flujos de trabajo","fr":"Découvrez comment installer et configurer l''agent de vérification pour améliorer vos processus","de":"Erfahren Sie, wie Sie das Verify-Framework für KI-Agents einrichten und Ihre Workflows optimieren","pt":"Aprenda a configurar o Verify, um framework de orquestração de agentes de IA que permite trocar provedores de LLM, rotear por custo e misturar modelos em nuv...","ru":"Узнайте, как настроить Verify, рамки для оркестровки ИИ Агентов, которые позволяют переключаться между провайдерами LLM, маршрутизировать по стоимости и смеш...","ar":"تعرف على كيفية إعداد Verify، إطار لتوجيه وكلاء الذكاء الاصطناعي الذي يسمح بتبديل مزودي LLM، وتوجيه حسب التكلفة، ودمج النماذج السحابية والمحلية"},"definition":{"en":"Verify is a provider-agnostic AI agent orchestration framework that adapts the verification-loop pattern for comprehensive testing and deployment.","zh":"Verify AI Agent 是一个用于验证和优化 AI 模型的框架","ja":"Verify AIエージェントは、AI モデルの検証と最適化を行うためのフレームワークです","ko":"Verify AI 에이전트는 AI 모델의 검증과 최적화를 위한 프레임워크입니다","es":"El framework de verificación es un conjunto de herramientas para verificar la calidad de los agentes de inteligencia artificial","fr":"L''agent de vérification est un ensemble d''outils pour vérifier la qualité des agents de l''intelligence artificielle","de":"Das Verify-Framework ist eine Sammlung von Tools zur Überprüfung der Qualität von KI-Agents","pt":"O Verify é um framework de orquestração de agentes de IA que executa verificações abrangentes em várias fases","ru":"Verify - это рамки для оркестровки ИИ Агентов, которые выполняют всестороннюю верификацию на нескольких этапах","ar":"Verify هو إطار لتوجيه وكلاء الذكاء الاصطناعي الذي يقوم بالتحقق الشامل في مراحل متعددة"},"features":{"en":["Build and import check using `docker compose run --rm app python -c \"import agent_orchestrator; print(''OK'')\"`","Linting using `docker compose run --rm lint` to report errors","Format check using `docker compose run --rm format` for code consistency","Testing in Phase 4 for thorough verification"],"zh":["支持多云混合部署","实现成本优化和路由","提供 Python 和 Docker Compose 集成","支持 lint 和格式检查","提供测试和验证功能"],"ja":["複数のクラウドとローカルモデルを混在させる","コスト最適化とルーティングを実現","Python と Docker Compose をサポート","Lint とフォーマットチェックを提供","テストと検証機能を提供"],"ko":["다중 클라우드와 로컬 모델을 혼합하여 배포","비용 최적화와 라우팅을 구현","Python과 Docker Compose를 지원","lint와 형식 확인을 제공","테스트와 검증 기능을 제공"],"es":["Comprobación de compilación con Docker Compose","Análisis de lint para detectar errores","Comprobación de formato para garantizar la coherencia","Soporte para múltiples proveedores de LLM","Enrutamiento por coste para optimizar los recursos","Compatibilidad con modelos en la nube y locales"],"fr":["Vérification de construction avec Docker Compose","Analyse de lint pour détecter les erreurs","Vérification de format pour garantir la cohérence","Prise en charge de plusieurs fournisseurs de LLM","Acheminement par coût pour optimiser les ressources","Compatibilité avec les modèles en nuage et locaux"],"de":["Build-Check mit Docker Compose","Lint-Analyse zur Fehlererkennung","Format-Check zur Gewährleistung der Konsistenz","Unterstützung für mehrere LLM-Anbieter","Kostenoptimiertes Routing","Kompatibilität mit Cloud- und lokalen Modellen"],"pt":["Suporte à troca de provedores de LLM","Roteamento por custo","Mistura de modelos em nuvem e locais","Verificação em várias fases (Build, Lint, Format, Test)","Utilização de Docker Compose para execução de comandos","Suporte à importação de módulos Python"],"ru":["Поддержка переключения между провайдерами LLM","Маршрутизация по стоимости","Смешивание облачных и локальных моделей","Верификация на нескольких этапах (Build, Lint, Format, Test)","Использование Docker Compose для выполнения команд","Поддержка импорта модулей Python"],"ar":["دعم تبديل مزودي LLM","توجيه حسب التكلفة","دمج النماذج السحابية والمحلية","التحقق في مراحل متعددة (Build, Lint, Format, Test)","استخدام Docker Compose لتشغيل الأوامر","دعم استيراد وحدات Python"]},"keywords":{"en":["how to use verify","verify alternative","verify setup guide","what is verify","verify vs other frameworks","verify install","ai agent orchestration","llm provider routing","cloud and local model mixing"],"zh":["AI Agent","供应商无关性框架","多云混合部署","成本优化","Python","Docker Compose","lint","格式检查","测试和验证"],"ja":["AIエージェント","プロバイダー非依存フレームワーク","クラウドとローカルモデル","コスト最適化","Python","Docker Compose","Lint","フォーマットチェック","テストと検証"],"ko":["AI 에이전트","공급자 독립 프레임워크","다중 클라우드와 로컬 모델","비용 최적화","Python","Docker Compose","lint","형식 확인","테스트와 검증"],"es":["agentes de inteligencia artificial","framework de verificación","verificación de calidad","Docker Compose","lint","formato","proveedores de LLM","enrutamiento por coste"],"fr":["agents de l''intelligence artificielle","agent de vérification","vérification de qualité","Docker Compose","lint","format","fournisseurs de LLM","acheminement par coût"],"de":["KI-Agents","Verify-Framework","Qualitätsüberprüfung","Docker Compose","Lint","Format","LLM-Anbieter","kostenoptimiertes Routing"],"pt":["orquestração de agentes de IA","framework de verificação","LLM","nuvem","locar","Docker Compose","Python","verificação em várias fases"],"ru":["оркестровка ИИ Агентов","рамки для верификации","LLM","облачные","локальные","Docker Compose","Python","верификация на нескольких этапах"],"ar":["توجيه وكلاء الذكاء الاصطناعي","إطار التحقق","LLM","سحابي","محلي","Docker Compose","Python","التحقق في مراحل متعددة"]}},"owner":"pjcau","repo":"agent-orchestrator","repoPath":"pjcau/agent-orchestrator","stars":0,"forks":0,"updatedAt":"2026-03-07T22:27:55Z","topics":[],"category":"community","skillMd":{"name":"verify","description":"Run comprehensive pre-PR verification (tests, lint, format, docs sync, security scan, diff review). Use before creating PRs or after significant changes.","bodyPreview":"# Verify — Pre-PR Quality Gate\n\nComprehensive verification loop adapted from flatrick/everything-claude-code verification-loop pattern.\n\n## Phase 1: Build / Import Check\n```bash\ndocker compose run --rm app python -c \"import agent_orchestrator; print(''OK'')\"\n```\nIf this fails, STOP and fix before continuing.\n\n## Phase 2: Lint\n```bash\ndocker compose run --rm lint\n```\nReport all lint errors. Fix before continuing.\n\n## Phase 3: Format Check\n```bash\ndocker compose run --rm format\n```\n\n## Phase 4: Test","body":"# Verify — Pre-PR Quality Gate\n\nComprehensive verification loop adapted from flatrick/everything-claude-code verification-loop pattern.\n\n## Phase 1: Build / Import Check\n```bash\ndocker compose run --rm app python -c \"import agent_orchestrator; print(''OK'')\"\n```\nIf this fails, STOP and fix before continuing.\n\n## Phase 2: Lint\n```bash\ndocker compose run --rm lint\n```\nReport all lint errors. Fix before continuing.\n\n## Phase 3: Format Check\n```bash\ndocker compose run --rm format\n```\n\n## Phase 4: Test Suite\n```bash\ndocker compose run --rm test\n```\nReport:\n- Total tests\n- Passed / Failed\n- Any warnings\n\n## Phase 5: Security Scan\n```bash\n# Check for secrets in tracked files\ngrep -rn \"sk-\\|api_key\\s*=\\s*[''\\\"]\" --include=\"*.py\" src/ tests/ 2>/dev/null | head -10\n# Check for hardcoded passwords\ngrep -rn \"password\\s*=\\s*[''\\\"]\" --include=\"*.py\" src/ 2>/dev/null | grep -v \"test\\|example\\|orchestrator\" | head -10\n```\n\n## Phase 6: Diff Review\n```bash\ngit diff --stat\ngit diff HEAD --name-only\n```\nReview each changed file for:\n- Unintended changes\n- Missing error handling\n- Potential security issues\n\n## Output Format\n\nAfter running all phases, produce a verification report:\n\n```\nVERIFICATION REPORT\n==================\nImport:    [PASS/FAIL]\nLint:      [PASS/FAIL] (details)\nFormat:    [PASS/FAIL]\nTests:     [PASS/FAIL] (X passed, Y warnings)\nSecurity:  [PASS/FAIL] (X issues)\nDiff:      [X files changed]\n\nOverall:   [READY/NOT READY] for PR\n\nIssues to Fix:\n1. ...\n```\n\n## When to Run\n\n- Before every PR\n- After refactoring\n- After adding new dependencies\n- After significant code changes\n"},"lastSynced":"2026-03-08T02:17:50.676Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing comprehensive content analysis and verification capabilities for efficient model deployment.","zh":"适合需要全面内容分析和验证功能以实现高效模型部署的AI代理。","ja":"包括的モデル展開のための包括的なコンテンツ分析および検証機能を必要とするAIエージェントに最適です。","ko":"전면적인 콘텐츠 분석 및 검증 기능이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades de análisis y verificación de contenido integral para una implementación de modelo eficiente.","fr":"Parfait pour les agents IA nécessitant une analyse et une vérification de contenu complètes pour un déploiement de modèle efficace.","de":"Perfekt für KI-Agents, die umfassende Inhaltsanalyse- und Verifizierungsfunktionen für eine effiziente Modellbereitstellung benötigen.","pt":"Perfeito para Agentes de IA que necessitam de capacidades de análise e verificação de conteúdo abrangentes para implantação eficiente de modelos.","ru":"Идеально подходит для агентов ИИ, которым необходимы всесторонние возможности анализа и проверки контента для эффективного развертывания моделей.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى قدرات تحليل و 驗證 المحتوى الشامل لتنفيذ نموذج فعال."},"recommendation":{"en":"Empowers agents to orchestrate LLM providers, route by cost, and mix cloud and local models using docker compose, ensuring flexibility and efficiency in AI model deployment with Python and agent_orchestrator.","zh":"赋予代理能力以编排LLM提供商，按成本路由，并使用docker compose混合云和本地模型，确保使用Python和agent_orchestrator的AI模型部署的灵活性和效率。","ja":"LLMプロバイダーのオーケストレーション、コストによるルーティング、およびdocker composeを使用したクラウドおよびローカルモデルの混合化を可能にし、Pythonおよびagent_orchestratorを使用したAIモデルの展開における柔軟性および効率を確保します。","ko":"LLM 제공업체의 오케스트레이션, 비용에 따른 라우팅 및 docker compose를 사용한 클라우드 및 로컬 모델의 혼합을 가능하게 하며 Python 및 agent_orchestrator를 사용한 AI 모델 배포의 유연성 및 효율성을 보장합니다.","es":"Habilita a los agentes a orquestar proveedores de LLM, enrutamiento por costo y mezcla de modelos en la nube y locales usando docker compose, asegurando flexibilidad y eficiencia en la implementación de modelos de IA con Python y agent_orchestrator.","fr":"Permet aux agents d''orchestrer les fournisseurs LLM, de router par coût et de mélanger les modèles cloud et locaux à l''aide de docker compose, garantissant ainsi flexibilité et efficacité dans le déploiement de modèles d''IA avec Python et agent_orchestrator.","de":"Ermöglicht es Agenten, LLM-Anbieter zu orchestrieren, Routing nach Kosten und Mischen von Cloud- und lokalen Modellen mit docker compose zu nutzen, um Flexibilität und Effizienz bei der Bereitstellung von KI-Modellen mit Python und agent_orchestrator sicherzustellen.","pt":"Habilita os agentes a orquestrar provedores de LLM, rotear pelo custo e misturar modelos de nuvem e locais usando docker compose, garantindo flexibilidade e eficiência na implantação de modelos de IA com Python e agent_orchestrator.","ru":"Позволяет агентам оркестрировать провайдеров LLM, маршрутизировать по стоимости и смешивать облачные и локальные модели с помощью docker compose, обеспечивая гибкость и эффективность в развертывании моделей ИИ с Python и agent_orchestrator.","ar":"يُمكّن الوكلاء من تنسيق مزودي LLM و التوجيه حسب التكلفة و مزج النماذج السحابية و المحلية باستخدام docker compose، و ضمان المرونة و الفاعلية في تنفيذ نموذج الذكاء الاصطناعي مع Python و agent_orchestrator."},"useCases":{"en":["Automating model deployment verification","Debugging LLM integration issues","Optimizing model routing by cost"],"zh":["自动化模型部署验证","调试LLM集成问题","优化模型路由以降低成本"],"ja":["モデルの展開の検証を自動化する","LLMの統合問題をデバッグする","コストによるモデルルーティングの最適化"],"ko":["모델 배포 검증 자동화","LLM 통합 문제 디버깅","비용에 따른 모델 라우팅 최적화"],"es":["Automatización de la verificación de la implementación de modelos","Depuración de problemas de integración de LLM","Optimización del enrutamiento de modelos por costo"],"fr":["Automatisation de la vérification du déploiement de modèles","Débogage des problèmes d''intégration de LLM","Optimisation du routage de modèles par coût"],"de":["Automatisierung der Überprüfung der Modellbereitstellung","Fehlerbehebung bei LLM-Integrationsproblemen","Optimierung der Modellrouting nach Kosten"],"pt":["Automatizar verificação de implantação de modelos","Depurar problemas de integração de LLM","Otimizar roteamento de modelos por custo"],"ru":["Автоматизировать проверку развертывания моделей","Отладить проблемы интеграции LLM","Оптимизировать маршрутизацию моделей по стоимости"],"ar":["أتمتة التحقق من تنفيذ النماذج","تصحيح مشاكل التكامل LLM","تحسين التوجيه النموذجي حسب التكلفة"]},"limitations":{"en":["Requires docker compose setup","Python environment needed","Limited to LLM providers supported by agent_orchestrator"],"zh":["需要docker compose设置","需要Python环境","仅限agent_orchestrator支持的LLM提供商"],"ja":["docker composeの設定が必要","Python環境が必要","agent_orchestratorでサポートされているLLMプロバイダーに限定"],"ko":["docker compose 설정 필요","Python 환경 필요","agent_orchestrator에서 지원하는 LLM 제공업체로 제한"],"es":["Requiere configuración de docker compose","Entorno de Python necesario","Limitado a proveedores de LLM compatibles con agent_orchestrator"],"fr":["Nécessite une configuration de docker compose","Environnement Python requis","Limité aux fournisseurs LLM pris en charge par agent_orchestrator"],"de":["Benötigt docker compose-Einrichtung","Python-Umgebung erforderlich","Begrenzt auf LLM-Anbieter, die von agent_orchestrator unterstützt werden"],"pt":["Requer configuração do docker compose","Ambiente Python necessário","Limitado a provedores de LLM suportados pelo agent_orchestrator"],"ru":["Требует настройки docker compose","Необходимо окружение Python","Ограничен провайдерами LLM, поддерживаемыми agent_orchestrator"],"ar":["يتطلب إعداد docker compose","بيئة Python ضرورية","محدود بمزودي LLM المدعومين من قبل agent_orchestrator"]},"version":4},"contentHash":"9f4a579627634541c1f8585bdc09dc4a4128ba241a0be4f633d8139bcbab5d7e","qualityScore":51}');
