INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pjcau/agent-orchestrator/verify', 'verify', 'pjcau', 'agent-orchestrator', 'community', 'verify pjcau agent-orchestrator community Verify is a comprehensive AI agent orchestration framework that enables swapping LLM providers, routing by cost, and mixing cloud and local models. It benefits developers and organizations seeking flexibility and efficiency in AI model deployment. Verify AI Agent 是一个供应商无关性框架，支持多云混合部署和成本优化。通过 Verify，您可以轻松地在不同云平台和本地环境之间切换 Verify AIエージェントは、プロバイダー非依存フレームワークです。複数のクラウドとローカルモデルを混在させることができます Verify AI 에이전트는 공급자 독립 프레임워크로 다중 클라우드와 로컬 모델을 혼합하여 배포할 수 있습니다 El framework de verificación es una herramienta para verificar la calidad de los agentes de inteligencia artificial, que incluye comprobaciones de compilación, lint y formato L''agent de vérification est un outil pour vérifier la qualité des agents de l''intelligence artificielle, qui inclut des vérifications de construction, de lint et de format Das Verify-Framework ist ein Werkzeug zur Überprüfung der Qualität von KI-Agents, das Build-, Lint- und Format-Checks umfasst O Verify é um framework de orquestração de agentes de IA que permite uma verificação abrangente e flexível. Ele suporta a troca de provedores de LLM e a mistura de modelos em nuvem e locais Verify - это рамки для оркестровки ИИ Агентов, которые обеспечивают всестороннюю и гибкую верификацию. Они поддерживают переключение между провайдерами LLM и смешивание облачных и локальных моделей Verify هو إطار لتوجيه وكلاء الذكاء الاصطناعي الذي يوفر عمليات التحقق الشاملة والمطورة. يدعم تبديل مزودي LLM ودمج النماذج السحابية والمحلية how to use verify verify alternative verify setup guide what is verify verify vs other frameworks verify install ai agent orchestration llm provider routing cloud and local model mixing AI Agent 供应商无关性框架 多云混合部署 成本优化 Python Docker Compose lint 格式检查 测试和验证 Build and import check using `docker compose run --rm app python -c "import agent_orchestrator; print(''OK'')"` Linting using `docker compose run --rm lint` to report errors Format check using `docker compose run --rm format` for code consistency Testing in Phase 4 for thorough verification Verify is a provider-agnostic AI agent orchestration framework that adapts the verification-loop pattern for comprehensive testing and deployment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zzstoatzz/pdsx/cli', 'community', 'zzstoatzz', 'pdsx', 'zzstoatzz/pdsx', 'cli', 0, 0, 51, '2026-03-06T06:23:00.164Z', '2026-03-06T07:27:03.307Z', '7db0d5242e9a444674fad147c6ded8bf13b86ed34c22c15ccfe8adaa9534ca6c', '{"id":"zzstoatzz/pdsx/cli","name":"cli","description":{"en":"The cli skill enables ATProto record CRUD operations for developers, allowing them to perform create, read, update, and delete actions using uvx pdsx commands","zh":"CLI 用于 ATProto 记录 CRUD 操作，支持读取和写入操作","ja":"CLI は ATProto レコードの CRUD 操作をサポートします","ko":"CLI는 ATProto 레코드 CRUD 연산을 지원합니다","es":"La CLI de ATProto permite operaciones de registro CRUD con autenticación y comandos personalizados. Utilice comandos como `uvx pdsx` para interactuar con el registro.","fr":"La CLI d''ATProto permet des opérations de registre CRUD avec authentification et commandes personnalisées. Utilisez des commandes comme `uvx pdsx` pour interagir avec le registre.","de":"Die ATProto-CLI ermöglicht CRUD-Registrierungsoperationen mit Authentifizierung und benutzerdefinierten Befehlen. Verwenden Sie Befehle wie `uvx pdsx`, um mit dem Register zu interagieren.","pt":"A CLI do ATProto permite operações de CRUD em registros com autenticação e comandos personalizados","ru":"ИИ Агент CLI для ATProto позволяет выполнять операции CRUD с записями, используя аутентификацию и настраиваемые команды","ar":"واجهة سطر الأوامر CLI للات بروتو تسمح بالعمليات CRUD على السجلات باستخدام المصادقة والأوامر المخصصة"},"seo":{"title":{"en":"cli: ATProto Record CRUD Setup Guide | AI Agent Skill","zh":"CLI_SETUP GUIDE: ATProto 记录 CRUD 操作","ja":"CLI セットアップガイド: ATProto レコード CRUD 操作","ko":"CLI 설정 가이드: ATProto 레코드 CRUD 연산","es":"Guía de configuración de CLI para ATProto","fr":"Guide de mise en place de CLI pour ATProto","de":"CLI-Setup-Anleitung für ATProto","pt":"Guia de Configuração CLI para ATProto","ru":"Настройка ИИ Агента CLI для ATProto","ar":"دليل إعداد واجهة سطر الأوامر CLI للات بروتو"},"description":{"en":"Unlock ATProto record operations with cli. Learn how to use uvx pdsx for CRUD actions and discover the power of ATProto handle authentication","zh":"了解如何使用 CLI 进行 ATProto 记录 CRUD 操作，包括读取和写入操作","ja":"CLI を使用して ATProto レコードの CRUD 操作を実行する方法について学びます","ko":"CLI를 사용하여 ATProto 레코드 CRUD 연산을 수행하는 방법에 대해 알아보세요","es":"Aprende a utilizar la CLI de ATProto para operaciones de registro CRUD con autenticación y comandos personalizados","fr":"Découvrez comment utiliser la CLI d''ATProto pour les opérations de registre CRUD avec authentification et commandes personnalisées","de":"Erfahren Sie, wie Sie die ATProto-CLI für CRUD-Registrierungsoperationen mit Authentifizierung und benutzerdefinierten Befehlen verwenden","pt":"Aprenda a utilizar a CLI para operações de CRUD em registros ATProto com autenticação e comandos personalizados","ru":"Узнайте, как использовать ИИ Агент CLI для операций CRUD с записями ATProto, а также об аутентификации и настраиваемых командах","ar":"تعلم كيفية استخدام واجهة سطر الأوامر CLI لأداء عمليات CRUD على السجلات ATProto مع المصادقة والأوامر المخصصة"},"definition":{"en":"cli is a command-line interface for ATProto record operations, providing a straightforward way to interact with ATProto records using uvx pdsx","zh":"CLI 是一种用于 ATProto 记录 CRUD 操作的命令行工具","ja":"CLI は ATProto レコードの CRUD 操作用のコマンドラインツールです","ko":"CLI는 ATProto 레코드 CRUD 연산을 위한 명령줄 도구입니다","es":"La CLI de ATProto es una herramienta de línea de comandos para interactuar con el registro ATProto","fr":"La CLI d''ATProto est un outil de ligne de commande pour interagir avec le registre ATProto","de":"Die ATProto-CLI ist ein Befehlszeilen-Tool zur Interaktion mit dem ATProto-Register","pt":"CLI é uma interface de linha de comando para gerenciar registros ATProto","ru":"ИИ Агент CLI - это интерфейс командной строки для управления записями ATProto","ar":"واجهة سطر الأوامر CLI هي واجهة سطر أوامر لإدارة السجلات ATProto"},"features":{"en":["Supports ATProto record CRUD operations using uvx pdsx commands","Enables authentication for write operations using --handle and --password","Allows setting environment variables ATPROTO_HANDLE and ATPROTO_PASSWORD","Performs read operations without authentication using -r/--repo","Supports creating records with custom text using the create command","Lists records using the ls command"],"zh":["支持读取和写入 ATProto 记录","使用 `uvx pdsx` 命令进行 CRUD 操作","支持设置环境变量 `ATPROTO_HANDLE` 和 `ATPROTO_PASSWORD`","支持使用 `--handle` 和 `--password` 参数进行认证","支持使用 `ls` 命令列出记录","支持使用 `create` 命令创建新记录"],"ja":["ATProto レコードの読み取りと書き込みをサポート","CRUD 操作用の `uvx pdsx` コマンド","環境変数 `ATPROTO_HANDLE` と `ATPROTO_PASSWORD` を設定することをサポート","認証用の `--handle` と `--password` パラメータをサポート","レコードを一覧するための `ls` コマンド","新しいレコードを作成するための `create` コマンド"],"ko":["ATProto 레코드 읽기 및 쓰기 지원","CRUD 연산을 위한 `uvx pdsx` 명령","환경 변수 `ATPROTO_HANDLE` 및 `ATPROTO_PASSWORD` 설정 지원","인증을 위한 `--handle` 및 `--password` 매개 변수 지원","레코드 목록을 위한 `ls` 명령","새 레코드 생성을 위한 `create` 명령"],"es":["Soporte para operaciones de registro CRUD","Autenticación mediante handle y contraseña","Comandos personalizados como `uvx pdsx`","Compatibilidad con variables de entorno como `ATPROTO_HANDLE` y `ATPROTO_PASSWORD`","Lecturas sin autenticación requerida"],"fr":["Prise en charge des opérations de registre CRUD","Authentification via handle et mot de passe","Commandes personnalisées comme `uvx pdsx`","Compatibilité avec des variables d''environnement comme `ATPROTO_HANDLE` et `ATPROTO_PASSWORD`","Lectures sans authentification requise"],"de":["Unterstützung für CRUD-Registrierungsoperationen","Authentifizierung über Handle und Passwort","Benutzerdefinierte Befehle wie `uvx pdsx`","Kompatibilität mit Umgebungsvariablen wie `ATPROTO_HANDLE` und `ATPROTO_PASSWORD`","Lesevorgänge ohne erforderliche Authentifizierung"],"pt":["Suporte a operações de CRUD em registros ATProto","Autenticação com handle e senha","Comandos personalizados para criar, ler, atualizar e excluir registros","Suporte a variáveis de ambiente para autenticação","Comandos como ls, create, update e delete"],"ru":["Поддержка операций CRUD с записями ATProto","Аутентификация с помощью хэндла и пароля","Настраиваемые команды для создания, чтения, обновления и удаления записей","Поддержка переменных окружения для аутентификации","Команды như ls, create, update и delete"],"ar":["دعم عمليات CRUD على السجلات ATProto","المصادقة باستخدام المحامل وكلمة المرور","أوامر مخصصة لإنشاء وقراءة وتحديث وحذف السجلات","دعم متغيرات البيئة للمصادقة","أوامر مثل ls و create و update و delete"]},"keywords":{"en":["how to use cli for ATProto","cli vs ATProto API","cli install guide","what is cli in ATProto","cli alternative for record operations","cli setup for ATProto development","ATProto record CRUD tutorial","cli authentication for ATProto","uvx pdsx commands for cli"],"zh":["CLI","ATProto","CRUD 操作","命令行工具","环境变量","认证","AI 工具","AI开发"],"ja":["CLI","ATProto","CRUD 操作","コマンドラインツール","環境変数","認証","AI エージェント","AI 開発"],"ko":["CLI","ATProto","CRUD 연산","명령줄 도구","환경 변수","인증","AI 에이전트","AI 개발"],"es":["CLI de ATProto","operaciones de registro CRUD","autenticación en CLI","comandos personalizados en CLI","variables de entorno en CLI","herramientas de línea de comandos","ATProto registro","desarrollo de software"],"fr":["CLI d''ATProto","opérations de registre CRUD","authentification en CLI","commandes personnalisées en CLI","variables d''environnement en CLI","outils de ligne de commande","registre ATProto","développement de logiciels"],"de":["ATProto-CLI","CRUD-Registrierungsoperationen","Authentifizierung in der CLI","benutzerdefinierte Befehle in der CLI","Umgebungsvariablen in der CLI","Befehlszeilen-Tools","ATProto-Register","Software-Entwicklung"],"pt":["CLI ATProto","operacoes CRUD","autenticacao CLI","comandos personalizados CLI","variaveis de ambiente CLI","ATProto registro","gerenciamento de registros","interface de linha de comando"],"ru":["ИИ Агент CLI ATProto","операции CRUD","аутентификация ИИ Агента","настраиваемые команды ИИ Агента","переменные окружения ИИ Агента","АТProto запись","управление записями","интерфейс командной строки"],"ar":["واجهة سطر الأوامر CLI للات بروتو","عمليات CRUD","المصادقة واجهة سطر الأوامر","أوامر مخصصة واجهة سطر الأوامر","متغيرات البيئة واجهة سطر الأوامر","سجل الات بروتو","إدارة السجلات","واجهة سطر أوامر"]}},"owner":"zzstoatzz","repo":"pdsx","repoPath":"zzstoatzz/pdsx","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.164Z","topics":[],"category":"community","skillMd":{"name":"cli","description":"Use the pdsx CLI for ATProto record operations. Requires auth for writes, supports batch operations via stdin.","bodyPreview":"# pdsx CLI\n\nUse `uvx pdsx` (or `uv run pdsx` for local dev) for ATProto record operations.\n\n## Authentication\n\nReads don''t need auth, just `-r/--repo`. Writes need `--handle` and `--password`:\n\n```bash\n# reads - no auth\nuvx pdsx -r someone.bsky.social ls app.bsky.feed.post\n\n# writes - auth required\nuvx pdsx --handle you.bsky.social --password xxxx-xxxx create app.bsky.feed.post text=''hello''\n```\n\nYou can also set env vars: `ATPROTO_HANDLE`, `ATPROTO_PASSWORD`\n\n## Commands\n\n| Command | Aliases | D","body":"# pdsx CLI\n\nUse `uvx pdsx` (or `uv run pdsx` for local dev) for ATProto record operations.\n\n## Authentication\n\nReads don''t need auth, just `-r/--repo`. Writes need `--handle` and `--password`:\n\n```bash\n# reads - no auth\nuvx pdsx -r someone.bsky.social ls app.bsky.feed.post\n\n# writes - auth required\nuvx pdsx --handle you.bsky.social --password xxxx-xxxx create app.bsky.feed.post text=''hello''\n```\n\nYou can also set env vars: `ATPROTO_HANDLE`, `ATPROTO_PASSWORD`\n\n## Commands\n\n| Command | Aliases | Description |\n|---------|---------|-------------|\n| `list` | `ls` | list records in a collection |\n| `get` | `cat` | get a specific record |\n| `create` | `touch`, `add` | create record(s) |\n| `update` | `edit` | update record(s) |\n| `delete` | `rm` | delete record(s) |\n| `upload-blob` | - | upload image/video |\n| `whoami` | `me`, `identity` | show authenticated identity |\n\n## Examples\n\n```bash\n# list posts from someone\nuvx pdsx -r zzstoatzz.io ls app.bsky.feed.post\n\n# get a specific post\nuvx pdsx get at://did:plc:xxx/app.bsky.feed.post/abc123\n\n# get someone''s profile\nuvx pdsx -r zzstoatzz.io get app.bsky.actor.profile/self\n\n# create a post\nuvx pdsx --handle you.bsky.social --password $APP_PASSWORD create app.bsky.feed.post text=''hello from pdsx''\n\n# check who you''re authenticated as\nuvx pdsx --handle you.bsky.social --password $APP_PASSWORD whoami\n\n# delete a post\nuvx pdsx --handle you.bsky.social --password $APP_PASSWORD rm at://did:plc:xxx/app.bsky.feed.post/abc123\n```\n\n## Batch Operations\n\nPipe JSONL to stdin for batch operations:\n\n```bash\n# batch create\necho ''{\"text\":\"post 1\"}\n{\"text\":\"post 2\"}'' | uvx pdsx --handle ... create app.bsky.feed.post\n\n# batch delete\necho ''at://did:plc:xxx/app.bsky.feed.post/abc123\nat://did:plc:xxx/app.bsky.feed.post/def456'' | uvx pdsx --handle ... rm\n\n# batch update (JSONL with uri field)\necho ''{\"uri\":\"at://...\",\"text\":\"updated text\"}'' | uvx pdsx --handle ... update\n```\n\n## Output Formats\n\nUse `-o/--output` for different formats:\n\n```bash\nuvx pdsx -r someone.bsky.social ls app.bsky.feed.post -o json\nuvx pdsx -r someone.bsky.social ls app.bsky.feed.post -o yaml\nuvx pdsx -r someone.bsky.social ls app.bsky.feed.post -o table\nuvx pdsx -r someone.bsky.social ls app.bsky.feed.post -o compact  # default for list\n```\n\n## Common Collections\n\n| Collection | Purpose |\n|------------|---------|\n| `app.bsky.feed.post` | posts |\n| `app.bsky.actor.profile` | profile (rkey is `self`) |\n| `app.bsky.feed.like` | likes |\n| `app.bsky.feed.repost` | reposts |\n| `app.bsky.graph.follow` | follows |\n"},"lastSynced":"2026-03-06T07:27:03.307Z","agentAnalysis":{"suitability":{"en":"Ideal for ATProto-based AI Agents requiring low-level record manipulation via command-line interfaces.","zh":"适用于需要通过命令行接口进行低级记录操作的ATProto-based AI Agents。","ja":"コマンドラインインターフェイス経由で低レベルのレコード操作を必要とするATProtoベースのAIエージェントに最適。","ko":"명령줄 인터페이스를 통해 낮은 수준의 레코드 조작이 필요한 ATProto 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de AI basados en ATProto que requieren manipulación de registros de bajo nivel a través de interfaces de línea de comandos.","fr":"Idéal pour les agents d''IA basés sur ATProto nécessitant une manipulation de registres de bas niveau via des interfaces de ligne de commande.","de":"Ideal für ATProto-basierte KI-Agents, die eine Manipulation von Registrierungen auf niedriger Ebene über Kommandozeilen-Schnittstellen benötigen.","pt":"Ideal para Agentes de IA baseados em ATProto que exigem manipulação de registros de baixo nível via interfaces de linha de comando.","ru":"Идеально для агентов ИИ на основе ATProto, требующих манипуляции записями низкого уровня через командную строку.","ar":"مثالي لعمليات الوكيل الذكي التي تقوم على ATProto والتي تتطلب مаниبуляت السجلات منخفضة المستوى عبر واجهات سطر الأوامر."},"recommendation":{"en":"Empowers agents to perform CRUD operations using uvx pdsx commands, enabling seamless interaction with ATProto records through authenticated writes and unauthenticated reads, leveraging environment variables like ATPROTO_HANDLE and ATPROTO_PASSWORD for secure authentication.","zh":"赋予代理执行CRUD操作的能力，使用uvx pdsx命令，实现与ATProto记录的无缝交互，通过环境变量如ATPROTO_HANDLE和ATPROTO_PASSWORD进行安全的身份验证。","ja":"uvx pdsxコマンドを使用してCRUD操作を実行する機能をエージェントに与え、ATPROTO_HANDLEおよびATPROTO_PASSWORDなどの環境変数を使用して認証された書き込みおよび認証されていない読み取りを介してATProtoレコードとのシームレスなやり取りを可能にします。","ko":"uvx pdsx 명령을 사용하여 CRUD 작업을 수행할 수 있는 능력을 에이전트에게 부여하여, ATPROTO_HANDLE 및 ATPROTO_PASSWORD 등의 환경 변수를 사용하여 인증된 쓰기 및 인증되지 않은 읽기를 통해 ATProto 레코드와의 無縫な 상호 작용을 가능하게 합니다.","es":"Habilita a los agentes a realizar operaciones CRUD utilizando comandos uvx pdsx, lo que permite una interacción fluida con los registros de ATProto a través de escrituras autenticadas y lecturas no autenticadas, aprovechando variables de entorno como ATPROTO_HANDLE y ATPROTO_PASSWORD para una autenticación segura.","fr":"Permet aux agents d''effectuer des opérations CRUD en utilisant des commandes uvx pdsx, permettant une interaction transparente avec les enregistrements ATProto via des écritures authentifiées et des lectures non authentifiées, en exploitant des variables d''environnement comme ATPROTO_HANDLE et ATPROTO_PASSWORD pour une authentification sécurisée.","de":"Ermächtigt die Agents, CRUD-Operationen mit uvx pdsx-Befehlen durchzuführen, wodurch eine nahtlose Interaktion mit ATProto-Registrierungen über authentifizierte Schreibvorgänge und nicht authentifizierte Lesevorgänge ermöglicht wird, indem Umgebungsvariablen wie ATPROTO_HANDLE und ATPROTO_PASSWORD für eine sichere Authentifizierung genutzt werden.","pt":"Habilita os agentes a executar operações CRUD usando comandos uvx pdsx, permitindo interação sem problemas com registros ATProto por meio de escritas autenticadas e leituras não autenticadas, utilizando variáveis de ambiente como ATPROTO_HANDLE e ATPROTO_PASSWORD para autenticação segura.","ru":"Наделяет агентов возможностью выполнять операции CRUD с помощью команд uvx pdsx, обеспечивая бесшовное взаимодействие с записями ATProto посредством аутентифицированных записей и неаутентифицированных чтений, используя переменные среды, такие как ATPROTO_HANDLE и ATPROTO_PASSWORD, для безопасной аутентификации.","ar":"تمكّن الوكيل من تنفيذ عمليات CRUD باستخدام أوامر uvx pdsx، وتمكين التفاعل السلس مع سجلات ATProto من خلال الكتابة المُوثقة والقراءات غير المُوثقة، واستخدام متغيرات البيئة مثل ATPROTO_HANDLE وATPROTO_PASSWORD للتحقق من الصحة الآمن."},"useCases":{"en":["Automating ATProto record creation with authenticated writes","Debugging record updates using uvx pdsx commands","Listing app.bsky.feed.post records with unauthenticated reads"],"zh":["使用认证写入进行ATProto记录自动创建","使用uvx pdsx命令进行记录更新调试","使用无认证读取列出app.bsky.feed.post记录"],"ja":["認証された書き込みを使用したATProtoレコードの自動作成","uvx pdsxコマンドを使用したレコード更新のデバッグ","認証されていない読み取りを使用したapp.bsky.feed.postレコードのリスト"],"ko":["인증된 쓰기를 사용한 ATProto 레코드 자동 생성","uvx pdsx 명령을 사용한 레코드 업데이트 디버깅","인증되지 않은 읽기를 사용한 app.bsky.feed.post 레코드 목록"],"es":["Automatización de la creación de registros de ATProto con escrituras autenticadas","Depuración de actualizaciones de registros utilizando comandos uvx pdsx","Listado de registros de app.bsky.feed.post con lecturas no autenticadas"],"fr":["Automatisation de la création d''enregistrements ATProto avec des écritures authentifiées","Débogage des mises à jour d''enregistrements en utilisant des commandes uvx pdsx","Liste des enregistrements app.bsky.feed.post avec des lectures non authentifiées"],"de":["Automatisierung der Erstellung von ATProto-Registrierungen mit authentifizierten Schreibvorgängen","Fehlerbehebung bei Registrierungsaktualisierungen mithilfe von uvx pdsx-Befehlen","Auflistung von app.bsky.feed.post-Registrierungen mit nicht authentifizierten Lesevorgängen"],"pt":["Automatizar a criação de registros ATProto com escritas autenticadas","Depurar atualizações de registros usando comandos uvx pdsx","Listar registros app.bsky.feed.post com leituras não autenticadas"],"ru":["Автоматизировать создание записей ATProto с аутентифицированными записями","Отлаживать обновления записей с помощью команд uvx pdsx","Перечислять записи app.bsky.feed.post с неаутентифицированными чтениями"],"ar":["آليّة إنشاء سجلات ATProto باستخدام كتابات موثقة","تصحيح أخطاء تحديث السجلات باستخدام أوامر uvx pdsx","قائمة سجلات app.bsky.feed.post مع قراءات غير موثقة"]},"limitations":{"en":["Requires ATPROTO_HANDLE and ATPROTO_PASSWORD for authenticated operations","Limited to ATProto record operations","Dependent on uvx pdsx command-line tool"],"zh":["需要ATPROTO_HANDLE和ATPROTO_PASSWORD进行认证操作","仅限ATProto记录操作","依赖于uvx pdsx命令行工具"],"ja":["認証操作にはATPROTO_HANDLEおよびATPROTO_PASSWORDが必要","ATProtoレコード操作のみ","uvx pdsxコマンドラインツールに依存"],"ko":["인증 작업을 위해 ATPROTO_HANDLE 및 ATPROTO_PASSWORD가 필요","ATProto 레코드 작업만","uvx pdsx 명령줄 도구에 의존"],"es":["Requiere ATPROTO_HANDLE y ATPROTO_PASSWORD para operaciones autenticadas","Limitado a operaciones de registros de ATProto","Dependiente de la herramienta de línea de comandos uvx pdsx"],"fr":["Nécessite ATPROTO_HANDLE et ATPROTO_PASSWORD pour des opérations authentifiées","Limité aux opérations d''enregistrement ATProto","Dépendant de l''outil de ligne de commande uvx pdsx"],"de":["Benötigt ATPROTO_HANDLE und ATPROTO_PASSWORD für authentifizierte Operationen","Begrenzt auf ATProto-Registrierungsoperationen","Abhängig von der Kommandozeilen-Tool uvx pdsx"],"pt":["Exige ATPROTO_HANDLE e ATPROTO_PASSWORD para operações autenticadas","Limitado a operações de registros ATProto","Dependente da ferramenta de linha de comando uvx pdsx"],"ru":["Требует ATPROTO_HANDLE и ATPROTO_PASSWORD для аутентифицированных операций","Ограничен операциями с записями ATProto","Зависит от инструмента командной строки uvx pdsx"],"ar":["يتطلب ATPROTO_HANDLE وATPROTO_PASSWORD للعمليات المُوثقة","محدود لعمليات سجلات ATProto","يعتمد على أداة سطر الأوامر uvx pdsx"]},"version":4},"contentHash":"7db0d5242e9a444674fad147c6ded8bf13b86ed34c22c15ccfe8adaa9534ca6c","qualityScore":51}');
