INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dhar174/langgraph_system_generator/webapp-testing', 'webapp-testing', 'dhar174', 'langgraph_system_generator', 'community', 'webapp-testing dhar174 langgraph_system_generator community webapp-testing技能生成整个多智能体系统，用于Web应用测试，基于用户简单的文本提示 webapp-testingスキルは、Webアプリテスト用の完全な多智能体システムを生成します。ユーザーのシンプルなテキストプロンプトに基づいて webapp-testing 스킬은 웹앱 테스트를 위한 완전한 다중 에이전트 시스템을 생성합니다. 사용자의 간단한 텍스트 프롬프트에 따라 El sistema de pruebas de aplicaciones web con agentes de IA genera sistemas multiagentes basados en restricciones de usuario Le système de test d''applications web avec agents d''IA génère des systèmes multi-agents basés sur les contraintes de l''utilisateur Das Webanwendungstest-System mit KI-Agenten generiert Multiagentensysteme basierend auf Benutzereinschränkungen O Agente de Teste de Aplicativos Web gera sistemas de teste multiagente completos com base em restrições de usuário em prompts de texto simples ИИ Агенты для тестирования веб-приложений генерируют полные системы тестирования на основе ограничений пользователя в простых текстовых запросах وكلاء اختبار التطبيقات الويب ينشئون أنظمة اختبار متعددة الوكلاء الكاملة بناءً على قيود المستخدم في أوامر نصية بسيطة Prompt -> Full Agentic System. Generates entire multiagent systems based on user constraints in a simple text prompt. AI智能体 Web应用测试 多智能体系统 自动化测试 如何使用AI进行Web应用测试 AI智能体与传统测试方法的比较 webapp-testing安装指南 AI智能体在Web应用测试中的应用 Prompt -> Full Agentic System. Generates entire multiagent systems based on user constraints in a simple text prompt.');
