INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openakita/openakita/file-manager', 'file-manager', 'openakita', 'openakita', 'community', 'file-manager openakita openakita community 文件管理器是一个开源的AI助手框架，提供强大的文件管理功能 ファイルマネージャーは、オープンソースのAIアシスタントフレームワークであり、強力なファイル管理機能を提供します 파일 매니저는 오픈소스 AI 어시스턴트 프레임워크로서 강력한 파일 관리 기능을 제공합니다 El framework file-manager es una arquitectura de agente de IA de código abierto para desarrolladores. Permite la integración de habilidades y agentes en proyectos de IA Le framework file-manager est une architecture d''agent IA open-source pour les développeurs. Il permet l''intégration de compétences et d''agents dans les projets d''IA Das file-manager-Framework ist eine Open-Source-KI-Architektur für Entwickler. Es ermöglicht die Integration von Fähigkeiten und Agenten in KI-Projekten O file-manager é uma estrutura de assistente de IA de código aberto com habilidades e arquitetura de agente Файловый менеджер - это открытый ИИ агент с навыками и архитектурой агента مدير الملفات هو إطار مساعد ذكي مفتوح المصدر مع مهارات وهيكل وكيل An open-source AI assistant framework with skills and agent architecture AI智能代理 文件管理器 开源AI助手框架 文件管理工具 如何使用文件管理器 文件管理器安装指南 文件管理器替代品 An open-source AI assistant framework with skills and agent architecture');
