INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jefest9988/1c-ai-development-kit/1c-mxl-info', '1c-mxl-info', 'Jefest9988', '1c-ai-development-kit', 'community', '1c-mxl-info Jefest9988 1c-ai-development-kit community 1c-mxl-info是1C:Enterprise开发的综合AI工具箱，提供 Cursor IDE 集成 1c-mxl-infoは1C:Enterprise開発のための総合的なAIエージェントスキルであり、Cursor IDEとの統合を提供 1c-mxl-info는 1C:Enterprise 개발을 위한 완벽한 AI 에이전트 툴킷으로, Cursor IDE 통합을 제공 El kit de herramientas de agentes de IA y reglas para 1C:Enterprise en Cursor IDE ofrece una solución integral para el desarrollo de aplicaciones Le kit d''outils d''agents IA et de règles pour 1C:Enterprise dans Cursor IDE offre une solution intégrale pour le développement d''applications Das Toolkit für AI-Agenten und Regeln für 1C:Enterprise in Cursor IDE bietet eine umfassende Lösung für die Anwendungsentwicklung O 1c-mxl-info é um kit de ferramentas de agente de IA abrangente para desenvolvimento 1C:Enterprise em Cursor IDE. 1c-mxl-info - комплексный набор инструментов ИИ Агентов для разработки 1C:Enterprise в Cursor IDE. 1c-mxl-info هو مجموعة أدوات شاملة لوسائط الذكاء الاصطناعي لتطوير 1C:Enterprise في Cursor IDE. Comprehensive AI agents, skills and rules toolkit for 1C:Enterprise development in Cursor IDE 1C:Enterprise开发 AI工具箱 Cursor IDE集成 AI规则工具集 如何使用1c-mxl-info 1c-mxl-info安装 1c-mxl-info设置指南 Comprehensive AI agents, skills and rules toolkit for 1C:Enterprise development in Cursor IDE');
