INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('miyataSUPER/ai-kommon-llm-evaluation/context-loader', 'context-loader', 'miyataSUPER', 'ai-kommon-llm-evaluation', 'community', 'context-loader miyataSUPER ai-kommon-llm-evaluation community The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI has the same knowledge as Claude Code. This benefits developers working with multi-LLM comparison and evaluation frameworks. Context Loader 是一个加载共享项目上下文的技能，确保 Codex CLI 具有与 Claude Code 相同的知识 Context Loader は、共有プロジェクトのコンテキストを読み込み、Codex CLI が Claude Code と同じ知識を持つことを保証するスキルです Context Loader는 공유 프로젝트 컨텍스트를 로드하여 Codex CLI가 Claude Code와 동일한 지식을 갖도록 하는 스킬입니다 Context Loader es un marco de comparación y evaluación de multi-LLM para escenarios de coaching que carga contexto de proyecto desde el directorio `.claude/` Context Loader est un cadre de comparaison et d''évaluation de multi-LLM pour les scénarios de coaching qui charge le contexte de projet depuis le répertoire `.claude/` Context Loader ist ein Rahmenwerk für die Vergleich und Bewertung von multi-LLM in Coaching-Szenarien, das Projektcontext aus dem Verzeichnis `.claude/` lädt O Context Loader é um framework de comparação e avaliação de multi-LLM para cenários de treinamento que carrega contexto de projeto Context Loader - это фреймворк для сравнения и оценки многоязычных моделей для сценариев обучения, который загружает контекст проекта معماري لتحميل السياق هو إطار مقارنة وتقييم متعدد اللغات لسيناريوهات التدريب الذي ي加载 السياق المشترك how to use context-loader context-loader setup guide what is context-loader context-loader alternative context-loader vs Claude Code context-loader install loading shared project context Codex CLI knowledge synchronization multi-LLM comparison framework Context Loader AI 工具 加载共享项目上下文 Coding Rules Codex CLI Claude Code 多 LLM 比较 开发环境 uv ruff ty pytest Loads coding rules from .claude/rules/ directory Reads files such as coding-principles.md and dev-environment.md Ensures Codex CLI has the same knowledge as Claude Code Activates at the beginning of every task to load project context Supports files like uv, ruff, ty, and pytest requirements context-loader is a skill that loads shared project context from the .claude/ directory to synchronize knowledge between Codex CLI and Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('munlucky/mirae-financial-aicc/implementation-runner', 'community', 'munlucky', 'mirae-financial-aicc', 'munlucky/mirae-financial-aicc', 'implementation-runner', 0, 0, 51, '2026-03-06T06:23:00.212Z', '2026-03-06T08:24:04.804Z', '1f8337300c150c9609a9f87d9b99e20f5b5aacd19e04593220507f9dd70846f7', '{"id":"munlucky/mirae-financial-aicc/implementation-runner","name":"implementation-runner","description":{"en":"The implementation-runner skill automates code implementation by analyzing user messages and repository files, benefiting developers by streamlining their workflow.","zh":"Implementation Runner 是一个自动化代码变更的工具，通过检查要求和上下文，定义变更范围，记录更改的文件和摘要","ja":"Implementation Runner はコードの変更を自動化するツールで、要件とコンテキストをチェックし、変更の範囲を定義し、変更されたファイルとサマリーを記録する","ko":"Implementation Runner는 코드 변경을 자동화하는 도구로, 요구 사항과 컨텍스트를 확인하고 변경 범위를 정의하고 변경된 파일 및 요약을 기록","es":"Implementation-runner es una herramienta que automatiza la implementación de cambios en el código basándose en el análisis de contexto y la detección de archivos modificados","fr":"Implementation-runner est un outil qui automatisé la mise en œuvre de modifications dans le code en fonction de l''analyse de contexte et de la détection de fichiers modifiés","de":"Implementation-Runner ist ein Tool, das die Implementierung von Änderungen im Code basierend auf der Kontextanalyse und der Erkennung von geänderten Dateien automatisiert","pt":"O implementation-runner é uma ferramenta que automatiza a implementação de mudanças no código, utilizando análise de contexto e decisões baseadas em habilidades","ru":"Implementation-runner - это инструмент, который автоматизирует реализацию изменений в коде, используя анализ контекста и решения, основанные на навыках, с помощью ИИ Агентов","ar":"implementation-runner هو أداة تطبيقية تautomatiza تنفيذ التغييرات في الكود باستخدام تحليل السياق والقرارات المعتمدة على المهارات"},"seo":{"title":{"en":"implementation-runner: Automated Code Implementation Setu...","zh":"Implementation Runner 设置指南：自动化代码变更","ja":"Implementation Runner 導入ガイド：コード変更の自動化","ko":"Implementation Runner 설정 가이드: 자동 코드 변경","es":"Guía de implementación de implementation-runner para desa...","fr":"Configurer implementation-runner pour les développeurs","de":"Implementation-Runner Einrichtungsleitfaden für Entwickler","pt":"Guia de Implementação do implementation-runner","ru":"Настраиваемый implementation-runner: Руководство по настр...","ar":"دليل تطبيق implementation-runner: أفضل ممارسات للتطوير"},"description":{"en":"Discover how implementation-runner streamlines code changes with automated scope definition and patch generation. Learn how to integrate it into your workflo...","zh":"了解 Implementation Runner 的技术细节和功能，自动化代码变更和记录更改","ja":"Implementation Runner の技術的詳細と機能を学び、コードの変更を自動化して記録する","ko":"Implementation Runner의 기술적 세부 사항과 기능을 알아보고 자동 코드 변경 및 기록","es":"Aprenda a utilizar implementation-runner para automatizar la implementación de cambios en su código con análisis de contexto y seguimiento de archivos modifi...","fr":"Découvrez comment utiliser implementation-runner pour automatiser la mise en œuvre de modifications dans votre code avec analyse de contexte et suivi des fic...","de":"Erfahren Sie, wie Sie implementation-runner verwenden können, um die Implementierung von Änderungen in Ihrem Code mit Kontextanalyse und Änderungsverfolgung ...","pt":"Aprenda a configurar o implementation-runner para automatizar a implementação de mudanças no seu código","ru":"Узнайте, как настроить implementation-runner для автоматизации реализации изменений в вашем коде с помощью ИИ Агентов","ar":"اكتشف كيفية تطبيق implementation-runner لتحسين تنفيذ التغييرات في مشروعك باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"implementation-runner is a skill that automates code implementation by checking requirements, defining change scope, and recording changes in repository files.","zh":"Implementation Runner 是一种 AI 工具，用于自动化代码变更和记录","ja":"Implementation Runner は、コードの変更を自動化し記録する AI エージェントの一種","ko":"Implementation Runner는 코드 변경을 자동화하고 기록하는 AI 에이전트의 일종","es":"Implementation-runner es un agente de inteligencia artificial que implementa cambios en el código según el contexto y los archivos modificados","fr":"Implementation-runner est un agent d''intelligence artificielle qui met en œuvre des modifications dans le code en fonction du contexte et des fichiers modifiés","de":"Implementation-Runner ist ein KI-Agent, der Änderungen im Code basierend auf dem Kontext und den geänderten Dateien implementiert","pt":"O implementation-runner é uma ferramenta de automação de implementação de mudanças no código","ru":"Implementation-runner - это инструмент автоматизации реализации изменений в коде","ar":"implementation-runner هو أداة تطبيقية لتنفيذ التغييرات في الكود"},"features":{"en":["Analyzes user messages via `analysisContext.request.userMessage`","Defines change scope based on `analysisContext.decisions.skillChain`","Records changed files in `repo.changedFiles`","Updates implementation completion in `analysisContext`","Generates patch output in YAML format"],"zh":["检查要求和上下文","定义变更范围和实现","记录更改的文件和摘要","更新实现完成状态","支持多种代码文件类型"],"ja":["要件とコンテキストをチェック","変更の範囲と実装を定義","変更されたファイルとサマリーを記録","実装完了状態を更新","複数のコードファイルタイプをサポート"],"ko":["요구 사항과 컨텍스트 확인","변경 범위와 구현 정의","변경된 파일과 요약 기록","구현 완료 상태 업데이트","다중 코드 파일 유형 지원"],"es":["Análisis de contexto para determinar el alcance de los cambios","Detección de archivos modificados para realizar un seguimiento preciso","Implementación automática de cambios en el código","Actualización del estado de implementación en el contexto de análisis","Compatibilidad con varios formatos de archivo y estructuras de proyecto"],"fr":["Analyse de contexte pour déterminer la portée des modifications","Détection de fichiers modifiés pour un suivi précis","Mise en œuvre automatique de modifications dans le code","Mise à jour de l''état de mise en œuvre dans le contexte d''analyse","Compatibilité avec plusieurs formats de fichiers et structures de projet"],"de":["Kontextanalyse zur Bestimmung des Änderungsumfangs","Erkennung von geänderten Dateien für eine präzise Verfolgung","Automatisierte Implementierung von Änderungen im Code","Aktualisierung des Implementierungsstatus im Analysekontext","Kompatibilität mit verschiedenen Dateiformaten und Projektstrukturen"],"pt":["Análise de contexto para determinar a implementação certa","Decisões baseadas em habilidades para definir o escopo de mudanças","Registo de arquivos alterados e resumo das mudanças","Atualização do estado de implementação no analysisContext","Integração com o repositório para gerenciar arquivos alterados"],"ru":["Анализ контекста для определения правильной реализации","Решения, основанные на навыках, для определения объема изменений","Запись измененных файлов и краткое описание изменений","Обновление состояния реализации в analysisContext","Интеграция с репозиторием для управления измененными файлами с помощью ИИ Агентов"],"ar":["تحليل السياق لتحديد التنفيذ الصحيح","قرارات معتمدة على المهارات لتحديد نطاق التغييرات","تسجيل الملفات المعدلة وملخص التغييرات","تحديث حالة التنفيذ في analysisContext","التكامل مع المستودع لإدارة الملفات المعدلة باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use implementation-runner","implementation-runner setup guide","implementation-runner alternative","implementation-runner vs other skills","implementation-runner install","automated code implementation","yaml patch generation","repository file analysis"],"zh":["Implementation Runner","AI 工具","代码变更","自动化","代码记录","实现完成状态","代码文件类型","AIエージェント"],"ja":["Implementation Runner","AI エージェント","コード変更","自動化","コード記録","実装完了状態","コードファイルタイプ","AIツール"],"ko":["Implementation Runner","AI 에이전트","코드 변경","자동화","코드 기록","구현 완료 상태","코드 파일 유형","AI 도구"],"es":["implementation-runner","agente de inteligencia artificial","automatización de implementación","análisis de contexto","detección de archivos modificados","desarrollo de software","herramientas de desarrollo","integración continua"],"fr":["implementation-runner","agent d''intelligence artificielle","automatisation de la mise en œuvre","analyse de contexte","détection de fichiers modifiés","développement de logiciels","outils de développement","intégration continue"],"de":["implementation-runner","KI-Agent","Automatisierung der Implementierung","Kontextanalyse","Erkennung von geänderten Dateien","Software-Entwicklung","Entwicklungstools","kontinuierliche Integration"],"pt":["implementation-runner","automação de implementação","análise de contexto","decisões baseadas em habilidades","gerenciamento de arquivos","desenvolvimento de software","ferramentas de desenvolvimento","implementação de mudanças"],"ru":["implementation-runner","автоматизация реализации","анализ контекста","решения, основанные на навыках","управление файлами","разработка программного обеспечения","инструменты разработки","реализация изменений","ИИ Агенты"],"ar":["implementation-runner","تطبيق التغييرات","تحليل السياق","قرارات معتمدة على المهارات","إدارة الملفات","تطوير البرمجيات","أدوات التطوير","تنفيذ التغييرات","أدوات الذكاء الاصطناعي"]}},"owner":"munlucky","repo":"mirae-financial-aicc","repoPath":"munlucky/mirae-financial-aicc","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.212Z","topics":[],"category":"community","skillMd":{"name":"implementation-runner","description":"Performs implementation in the chain and records completion state and changed files in analysisContext. Use during implementation.","bodyPreview":"# Implementation Runner\n\n## Inputs\n- `analysisContext.request.userMessage`\n- `analysisContext.decisions.skillChain`\n- `analysisContext.repo.openFiles`\n- `analysisContext.artifacts.contextDocPath` (if present)\n\n## Procedure\n1. Check requirements and context.\n2. Define change scope and implement.\n3. Record changed files and key change summary.\n4. Update implementation completion in `analysisContext`.\n\n## Output (patch)\n```yaml\nsignals.implementationComplete: true\nrepo.changedFiles:\n  - src/...\nnot","body":"# Implementation Runner\n\n## Inputs\n- `analysisContext.request.userMessage`\n- `analysisContext.decisions.skillChain`\n- `analysisContext.repo.openFiles`\n- `analysisContext.artifacts.contextDocPath` (if present)\n\n## Procedure\n1. Check requirements and context.\n2. Define change scope and implement.\n3. Record changed files and key change summary.\n4. Update implementation completion in `analysisContext`.\n\n## Output (patch)\n```yaml\nsignals.implementationComplete: true\nrepo.changedFiles:\n  - src/...\nnotes:\n  - \"implementation: complete, changed_files=3\"\n```\n\n## Rules\n- Do not call other skills/subagents.\n- If failed or deferred, record the reason in `notes`.\n"},"lastSynced":"2026-03-06T08:24:04.804Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents requiring automated implementation and workflow streamlining capabilities.","zh":"适合需要自动化实现和工作流优化的代码分析代理。","ja":"コード分析エージェントが自動実装とワークフローのストリーミングを必要とする場合に適しています。","ko":"코드 분석 에이전트가 자동 구현 및 워크플로우 최적화를 필요로 할 때 적합합니다.","es":"Ideal para Agentes de Análisis de Código que requieren implementación automatizada y capacidades de optimización de flujo de trabajo.","fr":"Idéal pour les Agents d''Analyse de Code nécessitant une mise en œuvre automatisée et des capacités de rationalisation du flux de travail.","de":"Ideal für Code-Analyse-Agents, die eine automatisierte Implementierung und Workflow-Optimierungs-Funktionen erfordern.","pt":"Ideal para Agentes de Análise de Código que exigem implementação automatizada e capacidades de otimização de fluxo de trabalho.","ru":"Идеально для Агентов Анализа Кодов, требующих автоматизированной реализации и возможностей оптимизации рабочих процессов.","ar":"مثالي لعميل تحليل الشفرة الذي يتطلب التنفيذ الآلي وقدرات简 bufio العمل"},"recommendation":{"en":"Empowers agents to automate code implementation by analyzing user messages and repository files, utilizing context from artifacts like contextDocPath, and updating the analysisContext with implementation completion and changed files.","zh":"通过分析用户消息和仓库文件，利用contextDocPath等文物的上下文，更新analysisContext以实现完成和更改的文件，赋予代理自动化代码实现的能力。","ja":"ユーザーメッセージやリポジトリファイルを分析し、contextDocPathなどのアーティファクトからコンテキストを利用して、analysisContextを実装の完了と変更されたファイルで更新し、コードの実装を自動化するエージェントを可能にします。","ko":"사용자 메시지와 저장소 파일을 분석하고 contextDocPath 등의 아티팩트에서 컨텍스트를 활용하여 analysisContext를 구현 완료 및 변경된 파일로 업데이트하여 코드 구현을 자동화하는 에이전트를 가능하게 합니다.","es":"Habilita a los agentes a automatizar la implementación del código analizando los mensajes de los usuarios y los archivos del repositorio, utilizando el contexto de artefactos como contextDocPath, y actualizando el analysisContext con la finalización de la implementación y los archivos modificados.","fr":"Permet aux agents d''automatiser la mise en œuvre du code en analysant les messages des utilisateurs et les fichiers du référentiel, en utilisant le contexte d''artefacts tels que contextDocPath, et en mettant à jour l''analysisContext avec l''achèvement de la mise en œuvre et les fichiers modifiés.","de":"Ermächtigt die Agenten, die Code-Implementierung durch Analyse der Benutzernachrichten und der Repository-Dateien zu automatisieren, unter Verwendung des Kontexts von Artefakten wie contextDocPath, und aktualisiert den analysisContext mit der Implementierungsvollendung und den geänderten Dateien.","pt":"Habilita os agentes a automatizar a implementação do código analisando as mensagens do usuário e os arquivos do repositório, utilizando o contexto de artefatos como contextDocPath e atualizando o analysisContext com a conclusão da implementação e os arquivos alterados.","ru":"Наделяет агентов возможностью автоматизировать реализацию кода путем анализа сообщений пользователя и файлов репозитория, используя контекст артефактов, таких как contextDocPath, и обновляя analysisContext с завершением реализации и изменившимися файлами.","ar":"تمكين العميل من تلقين تنفيذ الشفرة عن طريق تحليل رسائل المستخدم وملفات المستودع، واستخدام السياق من الملفات المرفقة مثل contextDocPath، وتحديث analysisContext بالانتهاء من التنفيذ والملفات المعدلة"},"useCases":{"en":["Automating code changes based on user requests","Streamlining developer workflow by analyzing repository files","Recording and summarizing key changes in implementation"],"zh":["基于用户请求自动化代码更改","通过分析仓库文件优化开发者工作流","记录和总结关键的实现更改"],"ja":["ユーザーのリクエストに基づいてコードの変更を自動化する","リポジトリファイルを分析して開発者のワークフローを最適化する","実装の重要な変更を記録して要約する"],"ko":["사용자 요청에 따라 코드 변경 자동화","저장소 파일 분석을 통한 개발자 워크플로우 최적화","구현의 주요 변경 사항 기록 및 요약"],"es":["Automatizar los cambios de código en función de las solicitudes de los usuarios","Optimizar el flujo de trabajo de los desarrolladores analizando los archivos del repositorio","Grabar y resumir los cambios clave en la implementación"],"fr":["Automatiser les modifications de code en fonction des demandes des utilisateurs","Rationaliser le flux de travail des développeurs en analysant les fichiers du référentiel","Enregistrer et résumer les modifications clés de la mise en œuvre"],"de":["Automatisierung von Code-Änderungen basierend auf den Anfragen der Benutzer","Optimierung des Entwickler-Workflows durch Analyse der Repository-Dateien","Aufzeichnung und Zusammenfassung der wichtigsten Änderungen in der Implementierung"],"pt":["Automatizar alterações de código com base em solicitações do usuário","Otimizar o fluxo de trabalho do desenvolvedor analisando arquivos do repositório","Gravar e resumir as principais alterações na implementação"],"ru":["Автоматизировать изменения кода на основе запросов пользователя","Оптимизировать рабочий процесс разработчика путем анализа файлов репозитория","Записывать и суммировать основные изменения в реализации"],"ar":["تلقين تغييرات الشفرة بناءً على طلبات المستخدم","تحسين تدفق عمل المطور من خلال تحليل ملفات المستودع","تسجيل وتلخيص التغييرات الرئيسية في التنفيذ"]},"limitations":{"en":["Requires access to analysisContext and repository files","Needs userMessage and skillChain context for decision-making"],"zh":["需要访问analysisContext和仓库文件","需要userMessage和skillChain上下文进行决策"],"ja":["analysisContextとリポジトリファイルへのアクセスが必要","ユーザーメッセージとスキルチェーンのコンテキストが必要"],"ko":["analysisContext 및 저장소 파일에 대한 액세스가 필요","사용자 메시지 및 스킬 체인 컨텍스트가 필요"],"es":["Requiere acceso a analysisContext y archivos del repositorio","Necesita contexto de userMessage y skillChain para la toma de decisiones"],"fr":["Nécessite un accès à analysisContext et aux fichiers du référentiel","Nécessite un contexte de userMessage et de skillChain pour la prise de décision"],"de":["Benötigt Zugriff auf analysisContext und Repository-Dateien","Benötigt Kontext von userMessage und skillChain für die Entscheidungsfindung"],"pt":["Exige acesso ao analysisContext e aos arquivos do repositório","Necessita do contexto userMessage e skillChain para tomar decisões"],"ru":["Требует доступа к analysisContext и файлам репозитория","Требует контекста userMessage и skillChain для принятия решений"],"ar":["يتطلب الوصول إلى analysisContext وملفات المستودع","يحتاج إلى سياق userMessage وskillChain للقرارات"]},"version":4},"contentHash":"1f8337300c150c9609a9f87d9b99e20f5b5aacd19e04593220507f9dd70846f7","qualityScore":51}');
