INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('penne-0505/lifelog_clipper/systematic-debugging', 'systematic-debugging', 'penne-0505', 'lifelog_clipper', 'community', 'systematic-debugging penne-0505 lifelog_clipper community Systematic-debugging is a methodical approach to debugging that emphasizes finding the root cause of issues before attempting fixes, benefiting developers and QA engineers. It ensures that fixes are effective and long-lasting. 系统化调试是一种查找技术问题根因的方法，通过这种方法可以减少随机修复和新Bug的产生。 システム化デバッグは、テスト失敗やバグの根本原因を迅速に特定するための方法です。 시스템 디버깅은 기술 이슈의 근본 원인을 찾아내는 방법으로, 이를 통해 빠른 해결과 버그의 최소화를 도모합니다. La depuración sistemática es crucial para identificar la causa raíz de los problemas técnicos. Sigue nuestro enfoque para solucionar bugs y fallos de prueba de manera efectiva. Le débogage systématique est essentiel pour identifier la cause racine des problèmes techniques. Suivez notre approche pour résoudre les bugs et les échecs de test de manière efficace. Die systematische Fehlersuche ist entscheidend, um die Ursache von technischen Problemen zu identifizieren. Befolgen Sie unseren Ansatz, um Bugs und Testfehler effektiv zu beheben. how to use systematic-debugging systematic-debugging vs trial and error systematic-debugging setup guide what is systematic-debugging systematic-debugging alternative to random fixes systematic-debugging for bug resolution systematic-debugging install systematic-debugging best practices systematic-debugging for developers systematic-debugging for QA engineers 系统化调试 AIエージェント 技术问题解决 根因分析 快速调试 减少新Bug 严格的调试步骤 技术问题解决方案 调试Best Practices Enforces the iron law of no fixes without root cause investigation first Requires completion of Phase 1 investigation before proposing fixes Applies to any technical issue, including test failures and bugs Ensures that symptom fixes are not proposed without understanding the underlying issue Helps developers and QA engineers identify and resolve issues efficiently Follows a systematic approach to debugging, reducing random fixes and new bugs Systematic-debugging is a debugging approach that requires investigating the root cause of an issue before proposing any fixes, following the iron law of no fixes without root cause investigation first.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Erland366/transformers_playground/domain-advisor', 'community', 'Erland366', 'transformers_playground', 'Erland366/transformers_playground', 'domain-advisor', 0, 0, 51, '2026-03-06T12:59:22.267Z', '2026-03-06T15:00:57.918Z', 'aee8bafcc8695f037bc1ca3b36b5fb323cc5cb8a7969ab045f3c0103ddc3939d', '{"id":"Erland366/transformers_playground/domain-advisor","name":"domain-advisor","description":{"en":"The domain-advisor skill provides expert guidance for AI agents, helping users determine the next steps in research, experiment, or troubleshooting processes. It benefits developers and researchers seeking optimized workflows.","zh":"Domain Advisor 是一个 AI Agent 技术，用于提供实验和benchmark报告，适应不同domain的行为","ja":"Domain Advisor は、実験とベンチマークレポートを提供し、さまざまなドメインの動作に適応する AI エージェント技術です","ko":"Domain Advisor는 실험 및 벤치마크 보고서를 제공하고 다양한 도메인의 동작에 적응하는 AI 도구 기술입니다","es":"El skill domain-advisor se utiliza para proporcionar asesoramiento en la planificación de proyectos de inteligencia artificial","fr":"Le skill domaine-conseiller est utilisé pour offrir des conseils en planification pour les projets d''IA","de":"Der domain-advisor-Skill wird verwendet, um Beratung bei der Planung von KI-Projekten zu bieten","pt":"O Domain-Advisor é uma habilidade que fornece orientação para a próxima etapa com base em relatórios de experimentos e logs de troubleshoot","ru":"Domain-Advisor - это навык, который предоставляет рекомендации для следующего шага на основе отчетов экспериментов и журналов устранения неполадок ИИ Агентов","ar":"Domain-Advisor هو مهارة توفر توجيهات للخطوة التالية بناءً على تقارير التجارب وسجلات حل المشكلات"},"seo":{"title":{"en":"domain-advisor: Setup Guide for AI Agents","zh":"Domain Advisor 设置指南 - AIエージェント技术","ja":"Domain Advisor ベストプラクティス - AIエージェントの活用","ko":"Domain Advisor 설정 가이드 - AI 도구 활용","es":"Guía de configuración de domain-advisor para agentes de i...","fr":"Configurer le domaine-conseiller pour les outils d''IA","de":"Einrichtungsleitfaden für domain-advisor in KI-Agents","pt":"Guia de Configuração do Domain-Advisor para Desenvolvedores","ru":"Настройка Domain-Advisor: Руководство для Разработчиков И...","ar":"دليل إعدادDomain-Advisor للمانحين"},"description":{"en":"Unlock expert advice with domain-advisor. Discover how to integrate this skill into your AI agent and boost decision-making capabilities. Get started now!","zh":"了解 Domain Advisor 的技术细节，包括初始化和行为适应，提高您的 AI Agent 开发效率","ja":"Domain Advisor の機能と設定方法をマスターし、AI エージェントの開発を効率化する","ko":"Domain Advisor의 기술 세부 사항과 설정 방법을 알아보세요. AI 도구 개발을 효율화하는 방법","es":"Aprende a utilizar domain-advisor para mejorar la toma de decisiones en tus proyectos de inteligencia artificial","fr":"Découvrez comment configurer le domaine-conseiller pour améliorer la planification dans vos projets d''IA","de":"Erfahren Sie, wie Sie domain-advisor einrichten, um die Entscheidungsfindung in Ihren KI-Projekten zu verbessern","pt":"Aprenda a configurar o Domain-Advisor para melhorar a tomada de decisões com base em relatórios de experimentos e logs de troubleshoot","ru":"Узнайте, как настроить Domain-Advisor для улучшения принятия решений на основе отчетов экспериментов и журналов устранения неполадок ИИ Агентов","ar":"تعرف على كيفية إعداد Domain-Advisor لتحسين اتخاذ القرارات بناءً على تقارير التجارب وسجلات حل المشكلات"},"definition":{"en":"domain-advisor is a skill that offers advice based on user input, utilizing registry.json for configuration and adapting behavior to specific domains such as research or CUDA.","zh":"Domain Advisor 是一种 AI Agent 技术，提供实验报告和benchmark数据，用于规划和优化","ja":"Domain Advisor は、実験レポートとベンチマークデータを提供する AI エージェント技術です","ko":"Domain Advisor는 실험 보고서와 벤치마크 데이터를 제공하는 AI 도구 기술입니다","es":"Un domain-advisor es un agente de inteligencia artificial que asesora en la planificación de proyectos","fr":"Un domaine-conseiller est un outil d''IA qui conseille en planification de projets","de":"Ein domain-advisor ist ein KI-Agent, der bei der Planung von Projekten berät","pt":"O Domain-Advisor é uma ferramenta de orientação que ajuda os desenvolvedores a tomar decisões informadas","ru":"Domain-Advisor - это инструмент рекомендаций, который помогает разработчикам принимать обоснованные решения ИИ Агентов","ar":"Domain-Advisor هو أداة توجيه تساعد المطورين على اتخاذ قرارات مستنيرة"},"features":{"en":["Reads .codex/skills/registry.json for domain and path configurations","Adapts behavior based on the domain, including research, unsloth, or CUDA","Utilizes paths.reports for experiment and benchmark reports","Accesses paths.experiment_log for detailed experiment logs","Leverages paths.troubleshooting for guided troubleshooting"],"zh":["支持多个 domain（research、unsloth、cuda）","根据用户输入的消息初始化行为","提供实验和benchmark报告","适应不同 domain 的行为","支持多种路径配置（reports、experiment_log、troubleshooting）"],"ja":["複数のドメイン（research、unsloth、cuda）をサポート","ユーザーの入力メッセージに基づいて動作を初期化","実験とベンチマークレポートを提供","さまざまなドメインの動作に適応","複数のパス設定（reports、experiment_log、troubleshooting）をサポート"],"ko":["여러 도메인（research、unsloth、cuda）을 지원","사용자의 입력 메시지에 따라 동작을 초기화","실험과 벤치마크 보고서를 제공","다양한 도메인의 동작에 적응","여러 경로 설정（reports、experiment_log、troubleshooting）을 지원"],"es":["Incorpora la lectura de `.codex/skills/registry.json` para determinar el dominio","Adapta su comportamiento en función del dominio de investigación, unsloth o cuda","Proporciona informes de experimentos y benchmarks","Ofrece una guía de solución de problemas","Permite la planificación de proyectos de inteligencia artificial","Utiliza tecnologías como JSON y CLI"],"fr":["Intègre la lecture de `.codex/skills/registry.json` pour déterminer le domaine","Adapte son comportement en fonction du domaine de recherche, unsloth ou cuda","Fournit des rapports d''expériences et de benchmarks","Offre un guide de dépannage","Permet la planification de projets d''IA","Utilise des technologies comme JSON et CLI"],"de":["Integriert die Lektüre von `.codex/skills/registry.json`, um das Domänengebiet zu bestimmen","Passt sein Verhalten an das Forschungs-, unsloth- oder cuda-Domänengebiet an","Bietet Experiment- und Benchmark-Berichte an","Bietet eine Fehlerbehebungsanleitung","Ermöglicht die Planung von KI-Projekten","Verwendet Technologien wie JSON und CLI"],"pt":["Leitura de arquivos de registro de experimentos","Análise de logs de troubleshoot","Adaptação de comportamento com base em configurações de domínio","Suporte a múltiplos domínios de pesquisa","Integração com relatórios de benchmark"],"ru":["Чтение файлов журналов экспериментов","Анализ журналов устранения неполадок","Адаптация поведения на основе настроек домена ИИ Агентов","Поддержка нескольких доменов исследования","Интеграция с отчетами о производительности"],"ar":["قراءة سجلات تجارب","تحليل سجلات حل المشكلات","التكيف السلوكي بناءً على إعدادات المجال","دعم مجالات بحث متعددة","التكامل مع تقارير الأداء"]},"keywords":{"en":["how to use domain-advisor","domain-advisor setup guide","what is domain-advisor","domain-advisor alternative","domain-advisor vs other AI skills","installing domain-advisor","configuring domain-advisor for CUDA","domain-advisor for research optimization","domain-advisor troubleshooting guide"],"zh":["AIエージェント","Domain Advisor","实验报告","benchmark数据","多个domain支持","初始化行为","报告提供","动作适应"],"ja":["AIエージェント","Domain Advisor","実験レポート","ベンチマークデータ","複数のドメインサポート","動作初期化","レポート提供","動作適応"],"ko":["AI 도구","Domain Advisor","실험 보고서","벤치마크 데이터","여러 도메인 지원","동작 초기화","보고서 제공","동작 적응"],"es":["agentes de inteligencia artificial","domain-advisor","planificación de proyectos de IA","configuración de domain-advisor","registros JSON","dominios de investigación","unsloth","cuda","informes de experimentos","benchmarking"],"fr":["outils d''IA","domaine-conseiller","planification de projets d''IA","configuration du domaine-conseiller","fichiers JSON","domaines de recherche","unsloth","cuda","rapports d''expériences","benchmarking"],"de":["KI-Agents","domain-advisor","Planung von KI-Projekten","Einrichtung von domain-advisor","JSON-Dateien","Forschungsdomänen","unsloth","cuda","Experimentenberichte","Benchmarking"],"pt":["Domain-Advisor","orientação de desenvolvimento","relatórios de experimentos","logs de troubleshoot","desenvolvimento de software","ferramentas de desenvolvimento","tecnologias de IA"],"ru":["Domain-Advisor","разработка ИИ Агентов","отчеты экспериментов","журналы устранения неполадок","разработка программного обеспечения","инструменты разработки","технологии ИИ"],"ar":["Domain-Advisor","تطوير المانحين","تقارير التجارب","سجلات حل المشكلات","تطوير البرمجيات","أدوات التطوير","تقنيات الذكاء الاصطناعي"]}},"owner":"Erland366","repo":"transformers_playground","repoPath":"Erland366/transformers_playground","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.267Z","topics":[],"category":"community","skillMd":{"name":"domain-advisor","description":">","tags":"","bodyPreview":"# Skill: domain-advisor\n\n## When to use\n\nUse this skill when:\n- The user message starts with `<advise>`, or\n- The user asks \"What should we try next?\" or similar planning questions.\n\n## Initialization\n\n1. Read `.codex/skills/registry.json` to determine:\n   - `domain`: research | unsloth | cuda\n   - `paths.reports`: where to find experiment/benchmark reports\n   - `paths.experiment_log`: path to experiment log\n   - `paths.troubleshooting`: path to troubleshooting guide\n\n2. Adapt behavior based on","body":"# Skill: domain-advisor\n\n## When to use\n\nUse this skill when:\n- The user message starts with `<advise>`, or\n- The user asks \"What should we try next?\" or similar planning questions.\n\n## Initialization\n\n1. Read `.codex/skills/registry.json` to determine:\n   - `domain`: research | unsloth | cuda\n   - `paths.reports`: where to find experiment/benchmark reports\n   - `paths.experiment_log`: path to experiment log\n   - `paths.troubleshooting`: path to troubleshooting guide\n\n2. Adapt behavior based on domain (see Domain-Specific Behavior below).\n\n## Inputs\n\n- User goal (including constraints like run budget, hardware, time).\n- Optional references to files (configs, reports, logs) mentioned in the goal.\n\n## Behavior\n\n1. **Understand the goal**\n   - Parse the research/development goal and constraints.\n   - If unclear, ask a concise clarifying question.\n\n2. **Gather context**\n   - Scan `.codex/skills/` for **relevant result skills** matching the task.\n   - Read relevant reports from the `paths.reports` directory.\n   - Skim recent entries in `paths.experiment_log`.\n   - If errors are mentioned, check `paths.troubleshooting` for known patterns.\n\n3. **Propose a plan**\n   - Design **2–5 concrete experiments/tasks**, each with:\n     - Clear objective\n     - Key configuration/parameters\n     - Expected outcome or hypothesis\n     - Any relevant variation to test\n   - Respect constraints (budget, hardware, time).\n   - **Reuse defaults** from existing skills instead of inventing new ones.\n\n4. **Output format**\n   - Start with a short natural-language summary.\n   - Provide a markdown table:\n\n     | id | description | key_differences | notes |\n     |----|-------------|-----------------|-------|\n\n   - Optionally propose file paths for configs or reports to create.\n   - If errors were mentioned, explain how this plan avoids known failure patterns.\n\n5. **Logging**\n   - When useful, append a short entry to `paths.experiment_log` summarizing\n     the proposed plan (only with user approval).\n\n---\n\n## Domain-Specific Behavior\n\n### Research Domain\n\nWhen `domain: research`:\n\n**Focus areas:**\n- Hyperparameter sweeps (learning rate, batch size, epochs)\n- Model architecture variations (layers, dimensions, attention heads)\n- Dataset mixtures and sampling strategies\n- Training dynamics (warmup, schedulers, checkpointing)\n\n**Context to gather:**\n- `training_reports/*.md` - past training runs\n- Model configs and their performance\n- Loss curves and convergence patterns\n\n**Output emphasis:**\n- Parameter sweep tables with specific values\n- Ablation study designs\n- Baseline comparisons\n\n### Unsloth Domain\n\nWhen `domain: unsloth`:\n\n**Focus areas:**\n- LoRA rank and alpha selection\n- Quantization settings (4-bit, 8-bit, nf4)\n- Gradient checkpointing configuration\n- Fine-tuning hyperparameters for specific model families\n- Memory optimization strategies\n\n**Context to gather:**\n- `training_reports/*.md` - past fine-tuning runs\n- Model-specific Unsloth configurations\n- Memory usage patterns\n\n**Output emphasis:**\n- LoRA configuration recommendations\n- Memory/speed tradeoffs\n- Model-specific settings (Llama, Mistral, Qwen, etc.)\n\n### CUDA Domain\n\nWhen `domain: cuda`:\n\n**Focus areas:**\n- Tiling strategies and block sizes\n- Shared memory usage patterns\n- Warp-level primitives\n- Memory coalescing optimization\n- Triton autotuning configurations\n\n**Context to gather:**\n- `benchmark_results/*.md` - past kernel benchmarks\n- Profiling data (nsight, ncu reports)\n- Bandwidth and occupancy metrics\n\n**Output emphasis:**\n- Kernel configuration parameters\n- Expected speedup estimates\n- Memory access pattern recommendations\n- Profiling metrics to track\n\n---\n\n## Example Output\n\n### Research Example\n\n```markdown\n## Experiment Plan: Attention Head Ablation\n\nBased on previous runs in `training_reports/baseline-2025-01.md`, the 8-head\nconfiguration achieved 92% accuracy. Testing whether fewer heads can match\nthis with lower compute.\n\n| id | description | key_differences | notes |\n|----|-------------|-----------------|-------|\n| A1 | 4-head attention | heads=4 vs baseline 8 | Test if 4 heads sufficient |\n| A2 | 6-head attention | heads=6 | Middle ground |\n| A3 | 4-head + wider FFN | heads=4, ffn_dim=4096 | Compensate with FFN |\n\nAll runs use: lr=1e-4, batch_size=32, epochs=10 (from baseline config).\n```\n\n### Unsloth Example\n\n```markdown\n## Fine-tuning Plan: Llama-3 8B with Unsloth\n\nBased on `training_reports/llama3-lora-v1.md`, rank=16 showed good results\nbut OOM''d at batch_size=4. Testing memory-efficient configurations.\n\n| id | description | key_differences | notes |\n|----|-------------|-----------------|-------|\n| U1 | rank=8 + grad_ckpt | Lower rank, enable checkpointing | Memory baseline |\n| U2 | rank=16 + 4bit | Full rank with 4-bit quantization | Quality vs memory |\n| U3 | rank=32 + offload | Higher rank with CPU offload | Max quality attempt |\n\nAll runs use: alpha=32, dropout=0.05, target_modules=[\"q_proj\", \"v_proj\"]\n```\n\n### CUDA Example\n\n```markdown\n## Kernel Optimization Plan: Softmax\n\nBased on `benchmark_results/softmax-v1.md`, current implementation achieves\n80% of theoretical bandwidth. Testing tiling strategies.\n\n| id | description | key_differences | notes |\n|----|-------------|-----------------|-------|\n| K1 | 2D tiling | BLOCK_M=64, BLOCK_N=64 | Better L2 reuse |\n| K2 | Warp reduction | Use warp shuffles | Reduce shared mem |\n| K3 | Online softmax | Single-pass algorithm | Fused with attention |\n\nProfile with: `ncu --set full` to capture memory metrics.\n```\n"},"lastSynced":"2026-03-06T15:00:57.918Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents requiring expert guidance on workflow optimization and troubleshooting processes.","zh":"适合需要工作流优化和故障排除过程专家指导的研究代理。","ja":"ワークフロー最適化とトラブルシューティングプロセスに関する専門家の指導が必要な研究エージェントに適しています。","ko":"워크플ロー 최적화 및 문제 해결 프로세스에 대한 전문가 지침이 필요한 연구 에이전트에 적합합니다.","es":"Ideal para Agentes de Investigación que requieren orientación experta sobre la optimización de flujos de trabajo y procesos de solución de problemas.","fr":"Idéal pour les Agents de Recherche nécessitant une guidance experte sur l''optimisation des flux de travail et les processus de dépannage.","de":"Ideal für Forschungsagenten, die eine Expertenberatung zur Optimierung von Workflows und Fehlerbehebungsprozessen benötigen.","pt":"Ideal para Agentes de Pesquisa que requerem orientação especializada na otimização de fluxos de trabalho e processos de solução de problemas.","ru":"Идеально для Исследовательских Агентов, требующих экспертных рекомендаций по оптимизации рабочих процессов и процессов устранения неполадок.","ar":"مثالي للوكلاء البحثيين الذين يتطلبون إرشادات خبيرة في تحسين سير العمل وإجراءات حل المشكلات."},"recommendation":{"en":"Empowers agents to provide actionable advice on next steps in research, experiment, or troubleshooting processes, utilizing registry.json configurations and paths to reports, experiment logs, and troubleshooting guides.","zh":"赋予代理提供可执行的建议，用于研究、实验或故障排除过程的下一步，利用registry.json配置和报告、实验日志和故障排除指南的路径。","ja":"registry.jsonの構成と報告書、実験ログ、トラブルシューティングガイドへのパスを利用して、研究、実験、またはトラブルシューティングプロセスの次のステップについて、実行可能なアドバイスを提供するエージェントを可能にします。","ko":"registry.json 구성 및 보고서, 실험 로그 및 문제 해결 가이드への 경로를 사용하여 연구, 실험 또는 문제 해결 프로세스의 다음 단계에 대한 실행 가능한 조언을 제공하는 에이전트를 가능하게 합니다.","es":"Habilita a los agentes a proporcionar consejos operativos sobre los próximos pasos en la investigación, el experimento o los procesos de solución de problemas, utilizando configuraciones de registry.json y rutas a informes, registros de experimentos y guías de solución de problemas.","fr":"Permet aux agents de fournir des conseils opérationnels sur les prochaines étapes dans la recherche, l''expérimentation ou les processus de dépannage, en utilisant des configurations registry.json et des chemins d''accès aux rapports, journaux d''expérimentation et guides de dépannage.","de":"Ermächtigt die Agenten, handhabbare Ratschläge für die nächsten Schritte in der Forschung, dem Experiment oder den Fehlerbehebungsprozessen zu geben, indem sie Konfigurationen von registry.json und Pfade zu Berichten, Experimentprotokollen und Fehlerbehebungsleitfäden nutzen.","pt":"Habilita os agentes a fornecer conselhos práticos sobre as próximas etapas nos processos de pesquisa, experimento ou solução de problemas, utilizando configurações registry.json e caminhos para relatórios, logs de experimentos e guias de solução de problemas.","ru":"Наделяет агентов возможностью предоставлять действенные советы о следующих шагах в процессах исследования, эксперимента или устранения неполадок, используя конфигурации registry.json и пути к отчетам, журналам экспериментов и руководствам по устранению неполадок.","ar":"يمكّن الوكلاء من تقديم نصائح قابلة للتنفيذ حول الخطوات التالية في عمليات البحث أو التجربة أو إجراءات حل المشكلات، باستخدام تكوينات registry.json ومسارات إلى التقارير وسجلات التجارب ودلائل حل المشكلات."},"useCases":{"en":["Determining optimal workflows for research tasks","Troubleshooting experiment issues based on log data","Generating reports for benchmarking and analysis"],"zh":["确定研究任务的最佳工作流","基于日志数据排除实验问题","生成基准测试和分析报告"],"ja":["研究タスクの最適なワークフローを決定する","ログデータに基づいて実験の問題をトラブルシューティングする","ベンチマークテストと分析の報告書を生成する"],"ko":["연구 작업을 위한 최적의 워크플ロー 결정","로그 데이터를 기반으로 실험 문제 해결","벤치마크 테스트 및 분석 보고서 생성"],"es":["Determinar flujos de trabajo óptimos para tareas de investigación","Solucionar problemas de experimentación en función de los datos del registro","Generar informes para la creación de benchmarks y el análisis"],"fr":["Déterminer les flux de travail optimaux pour les tâches de recherche","Résoudre les problèmes d''expérimentation en fonction des données de journal","Générer des rapports pour la création de benchmarks et l''analyse"],"de":["Bestimmung optimaler Workflows für Forschungsaufgaben","Fehlerbehebung bei Experimenten auf der Grundlage von Protokolldaten","Erstellung von Berichten für Benchmarking und Analyse"],"pt":["Determinar fluxos de trabalho ótimos para tarefas de pesquisa","Solucionar problemas de experimento com base em dados de log","Gerar relatórios para benchmarking e análise"],"ru":["Определение оптимальных рабочих процессов для исследовательских задач","Устранение неполадок эксперимента на основе данных журнала","Генерация отчетов для бенчмаркинга и анализа"],"ar":["تحديد سير العمل الأمثل لمهام البحث","حل مشاكل التجربة بناءً على بيانات السجل","генерация تقارير لعمليات الاختبار والتحليل"]},"limitations":{"en":["Requires access to .codex/skills/registry.json","Dependent on specific domain configurations (research, unsloth, cuda)","Needs paths to experiment logs and troubleshooting guides"],"zh":["需要访问.codex/skills/registry.json","依赖于特定领域配置(研究、unsloth、cuda)","需要实验日志和故障排除指南的路径"],"ja":[".codex/skills/registry.jsonへのアクセスが必要","特定のドメイン構成(研究、unsloth、cuda)に依存する","実験ログとトラブルシューティングガイドへのパスが必要"],"ko":[".codex/skills/registry.json에 접근해야 함","특정 도메인 구성(연구, unsloth, cuda)에 의존","실험 로그 및 문제 해결 가이드에 대한 경로가 필요"],"es":["Requiere acceso a .codex/skills/registry.json","Dependiente de configuraciones de dominio específicas (investigación, unsloth, cuda)","Necesita rutas a registros de experimentos y guías de solución de problemas"],"fr":["Nécessite un accès à .codex/skills/registry.json","Dépend de configurations de domaine spécifiques (recherche, unsloth, cuda)","A besoin de chemins d''accès aux journaux d''expérimentation et aux guides de dépannage"],"de":["Benötigt Zugriff auf .codex/skills/registry.json","Abhängig von spezifischen Domänenkonfigurationen (Forschung, unsloth, cuda)","Benötigt Pfade zu Experimentprotokollen und Fehlerbehebungsleitfäden"],"pt":["Requer acesso a .codex/skills/registry.json","Dependente de configurações de domínio específicas (pesquisa, unsloth, cuda)","Necessita de caminhos para logs de experimentos e guias de solução de problemas"],"ru":["Требует доступа к .codex/skills/registry.json","Зависит от конкретных конфигураций домена (исследование, unsloth, cuda)","Требует путей к журналам экспериментов и руководствам по устранению неполадок"],"ar":["يتطلب الوصول إلى .codex/skills/registry.json","يعتمد على تكوينات نطاق محددة (البحث، unsloth، cuda)","يحتاج إلى مسارات إلى سجلات التجارب ودلائل حل المشكلات"]},"version":4},"contentHash":"aee8bafcc8695f037bc1ca3b36b5fb323cc5cb8a7969ab045f3c0103ddc3939d","qualityScore":51}');
