INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Erland366/transformers_playground/domain-advisor', 'domain-advisor', 'Erland366', 'transformers_playground', 'community', 'domain-advisor Erland366 transformers_playground community The domain-advisor skill provides expert guidance for AI agents, helping users determine the next steps in research, experiment, or troubleshooting processes. It benefits developers and researchers seeking optimized workflows. Domain Advisor 是一个 AI Agent 技术，用于提供实验和benchmark报告，适应不同domain的行为 Domain Advisor は、実験とベンチマークレポートを提供し、さまざまなドメインの動作に適応する AI エージェント技術です Domain Advisor는 실험 및 벤치마크 보고서를 제공하고 다양한 도메인의 동작에 적응하는 AI 도구 기술입니다 El skill domain-advisor se utiliza para proporcionar asesoramiento en la planificación de proyectos de inteligencia artificial Le skill domaine-conseiller est utilisé pour offrir des conseils en planification pour les projets d''IA Der domain-advisor-Skill wird verwendet, um Beratung bei der Planung von KI-Projekten zu bieten O Domain-Advisor é uma habilidade que fornece orientação para a próxima etapa com base em relatórios de experimentos e logs de troubleshoot Domain-Advisor - это навык, который предоставляет рекомендации для следующего шага на основе отчетов экспериментов и журналов устранения неполадок ИИ Агентов Domain-Advisor هو مهارة توفر توجيهات للخطوة التالية بناءً على تقارير التجارب وسجلات حل المشكلات how to use domain-advisor domain-advisor setup guide what is domain-advisor domain-advisor alternative domain-advisor vs other AI skills installing domain-advisor configuring domain-advisor for CUDA domain-advisor for research optimization domain-advisor troubleshooting guide AIエージェント Domain Advisor 实验报告 benchmark数据 多个domain支持 初始化行为 报告提供 动作适应 Reads .codex/skills/registry.json for domain and path configurations Adapts behavior based on the domain, including research, unsloth, or CUDA Utilizes paths.reports for experiment and benchmark reports Accesses paths.experiment_log for detailed experiment logs Leverages paths.troubleshooting for guided troubleshooting domain-advisor is a skill that offers advice based on user input, utilizing registry.json for configuration and adapting behavior to specific domains such as research or CUDA.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eisles/ai-chat-app/context-loader', 'community', 'eisles', 'ai-chat-app', 'eisles/ai-chat-app', 'context-loader', 0, 0, 51, '2026-03-07T01:49:01.572Z', '2026-03-07T02:07:27.953Z', 'fc5702cb289f89bd6241b217c2ea37004e146944a5ac9814b815a79b78a174b4', '{"id":"eisles/ai-chat-app/context-loader","name":"context-loader","description":{"en":"The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI and Claude Code have the same knowledge. This skill is essential for developers working with AI agents","zh":"Context Loader 技术加载共享项目上下文，确保 Codex CLI 与 Claude Code 具有相同的知识","ja":"コンテキストローダーは共有プロジェクトコンテキストをロードし、Codex CLI と Claude Code の同期を確保する","ko":"컨텍스트 로더는 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code의 동기를 유지합니다","es":"Context Loader carga el contexto de proyecto compartido desde el directorio `.claude/` para asegurar que la CLI de Codex tenga el mismo conocimiento que Claude Code","fr":"Context Loader charge le contexte de projet partagé depuis le répertoire `.claude/` pour garantir que la CLI Codex ait les mêmes connaissances que Claude Code","de":"Context Loader lädt den gemeinsamen Projekt-Kontext aus dem Verzeichnis `.claude/`, um sicherzustellen, dass die Codex-CLI dieselben Kenntnisse wie Claude Code hat","pt":"O Context Loader é uma habilidade que carrega o contexto do projeto compartilhado do diretório `.claude/` para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code","ru":"Context Loader — это навык, который загружает общий контекст проекта из директории `.claude/`, чтобы обеспечить совместимость Codex CLI и Claude Code","ar":"المحمل السياقي هو مهارة تقوم بتحميل السياق المشترك للمشروع من الدليل `.claude/` لضمان توافق Codex CLI مع Claude Code"},"seo":{"title":{"en":"context-loader: Setup Guide for AI Agents | AI Agent Skill","zh":"Context Loader 技术指南：AI 工具加载共享项目上下文","ja":"コンテキストローダー設定ガイド：AI エージェントの共有プロジェクトコンテキストをロード","ko":"컨텍스트 로더 설정 가이드: AI 도구 공유 프로젝트 컨텍스트 로드","es":"Guía de Configuración de Context Loader para Herramientas...","fr":"Guide de Configuration de Context Loader pour Outils d''IA","de":"Einrichtungsleitfaden für Context Loader in KI-Tools","pt":"Guia de Configuração do Context Loader para Desenvolvedores","ru":"ИИ Агенты: Настройка Context Loader для Работы с Codex CLI","ar":"إعداد معيار للتحميل السياقي لتقنيات الذكاء الاصطناعي"},"description":{"en":"Discover how to load shared project context with context-loader. Learn how to integrate with Codex CLI and Claude Code for seamless development","zh":"了解 Context Loader 技术，加载共享项目上下文，确保 Codex CLI 与 Claude Code 具有相同的知识","ja":"コンテキストローダーを使用して共有プロジェクトコンテキストをロードし、Codex CLI と Claude Code の同期を確保する","ko":"컨텍스트 로더를 사용하여 공유 프로젝트 컨텍스트를 로드하고 Codex CLI와 Claude Code의 동기를 유지합니다","es":"Aprende a configurar Context Loader para cargar contexto de proyecto compartido en tu CLI de Codex","fr":"Découvrez comment configurer Context Loader pour charger le contexte de projet partagé dans votre CLI Codex","de":"Erfahren Sie, wie Sie Context Loader einrichten, um gemeinsamen Projekt-Kontext in Ihrer Codex-CLI zu laden","pt":"Aprenda a configurar o Context Loader para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code","ru":"Узнайте, как настроить Context Loader, чтобы обеспечить совместимость Codex CLI и Claude Code","ar":"تعرف على كيفية إعداد معيار التحميل السياقي لضمان توافق Codex CLI مع Claude Code"},"definition":{"en":"context-loader is a skill that loads project context from .claude/ directory to synchronize knowledge between Codex CLI and Claude Code","zh":"Context Loader 是一种 AI 工具，加载共享项目上下文以确保 Codex CLI 与 Claude Code 具有相同的知识","ja":"コンテキストローダーは、共有プロジェクトコンテキストをロードして Codex CLI と Claude Code の同期を確保する AI エージェントです","ko":"컨텍스트 로더는 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code의 동기를 유지하는 AI 도구입니다","es":"Context Loader es una habilidad que carga el contexto de proyecto compartido para la CLI de Codex","fr":"Context Loader est une compétence qui charge le contexte de projet partagé pour la CLI Codex","de":"Context Loader ist eine Fähigkeit, die den gemeinsamen Projekt-Kontext für die Codex-CLI lädt","pt":"O que é Context Loader? É uma habilidade que carrega o contexto do projeto para garantir a compatibilidade entre o Codex CLI e o Claude Code","ru":"Что такое Context Loader? Это навык, который загружает контекст проекта для обеспечения совместимости между Codex CLI и Claude Code","ar":"ما هو المحمل السياقي؟ هو مهارة تقوم بتحميل السياق المشترك للمشروع لضمان التوافق بين Codex CLI و Claude Code"},"features":{"en":["Loads coding rules from .claude/rules/ directory","Reads files such as coding-principles.md and dev-environment.md","Ensures Codex CLI has the same knowledge as Claude Code","Runs at the beginning of every task to load project context","Supports files like uv, ruff, ty, and pytest requirements"],"zh":["加载 `.claude/rules/` 目录中的编码规则","支持加载 coding-principles.md 和 dev-environment.md 文件","确保 Codex CLI 与 Claude Code 具有相同的知识","在每个任务开始时自动加载项目上下文","支持 uv、ruff、ty、pytest 等开发环境"],"ja":["`.claude/rules/` ディレクトリ内のコーディングルールをロード","coding-principles.md と dev-environment.md ファイルのロードをサポート","Codex CLI と Claude Code の同期を確保","タスクの開始時に自動的にプロジェクトコンテキストをロード","uv、ruff、ty、pytest などの開発環境をサポート"],"ko":["`.claude/rules/` 디렉토리의 코딩 규칙 로드","coding-principles.md 및 dev-environment.md 파일 로드 지원","Codex CLI와 Claude Code의 동기를 유지","작업 시작 시 자동으로 프로젝트 컨텍스트 로드","uv, ruff, ty, pytest 등 개발 환경 지원"],"es":["Carga de reglas de codificación desde `.claude/rules/`","Compatibilidad con archivos de configuración como `coding-principles.md` y `dev-environment.md`","Integración con la CLI de Codex para cargar contexto de proyecto","Soporte para la carga de contexto de proyecto en cada tarea","Lectura de archivos en el directorio `.claude/`"],"fr":["Chargement des règles de codage depuis `.claude/rules/`","Compatibilité avec des fichiers de configuration tels que `coding-principles.md` et `dev-environment.md`","Intégration avec la CLI Codex pour charger le contexte de projet","Prise en charge du chargement du contexte de projet à chaque tâche","Lecture de fichiers dans le répertoire `.claude/`"],"de":["Laden von Codierregeln aus `.claude/rules/`","Kompatibilität mit Konfigurationsdateien wie `coding-principles.md` und `dev-environment.md`","Integration mit der Codex-CLI zum Laden des Projekt-Kontexts","Unterstützung für das Laden des Projekt-Kontexts bei jeder Aufgabe","Lesen von Dateien im Verzeichnis `.claude/`"],"pt":["Carrega regras de codificação do diretório `.claude/rules/`","Suporta arquivos de regras de codificação, como `coding-principles.md` e `dev-environment.md`","Garante a compatibilidade entre o Codex CLI e o Claude Code","Executa sempre no início de cada tarefa para carregar o contexto do projeto","Suporta a leitura de arquivos de regras de codificação em formato Markdown"],"ru":["Загружает правила кодирования из директории `.claude/rules/`","Поддерживает файлы правил кодирования, такие как `coding-principles.md` и `dev-environment.md`","Обеспечивает совместимость между Codex CLI и Claude Code","Выполняется всегда в начале каждой задачи для загрузки контекста проекта","Поддерживает чтение файлов правил кодирования в формате Markdown"],"ar":["يحمل قواعد الترميز من الدليل `.claude/rules/`","يدعم الملفات قواعد الترميز، مثل `coding-principles.md` و `dev-environment.md`","يضمن التوافق بين Codex CLI و Claude Code","ينفذ دائمًا في بداية كل مهمة لتحميل السياق المشترك للمشروع","يدعم قراءة الملفات قواعد الترميز في تنسيق Markdown"]},"keywords":{"en":["how to use context-loader","context-loader setup guide","what is context-loader","context-loader alternative","context-loader vs Claude Code","context-loader install","loading project context with context-loader"],"zh":["Context Loader","AI 工具","共享项目上下文","Codex CLI","Claude Code","加载编码规则","开发环境","uv","ruff","ty","pytest"],"ja":["コンテキストローダー","AI エージェント","共有プロジェクトコンテキスト","Codex CLI","Claude Code","コーディングルールのロード","開発環境","uv","ruff","ty","pytest"],"ko":["컨텍스트 로더","AI 도구","공유 프로젝트 컨텍스트","Codex CLI","Claude Code","코딩 규칙 로드","개발 환경","uv","ruff","ty","pytest"],"es":["Context Loader","Herramientas de AI","CLI de Codex","carga de contexto de proyecto","reglas de codificación","configuración de proyecto","desarrollo de software","integración de herramientas de AI"],"fr":["Context Loader","Outils d''IA","CLI Codex","chargement de contexte de projet","règles de codage","configuration de projet","développement de logiciels","intégration d''outils d''IA"],"de":["Context Loader","KI-Tools","Codex-CLI","Laden von Projekt-Kontext","Codierregeln","Projekt-Konfiguration","Software-Entwicklung","Integration von KI-Tools"],"pt":["Context Loader","Codex CLI","Claude Code","regras de codificação","compatibilidade","desenvolvimento de software","ferramentas de desenvolvimento","AI Agents","Inteligência Artificial"],"ru":["Context Loader","Codex CLI","Claude Code","правила кодирования","совместимость","разработка программного обеспечения","инструменты разработки","ИИ Агенты","Искусственный Интеллект"],"ar":["المحمل السياقي","Codex CLI","Claude Code","قواعد الترميز","التوافق","تطوير البرمجيات","أدوات التطوير","وكلاء الذكاء الاصطناعي","الذكاء الاصطناعي"]}},"owner":"eisles","repo":"ai-chat-app","repoPath":"eisles/ai-chat-app","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.572Z","topics":[],"category":"community","skillMd":{"name":"context-loader","description":"ALWAYS activate this skill at the start of every task. Load project context from .claude/ directory including coding rules, design decisions, and documentation before executing any task.","bodyPreview":"# Context Loader Skill\n\n## Purpose\n\nLoad shared project context from `.claude/` directory to ensure Codex CLI has the same knowledge as Claude Code.\n\n## When to Activate\n\n**ALWAYS** - This skill must run at the beginning of every task to load project context.\n\n## Workflow\n\n### Step 1: Load Coding Rules\n\nRead all files in `.claude/rules/`:\n\n```\n.claude/rules/\n├── coding-principles.md   # Simplicity, single responsibility, early return\n├── dev-environment.md     # uv, ruff, ty, pytest requirements","body":"# Context Loader Skill\n\n## Purpose\n\nLoad shared project context from `.claude/` directory to ensure Codex CLI has the same knowledge as Claude Code.\n\n## When to Activate\n\n**ALWAYS** - This skill must run at the beginning of every task to load project context.\n\n## Workflow\n\n### Step 1: Load Coding Rules\n\nRead all files in `.claude/rules/`:\n\n```\n.claude/rules/\n├── coding-principles.md   # Simplicity, single responsibility, early return\n├── dev-environment.md     # uv, ruff, ty, pytest requirements\n├── language.md            # Think in English, respond in Japanese\n├── security.md            # Secrets, validation, SQLi/XSS prevention\n├── testing.md             # TDD, AAA pattern, 80% coverage\n└── codex-delegation.md    # (skip - not relevant for Codex itself)\n```\n\n### Step 2: Load Design Documentation\n\nRead `.claude/docs/DESIGN.md` for:\n- Architecture decisions\n- Implementation patterns\n- Library choices and constraints\n- TODO items and open questions\n\n### Step 3: Check Library Documentation\n\nIf the task involves specific libraries, read relevant files from:\n```\n.claude/docs/libraries/\n```\n\n### Step 4: Execute Task\n\nWith the loaded context, execute the requested task following:\n- Coding principles from rules\n- Design decisions from DESIGN.md\n- Library constraints from docs\n\n## Key Rules to Remember\n\nAfter loading, always follow these principles:\n\n1. **Simplicity first** - Choose readable code over complex\n2. **Single responsibility** - One function/class does one thing\n3. **Type hints required** - All functions need annotations\n4. **Use uv** - Never use pip directly\n5. **Security** - No hardcoded secrets, validate input, parameterize SQL\n\n## Language Protocol\n\n- **Thinking/Reasoning**: English\n- **Code**: English (variables, functions, comments)\n- **User communication**: Japanese (when reporting back through Claude Code)\n\n## Output\n\nAfter loading context, briefly confirm:\n- Rules loaded\n- Design document status\n- Ready to execute task\n"},"lastSynced":"2026-03-07T02:07:27.953Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Codex CLI and Claude Code needing synchronized project knowledge and context","zh":"非常适合像 Codex CLI 和 Claude Code 这样的 AI Agents，它们需要同步的项目知识和上下文","ja":"Codex CLI や Claude Code などの同期されたプロジェクトの知識とコンテキストが必要な AI エージェントに最適","ko":"Codex CLI 및 Claude Code와 같은 AI 에이전트가 프로젝트 지식과 컨텍스트를 동기화해야 하는 경우에 적합","es":"Perfecto para agentes de IA como Codex CLI y Claude Code que necesitan conocimiento y contexto de proyecto sincronizado","fr":"Parfait pour les agents IA comme Codex CLI et Claude Code nécessitant une connaissance et un contexte de projet synchronisés","de":"Perfekt für KI-Agenten wie Codex CLI und Claude Code, die synchronisiertes Projektwissen und -kontext benötigen","pt":"Perfeito para Agentes de IA como Codex CLI e Claude Code que necessitam de conhecimento de projeto e contexto sincronizados","ru":"Идеально для агентов ИИ, таких как Codex CLI и Claude Code, которым необходим синхронизированный проектный знания и контекст","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Codex CLI و Claude Code الذين يحتاجون إلى معرفة مشروع ومعلومات سياق متزامنة"},"recommendation":{"en":"Empowers agents to load shared project context from .claude/ directories, ensuring consistency with coding rules and dev environment requirements, utilizing files like coding-principles.md and dev-environment.md","zh":"赋予代理从 .claude/ 目录加载共享的项目上下文，确保与编码规则和开发环境要求的一致性，使用诸如 coding-principles.md 和 dev-environment.md 之类的文件","ja":"エージェントが .claude/ ディレクトリから共有されたプロジェクトのコンテキストを読み込むことを可能にし、coding-principles.md や dev-environment.md などのファイルを使用して、コード規則や開発環境の要件との一貫性を確保する","ko":"에이전트가 .claude/ 디렉토리에서 공유 프로젝트 컨텍스트를 로드할 수 있도록 하여 coding-principles.md 및 dev-environment.md와 같은 파일을 사용하여 코딩 규칙 및 개발 환경 요구 사항과 일관성을 보장","es":"Habilita a los agentes para cargar el contexto de proyecto compartido desde directorios .claude/, garantizando la consistencia con las reglas de codificación y los requisitos del entorno de desarrollo, utilizando archivos como coding-principles.md y dev-environment.md","fr":"Permet aux agents de charger le contexte de projet partagé à partir de répertoires .claude/, en garantissant la cohérence avec les règles de codage et les exigences de l''environnement de développement, en utilisant des fichiers comme coding-principles.md et dev-environment.md","de":"Ermöglicht es den Agenten, den gemeinsamen Projekt-Kontext aus .claude/-Verzeichnissen zu laden, wodurch die Konsistenz mit den Codierregeln und den Anforderungen der Entwicklerumgebung sichergestellt wird, unter Verwendung von Dateien wie coding-principles.md und dev-environment.md","pt":"Habilita os agentes a carregar o contexto do projeto compartilhado dos diretórios .claude/, garantindo a consistência com as regras de codificação e os requisitos do ambiente de desenvolvimento, utilizando arquivos como coding-principles.md e dev-environment.md","ru":"Позволяет агентам загружать общий контекст проекта из директорий .claude/, обеспечивая согласованность с правилами кодирования и требованиями среды разработки, используя файлы типа coding-principles.md и dev-environment.md","ar":"يمنح الوكلاء khảية تحميل السياق المشترك للمشروع من المجلدات .claude/، مما يضمن الاتساق مع قواعد البرمجة ومتطلبات بيئة التطوير، باستخدام ملفات مثل coding-principles.md و dev-environment.md"},"useCases":{"en":["Loading project-specific coding rules","Ensuring consistent developer environment settings","Synchronizing knowledge between Codex CLI and Claude Code"],"zh":["加载项目特定的编码规则","确保开发环境设置的一致性","在 Codex CLI 和 Claude Code 之间同步知识"],"ja":["プロジェクト固有のコード規則を読み込む","開発環境設定の一貫性を確保する","Codex CLI と Claude Code の間で知識を同期する"],"ko":["프로젝트별 코딩 규칙을 로드","개발자 환경 설정의 일관성을 보장","Codex CLI 및 Claude Code 간의 지식 동기화"],"es":["Carga de reglas de codificación específicas del proyecto","Garantizar la configuración coherente del entorno de desarrollo","Sincronización del conocimiento entre Codex CLI y Claude Code"],"fr":["Chargement des règles de codage spécifiques au projet","Assurer les paramètres d''environnement de développement cohérents","Synchronisation des connaissances entre Codex CLI et Claude Code"],"de":["Laden von projektspezifischen Codierregeln","Sicherstellung konsistenter Einstellungen für die Entwicklerumgebung","Synchronisierung von Wissen zwischen Codex CLI und Claude Code"],"pt":["Carregar regras de codificação específicas do projeto","Garantir configurações de ambiente de desenvolvedor consistentes","Sincronizar conhecimento entre Codex CLI e Claude Code"],"ru":["Загрузка правил кодирования, специфичных для проекта","Обеспечение согласованных настроек среды разработки","Синхронизация знаний между Codex CLI и Claude Code"],"ar":["تحميل قواعد البرمجة الخاصة بالمشروع","ضمان إعدادات بيئة التطوير المتسقة","تنسيق المعرفة بين Codex CLI و Claude Code"]},"limitations":{"en":["Requires access to .claude/ directory","Limited to projects with .claude/ directory structure"],"zh":["需要访问 .claude/ 目录","仅限于具有 .claude/ 目录结构的项目"],"ja":[".claude/ ディレクトリへのアクセスが必要",".claude/ ディレクトリ構造を持つプロジェクトのみに制限"],"ko":[".claude/ 디렉토리에 대한 액세스가 필요",".claude/ 디렉토리 구조를 가진 프로젝트에만 제한"],"es":["Requiere acceso al directorio .claude/","Limitado a proyectos con estructura de directorio .claude/"],"fr":["Nécessite l''accès au répertoire .claude/","Limité aux projets avec une structure de répertoire .claude/"],"de":["Erfordert Zugriff auf das Verzeichnis .claude/","Begrenzt auf Projekte mit .claude/-Verzeichnisstruktur"],"pt":["Requer acesso ao diretório .claude/","Limitado a projetos com estrutura de diretório .claude/"],"ru":["Требует доступа к директории .claude/","Ограничен проектами с структурой директории .claude/"],"ar":["يتطلب الوصول إلى المجلد .claude/","محدود بالمشاريع التي تحتوي على هيكل المجلد .claude/"]},"version":4},"contentHash":"fc5702cb289f89bd6241b217c2ea37004e146944a5ac9814b815a79b78a174b4","qualityScore":51}');
