INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eisles/ai-chat-app/context-loader', 'context-loader', 'eisles', 'ai-chat-app', 'community', 'context-loader eisles ai-chat-app community The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI and Claude Code have the same knowledge. This skill is essential for developers working with AI agents Context Loader 技术加载共享项目上下文，确保 Codex CLI 与 Claude Code 具有相同的知识 コンテキストローダーは共有プロジェクトコンテキストをロードし、Codex CLI と Claude Code の同期を確保する 컨텍스트 로더는 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code의 동기를 유지합니다 Context Loader carga el contexto de proyecto compartido desde el directorio `.claude/` para asegurar que la CLI de Codex tenga el mismo conocimiento que Claude Code Context Loader charge le contexte de projet partagé depuis le répertoire `.claude/` pour garantir que la CLI Codex ait les mêmes connaissances que Claude Code Context Loader lädt den gemeinsamen Projekt-Kontext aus dem Verzeichnis `.claude/`, um sicherzustellen, dass die Codex-CLI dieselben Kenntnisse wie Claude Code hat O Context Loader é uma habilidade que carrega o contexto do projeto compartilhado do diretório `.claude/` para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code Context Loader — это навык, который загружает общий контекст проекта из директории `.claude/`, чтобы обеспечить совместимость Codex CLI и Claude Code المحمل السياقي هو مهارة تقوم بتحميل السياق المشترك للمشروع من الدليل `.claude/` لضمان توافق Codex CLI مع Claude Code how to use context-loader context-loader setup guide what is context-loader context-loader alternative context-loader vs Claude Code context-loader install loading project context with context-loader Context Loader AI 工具 共享项目上下文 Codex CLI Claude Code 加载编码规则 开发环境 uv ruff ty pytest Loads coding rules from .claude/rules/ directory Reads files such as coding-principles.md and dev-environment.md Ensures Codex CLI has the same knowledge as Claude Code Runs at the beginning of every task to load project context Supports files like uv, ruff, ty, and pytest requirements context-loader is a skill that loads project context from .claude/ directory to synchronize knowledge between Codex CLI and Claude Code');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Moffran/calibrated_explanations/ce-plugin-audit', 'community', 'Moffran', 'calibrated_explanations', 'Moffran/calibrated_explanations', 'ce-plugin-audit', 74, 12, 50, '2026-03-02T12:26:27Z', '2026-03-06T06:33:57.310Z', '63796e934d48c3f0abb1d18c2ef5845f06e6146aef1091b10a2ce81dfad91094', '{"id":"Moffran/calibrated_explanations/ce-plugin-audit","name":"ce-plugin-audit","description":{"en":"The ce-plugin-audit skill audits a plugin''s conformance with the Calibrated Explanations (CE) plugin contract, benefiting AI agent developers. It runs through each audit dimension to produce a structured report.","zh":"CE 插件审计工具用于检查插件的合规性，确保 plugin_meta 字段正确","ja":"CE プラグイン監査ツールはプラグインの合规性をチェックし、plugin_meta フィールドを正しく設定する","ko":"CE 플러그인 감사 도구는 플러그인의 규정 준수를 확인하고 plugin_meta 필드를 올바르게 설정합니다","es":"ce-plugin-audit es una herramienta para auditar plugins y verificar su conformidad con el contrato de plugin CE","fr":"ce-plugin-audit est un outil pour auditer des plugins et vérifier leur conformité avec le contrat de plugin CE","de":"ce-plugin-audit ist ein Tool zum Auditen von Plugins und zur Überprüfung ihrer Konformität mit dem CE-Plugin-Vertrag","pt":"O ce-plugin-audit é uma ferramenta para auditoria de plugins CE. Ele verifica a conformidade com o contrato de plugin CE e gera um relatório estruturado.","ru":"Ce-plugin-audit — это инструмент для аудита плагинов CE. Он проверяет соответствие контракту плагина CE и генерирует структурированный отчет.","ar":"ce-plugin-audit هو أداة لمراجعة بلوغات CE. يقوم بفحص مطابقة عقد البلوغ CE وينشئ تقريرًا منظمًا."},"seo":{"title":{"en":"ce-plugin-audit: Calibrated Explanations Plugin Audit Gui...","zh":"CE 插件审计工具 Setup Guide","ja":"CE プラグイン監査ツール Best Practices","ko":"CE 플러그인 감사 도구 설정 가이드","es":"Guía de configuración de ce-plugin-audit para agentes de IA","fr":"Guide de mise en place de ce-plugin-audit pour les outils...","de":"Einrichtungsleitfaden für ce-plugin-audit für KI-Tools","pt":"Guia de Configuração do ce-plugin-audit para Ferramentas ...","ru":"Настройка ce-plugin-audit для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد ce-plugin-audit لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of Calibrated Explanations with the ce-plugin-audit skill. Learn how to audit plugins and ensure conformance with the CE contract.","zh":"使用 CE 插件审计工具进行插件合规性检查，确保 plugin_meta 字段正确","ja":"CE プラグイン監査ツールを使用してプラグインの合规性をチェックし、plugin_meta フィールドを正しく設定する","ko":"CE 플러그인 감사 도구를 사용하여 플러그인의 규정 준수를 확인하고 plugin_meta 필드를 올바르게 설정합니다","es":"Aprende a auditar plugins con ce-plugin-audit y asegúrate de su conformidad con el contrato de plugin CE","fr":"Découvrez comment auditer des plugins avec ce-plugin-audit et assurez-vous de leur conformité avec le contrat de plugin CE","de":"Erfahren Sie, wie Sie Plugins mit ce-plugin-audit auditen und ihre Konformität mit dem CE-Plugin-Vertrag sicherstellen","pt":"Aprenda a configurar o ce-plugin-audit para garantir a conformidade com o contrato de plugin CE. Obtenha dicas e melhores práticas para desenvolvedores.","ru":"Узнайте, как настроить ce-plugin-audit для обеспечения соответствия контракту плагина CE. Получите советы и лучшие практики для разработчиков.","ar":"تعرف على كيفية إعداد ce-plugin-audit لضمان مطابقة عقد البلوغ CE. احصل على نصائح وأفضل الممارسات للمطورين."},"definition":{"en":"ce-plugin-audit is a repository for explaining the Calibrated Explanations method, providing a plugin contract audit process.","zh":"CE 插件审计工具是一种用于检查插件合规性的工具，确保 plugin_meta 字段正确","ja":"CE プラグイン監査ツールはプラグインの合规性をチェックするツールであり、plugin_meta フィールドを正しく設定する","ko":"CE 플러그인 감사 도구는 플러그인의 규정 준수를 확인하는 도구로 plugin_meta 필드를 올바르게 설정합니다","es":"ce-plugin-audit es un método de explicación para auditar plugins y verificar su conformidad con el contrato de plugin CE","fr":"ce-plugin-audit est une méthode d''explication pour auditer des plugins et vérifier leur conformité avec le contrat de plugin CE","de":"ce-plugin-audit ist eine Erklärungsmethode zum Auditen von Plugins und zur Überprüfung ihrer Konformität mit dem CE-Plugin-Vertrag","pt":"O ce-plugin-audit é uma ferramenta de auditoria de plugins que verifica a conformidade com o contrato de plugin CE.","ru":"Ce-plugin-audit — это инструмент аудита плагинов, который проверяет соответствие контракту плагина CE.","ar":"ce-plugin-audit هو أداة مراجعة بلوغات التي تفحص مطابقة عقد البلوغ CE."},"features":{"en":["Runs `validate_plugin_meta(plugin.plugin_meta)` to check plugin metadata","Audits `plugin_meta` fields such as `schema_version`, `name`, and `version`","Checks for correct types, including `int` and non-empty `str`","Produces a structured report based on audit dimensions","Enforces conformance with the CE plugin contract (ADR-006)"],"zh":["支持 plugin_meta 字段检查","检查 schema_version 是否为 1","验证 name 和 version 字段","支持多种字段类型检查","生成结构化报告"],"ja":["plugin_meta フィールドのチェックをサポート","schema_version が 1 であることをチェック","name と version フィールドを検証","複数のフィールドタイプのチェックをサポート","構造化レポートの生成"],"ko":["plugin_meta 필드 확인 지원","schema_version 가 1인지 확인","name 및 version 필드 검증","다중 필드 유형 확인 지원","구조화된 보고서 생성"],"es":["Validación de metadatos de plugin con validate_plugin_meta","Verificación de la versión de esquema del plugin","Comprobación del nombre y versión del plugin","Soporte para contrato de plugin CE","Generación de informes estructurados para la auditoría"],"fr":["Validation des métadonnées de plugin avec validate_plugin_meta","Vérification de la version de schéma du plugin","Vérification du nom et de la version du plugin","Prise en charge du contrat de plugin CE","Génération de rapports structurés pour l''audit"],"de":["Validierung von Plug-in-Metadaten mit validate_plugin_meta","Überprüfung der Schema-Version des Plug-ins","Überprüfung des Namens und der Version des Plug-ins","Unterstützung für den CE-Plugin-Vertrag","Erstellung von strukturierten Berichten für die Audit"],"pt":["Verificação da conformidade com o contrato de plugin CE","Geração de relatório estruturado","Validação de metadados de plugin (plugin_meta)","Verificação da versão do schema","Verificação do nome e versão do plugin"],"ru":["Проверка соответствия контракту плагина CE","Генерация структурированного отчета","Валидация метаданных плагина (plugin_meta)","Проверка версии схемы","Проверка имени и версии плагина"],"ar":["فحص مطابقة عقد البلوغ CE","إنشاء تقرير منظم","تحقق من البيانات الوصفية للبلوغ (plugin_meta)","فحص إصدار مخطط","فحص اسم و إصدار البلوغ"]},"keywords":{"en":["how to use ce-plugin-audit","ce-plugin-audit setup guide","calibrated explanations plugin contract","ce-plugin-audit alternative","ce-plugin-audit vs other audit tools","install ce-plugin-audit","ce-plugin-audit tutorial","what is ce-plugin-audit","ce-plugin-audit documentation"],"zh":["CE 插件审计工具","AIエージェント","plugin_meta 字段检查","schema_version","name 和 version 字段","结构化报告","CE 插件合规性检查"],"ja":["CE プラグイン監査ツール","AIエージェント","plugin_meta フィールドのチェック","schema_version","name と version フィールド","構造化レポート","CE プラグイン合规性チェック"],"ko":["CE 플러그인 감사 도구","AI 에이전트","plugin_meta 필드 확인","schema_version","name 및 version 필드","구조화된 보고서","CE 플러그인 규정 준수 확인"],"es":["ce-plugin-audit","agentes de IA","auditoría de plugins","contrato de plugin CE","validación de metadatos","explicación de plugins","herramientas de IA","desarrollo de plugins","integración de plugins"],"fr":["ce-plugin-audit","outils d''IA","audit de plugins","contrat de plugin CE","validation de métadonnées","explication de plugins","développement de plugins","intégration de plugins","technologies d''IA"],"de":["ce-plugin-audit","KI-Tools","Plugin-Audit","CE-Plugin-Vertrag","Validierung von Metadaten","Erklärung von Plugins","Plugin-Entwicklung","Plugin-Integration","KI-Technologien"],"pt":["ce-plugin-audit","ferramentas de ia","auditoria de plugins","contrato de plugin ce","desenvolvimento de plugins","validação de metadados","geração de relatórios"],"ru":["ce-plugin-audit","ии агенты","аудит плагинов","контракт плагина ce","разработка плагинов","валидация метаданных","генерация отчетов"],"ar":["ce-plugin-audit","أدوات الذكاء الاصطناعي","مراجعة بلوغات","عقد البلوغ ce","تطوير بلوغات","تحقق من البيانات الوصفية","إنشاء تقارير"]}},"owner":"Moffran","repo":"calibrated_explanations","repoPath":"Moffran/calibrated_explanations","stars":74,"forks":12,"updatedAt":"2026-03-02T12:26:27Z","topics":[],"category":"community","skillMd":{"name":"ce-plugin-audit","description":">","bodyPreview":"# CE Plugin Audit\n\nYou are auditing a plugin''s conformance with the CE plugin contract.\nRun through each audit dimension below and produce a structured report.\n\n---\n\n## Audit Dimension 1 — `plugin_meta` (ADR-006)\n\nRun `validate_plugin_meta(plugin.plugin_meta)` and check:\n\n| Field | Required | Correct type | Notes |\n|---|---|---|---|\n| `schema_version` | ✅ | `int` | Must be `1` for current contract |\n| `name` | ✅ | non-empty `str` | Recommend reverse-DNS |\n| `version` | ✅ | non-empty `str` | Sema","body":"# CE Plugin Audit\n\nYou are auditing a plugin''s conformance with the CE plugin contract.\nRun through each audit dimension below and produce a structured report.\n\n---\n\n## Audit Dimension 1 — `plugin_meta` (ADR-006)\n\nRun `validate_plugin_meta(plugin.plugin_meta)` and check:\n\n| Field | Required | Correct type | Notes |\n|---|---|---|---|\n| `schema_version` | ✅ | `int` | Must be `1` for current contract |\n| `name` | ✅ | non-empty `str` | Recommend reverse-DNS |\n| `version` | ✅ | non-empty `str` | Semantic version |\n| `provider` | ✅ | non-empty `str` | Author/org attribution |\n| `capabilities` | ✅ | non-empty `list[str]` | Each tag non-empty |\n| `trusted` | optional | `bool` | Built-ins set `True`; third-party `False` |\n| `data_modalities` | optional (ADR-033) | `tuple[str, ...]` | Normalised lowercase; validated taxonomy |\n| `plugin_api_version` | optional (ADR-033) | `\"MAJOR.MINOR\"` str | Default `\"1.0\"` |\n\n```python\nfrom calibrated_explanations.plugins.base import validate_plugin_meta\nvalidate_plugin_meta(plugin.plugin_meta)   # raises ValidationError on non-conformance\n```\n\n---\n\n## Audit Dimension 2 — Capability tags (ADR-015)\n\nEach capability tag must match a defined CE capability:\n\n| Expected tag | Plugin type |\n|---|---|\n| `\"interval:classification\"` | Classification calibrator |\n| `\"interval:regression\"` | Regression calibrator |\n| `\"explanation:factual\"`, `\"explanation:alternative\"`, `\"explanation:fast\"` | Explanation |\n| `\"plot:legacy\"`, `\"plot:plotspec\"` | Plot |\n\n**Red flag:** Plugin lists no capability tags, or lists tags it doesn''t implement.\n\n---\n\n## Audit Dimension 3 — Interval calibrator protocol (ADR-013)\n\nIf `\"interval:classification\"` or `\"interval:regression\"` in capabilities:\n\n```python\n# Required: predict_proba must match VennAbers surface exactly\ndef predict_proba(\n    self, x, *, output_interval: bool = False, classes=None, bins=None\n) -> np.ndarray: ...\n# Shapes: (n_samples, n_classes) when output_interval=False\n#         (n_samples, n_classes, 3) when output_interval=True (predict, low, high)\n\ndef is_multiclass(self) -> bool: ...\ndef is_mondrian(self) -> bool: ...\n```\n\nFor regression (`\"interval:regression\"`), additional surface required:\n```python\ndef predict_probability(self, x) -> np.ndarray: ...  # shape (n_samples, 2): (low, high)\ndef predict_uncertainty(self, x) -> np.ndarray: ...  # shape (n_samples, 2): (width, confidence)\ndef pre_fit_for_probabilistic(self, x, y) -> None: ...\ndef compute_proba_cal(self, x, y, *, weights=None) -> np.ndarray: ...\ndef insert_calibration(self, x, y, *, warm_start: bool = False) -> None: ...\n```\n\n**Critical:** `predict_proba` must delegate to VennAbers/IntervalRegressor reference logic\nto preserve calibration guarantees (ADR-021). A plugin that replaces the probability\nmaths wholesale is non-conformant.\n\n**Context immutability:** The plugin must NOT mutate fields in the\n`IntervalCalibratorContext` passed to `create()`.\n\n---\n\n## Audit Dimension 4 — ADR-001: Core / plugin boundary\n\n**FAIL if** the plugin imports anything from `calibrated_explanations.core.*`\nthat is not a protocol, dataclass, or exception:\n\n```python\n# OK — passive types\nfrom calibrated_explanations.core.exceptions import ValidationError\n\n# NOT OK — implementation details\nfrom calibrated_explanations.core.calibrated_explainer import CalibratedExplainer  # red flag\n```\n\nCheck with:\n```bash\ngrep -r \"from calibrated_explanations.core\" src/your_plugin/\n```\n\n---\n\n## Audit Dimension 5 — Fallback visibility (mandatory copilot-instructions.md §7)\n\nAll fallback decisions inside the plugin must be visible:\n```python\nimport warnings, logging\n_LOGGER = logging.getLogger(\"calibrated_explanations.plugins.<name>\")\n\n# BAD — silent fallback\nif something_failed:\n    use_legacy_path()\n\n# GOOD — visible fallback\nif something_failed:\n    msg = \"MyPlugin: <reason>. Falling back to legacy path.\"\n    _LOGGER.info(msg)\n    warnings.warn(msg, UserWarning, stacklevel=2)\n    use_legacy_path()\n```\n\n---\n\n## Audit Dimension 6 — Lazy imports (source-code.instructions.md)\n\nHeavy optional dependencies must be imported lazily:\n```python\n# BAD\nimport matplotlib.pyplot as plt   # top-level in a module reachable from package root\n\n# GOOD\ndef render(self, ...):\n    import matplotlib.pyplot as plt  # inside function body\n```\n\n---\n\n## Audit Dimension 7 — ADR-033 modality contract (if applicable)\n\nIf the plugin targets a non-tabular modality (`\"image\"`, `\"audio\"`, `\"text\"`,\n`\"timeseries\"`, `\"multimodal\"`, or `\"x-<vendor>-<name>\"`):\n\n- `data_modalities` must be present in `plugin_meta`.\n- Modality strings must be in the canonical taxonomy or use the `x-<vendor>-<name>` namespace.\n- Aliases (`\"vision\" → \"image\"`, `\"time_series\" → \"timeseries\"`) are acceptable inputs but\n  are normalised to canonical form by the registry.\n- `plugin_api_version` must be present; major-version mismatch causes a registry rejection.\n\n---\n\n## Report Template\n\n```\nPlugin Audit Report: <plugin name>\n===================================\nplugin_meta validation:        PASS / FAIL\n  details: <fieldname: issue>\n\nCapability tags:               PASS / FAIL / N_A\n  declared: [...]\n  implemented: [...]\n\nInterval protocol (ADR-013):   PASS / FAIL / N_A\n  predict_proba shape:         PASS / FAIL\n  context immutability:        PASS / FAIL\n  delegates to reference:      YES / NO\n\nADR-001 core boundary:         PASS / FAIL\n  violations: <list>\n\nFallback visibility:           PASS / FAIL\n  missing warn():              <method names>\n\nLazy imports:                  PASS / FAIL\n  eager heavy imports:         <list>\n\nADR-033 modality (if used):    PASS / FAIL / N_A\n  data_modalities:             <value>\n  plugin_api_version:          <value>\n\nOverall:   CONFORMANT / NON-CONFORMANT (N issues)\n```\n\n---\n\n## Evaluation Checklist\n\n- [ ] `validate_plugin_meta()` called and passes.\n- [ ] All declared capabilities have corresponding implementations.\n- [ ] Context not mutated in `create()`.\n- [ ] `predict_proba` delegates to VennAbers / IntervalRegressor for probability maths.\n- [ ] No imports of `core/` implementation details.\n- [ ] Every fallback emits `warnings.warn + _LOGGER.info`.\n- [ ] No eager top-level imports of matplotlib/pandas/joblib.\n- [ ] ADR-033 metadata present if non-tabular modality targeted.\n"},"lastSynced":"2026-03-06T06:33:57.310Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing comprehensive plugin audits for Calibrated Explanations (CE) plugin contract conformance.","zh":"非常适合需要对校准解释（CE）插件合同进行全面插件审计的AI代理开发人员。","ja":"カリブレーション解釈（CE）プラグイン契約の包括的なプラグイン監査が必要なAIエージェント開発者に最適です。","ko":"칼리브레이션 설명(CE) 플러그인 계약에 대한 포괄적인 플러그인 감사를 필요로 하는 AI 에이전트 개발자를 위한 최적의 솔루션입니다.","es":"Perfecto para desarrolladores de agentes de inteligencia artificial que necesitan auditorías de plugins comprehensivas para la conformidad del contrato de plugin de Explicaciones Calibradas (CE).","fr":"Parfait pour les développeurs d''agents d''intelligence artificielle ayant besoin d''audits de plugins complets pour la conformité du contrat de plugin d''Explications Calibrées (CE).","de":"Perfekt für Entwickler von KI-Agenten, die umfassende Plugin-Audits für die Konformität des CE-Plugin-Vertrags benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que precisam de auditorias de plugins abrangentes para conformidade com o contrato do plugin de Explicações Calibradas (CE).","ru":"Идеально подходит для разработчиков агентов ИИ, которым требуются всесторонние аудиты плагинов для соблюдения контракта плагина Калиброванных Объяснений (CE).","ar":"مثالي لِمُطوّرين وكلاء الذكاء الاصطناعي الذين يحتاجون إلى تدقيقات شاملة للإضافات لملاءمة عقد إضافات الشرح المُقنّن (CE)."},"recommendation":{"en":"Empowers agents to validate plugin metadata, including schema version, name, and version, ensuring adherence to the CE plugin contract using dimensions like `plugin_meta` (ADR-006) and producing structured reports.","zh":"赋予代理验证插件元数据的能力，包括架构版本、名称和版本，确保遵守CE插件合同，使用诸如`plugin_meta`（ADR-006）等维度，并生成结构化报告。","ja":"エージェントにプラグインメタデータ（スキーマバージョン、名前、バージョンなど）を検証する能力を与え、CEプラグイン契約への準拠を確保し、`plugin_meta`（ADR-006）などの次元を使用して構造化レポートを生成する。","ko":"에이전트에게 플러그인 메타데이터(스키마 버전, 이름, 버전 등)를 검증할 수 있는 능력을 부여하여 CE 플러그인 계약의 준수를 보장하고, `plugin_meta`(ADR-006)와 같은 차원을 사용하여 구조화된 보고서를 생성합니다.","es":"Habilita a los agentes a validar los metadatos del plugin, incluyendo la versión del esquema, el nombre y la versión, garantizando el cumplimiento del contrato de plugin de CE utilizando dimensiones como `plugin_meta` (ADR-006) y produciendo informes estructurados.","fr":"Permet aux agents de valider les métadonnées du plugin, y compris la version du schéma, le nom et la version, en garantissant la conformité au contrat de plugin d''Explications Calibrées en utilisant des dimensions comme `plugin_meta` (ADR-006) et en produisant des rapports structurés.","de":"Ermächtigt die Agenten, die Metadaten des Plugins zu validieren, einschließlich der Schemaversion, des Namens und der Version, und stellt sicher, dass der CE-Plugin-Vertrag eingehalten wird, indem Dimensionen wie `plugin_meta` (ADR-006) verwendet werden, und produziert strukturierte Berichte.","pt":"Habilita os agentes a validar os metadados do plugin, incluindo a versão do esquema, o nome e a versão, garantindo a adesão ao contrato do plugin CE usando dimensões como `plugin_meta` (ADR-006) e produzindo relatórios estruturados.","ru":"Наделяет агентов возможностью проверять метаданные плагина, включая версию схемы, имя и версию, обеспечивая соблюдение контракта плагина CE с использованием размеров, таких как `plugin_meta` (ADR-006), и генерируя структурированные отчеты.","ar":"يُمكّن الوكلاء من التحقق من بيانات الإضافة الوصفية، بما في ذلك إصدار مخطط البيانات واسم الإضافة وإصدارها، مما يضمن الامتثال لاتفاق إضافات CE باستخدام أبعاد مثل `plugin_meta` (ADR-006) وإنتاج تقارير منسقة."},"useCases":{"en":["Auditing plugin conformance with CE plugin contract","Validating plugin metadata for schema version and name","Generating structured reports for plugin audit dimensions"],"zh":["审计插件与CE插件合同的一致性","验证插件元数据的架构版本和名称","为插件审计维度生成结构化报告"],"ja":["プラグインとCEプラグイン契約の準拠性を監査する","プラグインメタデータのスキーマバージョンと名前を検証する","プラグイン監査の次元の構造化レポートを生成する"],"ko":["플러그인과 CE 플러그인 계약의 준수성을 감사하는 것","플러그인 메타데이터의 스키마 버전과 이름을 검증하는 것","플러그인 감사 차원의 구조화된 보고서를 생성하는 것"],"es":["Auditoría de la conformidad del plugin con el contrato de plugin de CE","Validación de los metadatos del plugin para la versión del esquema y el nombre","Generación de informes estructurados para las dimensiones de auditoría de plugins"],"fr":["Audit de la conformité du plugin avec le contrat de plugin d''Explications Calibrées","Validation des métadonnées du plugin pour la version du schéma et le nom","Génération de rapports structurés pour les dimensions d''audit de plugins"],"de":["Prüfung der Konformität des Plugins mit dem CE-Plugin-Vertrag","Validierung der Metadaten des Plugins für die Schemaversion und den Namen","Erstellung strukturierter Berichte für die Prüfdimensionen des Plugins"],"pt":["Auditoria de conformidade do plugin com o contrato do plugin CE","Validação dos metadados do plugin para versão do esquema e nome","Geração de relatórios estruturados para dimensões de auditoria de plugin"],"ru":["Аудит соответствия плагина контракту плагина CE","Проверка метаданных плагина на версию схемы и имя","Генерация структурированных отчетов для размеров аудита плагина"],"ar":["تدقيق امتثال الإضافة لاتفاق إضافات CE","التحقق من بيانات الإضافة الوصفية لإصدار مخطط البيانات واسم الإضافة","إنتاج تقارير منسقة لأبعاد تدقيق الإضافة"]},"limitations":{"en":["Requires access to plugin metadata","Specific to Calibrated Explanations (CE) plugin contract"],"zh":["需要访问插件元数据","特定于校准解释（CE）插件合同"],"ja":["プラグインメタデータへのアクセスが必要","カリブレーション解釈（CE）プラグイン契約に特有"],"ko":["플러그인 메타데이터에 대한 액세스가 필요함","칼리브레이션 설명(CE) 플러그인 계약에 특정"],"es":["Requiere acceso a los metadatos del plugin","Específico para el contrato de plugin de Explicaciones Calibradas (CE)"],"fr":["Nécessite l''accès aux métadonnées du plugin","Spécifique au contrat de plugin d''Explications Calibrées (CE)"],"de":["Benötigt Zugriff auf die Metadaten des Plugins","Spezifisch für den CE-Plugin-Vertrag"],"pt":["Requer acesso aos metadados do plugin","Específico para o contrato do plugin de Explicações Calibradas (CE)"],"ru":["Требует доступа к метаданным плагина","Специфичен для контракта плагина Калиброванных Объяснений (CE)"],"ar":["يتطلب الوصول إلى بيانات الإضافة الوصفية","محدد لاتفاق إضافات الشرح المُقنّن (CE)"]},"version":4},"contentHash":"63796e934d48c3f0abb1d18c2ef5845f06e6146aef1091b10a2ce81dfad91094","qualityScore":50}');
