INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Moffran/calibrated_explanations/ce-plugin-audit', 'ce-plugin-audit', 'Moffran', 'calibrated_explanations', 'community', 'ce-plugin-audit Moffran calibrated_explanations community The ce-plugin-audit skill audits a plugin''s conformance with the Calibrated Explanations (CE) plugin contract, benefiting AI agent developers. It runs through each audit dimension to produce a structured report. CE 插件审计工具用于检查插件的合规性，确保 plugin_meta 字段正确 CE プラグイン監査ツールはプラグインの合规性をチェックし、plugin_meta フィールドを正しく設定する CE 플러그인 감사 도구는 플러그인의 규정 준수를 확인하고 plugin_meta 필드를 올바르게 설정합니다 ce-plugin-audit es una herramienta para auditar plugins y verificar su conformidad con el contrato de plugin CE ce-plugin-audit est un outil pour auditer des plugins et vérifier leur conformité avec le contrat de plugin CE ce-plugin-audit ist ein Tool zum Auditen von Plugins und zur Überprüfung ihrer Konformität mit dem CE-Plugin-Vertrag O ce-plugin-audit é uma ferramenta para auditoria de plugins CE. Ele verifica a conformidade com o contrato de plugin CE e gera um relatório estruturado. Ce-plugin-audit — это инструмент для аудита плагинов CE. Он проверяет соответствие контракту плагина CE и генерирует структурированный отчет. ce-plugin-audit هو أداة لمراجعة بلوغات CE. يقوم بفحص مطابقة عقد البلوغ CE وينشئ تقريرًا منظمًا. how to use ce-plugin-audit ce-plugin-audit setup guide calibrated explanations plugin contract ce-plugin-audit alternative ce-plugin-audit vs other audit tools install ce-plugin-audit ce-plugin-audit tutorial what is ce-plugin-audit ce-plugin-audit documentation CE 插件审计工具 AIエージェント plugin_meta 字段检查 schema_version name 和 version 字段 结构化报告 CE 插件合规性检查 Runs `validate_plugin_meta(plugin.plugin_meta)` to check plugin metadata Audits `plugin_meta` fields such as `schema_version`, `name`, and `version` Checks for correct types, including `int` and non-empty `str` Produces a structured report based on audit dimensions Enforces conformance with the CE plugin contract (ADR-006) ce-plugin-audit is a repository for explaining the Calibrated Explanations method, providing a plugin contract audit process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Arman-Kudaibergenov/1c-ai-development-kit/form-compile', 'community', 'Arman-Kudaibergenov', '1c-ai-development-kit', 'Arman-Kudaibergenov/1c-ai-development-kit', 'form-compile', 64, 6, 50, '2026-02-24T12:56:13Z', '2026-03-06T06:34:36.643Z', '5e41ced809fd980eceb021735f5ff21f5127e69a7252217b752fb3897f0ff4cc', '{"id":"Arman-Kudaibergenov/1c-ai-development-kit/form-compile","name":"form-compile","description":{"en":"The form-compile skill is a comprehensive toolkit for 1C:Enterprise development, generating complete Form.xml files from compact JSON definitions. It benefits developers working with Cursor IDE and AI agents.","zh":"form-compile是一种Comprehensive AI agents和规则工具包，用于1C：Enterprise开发和Cursor IDE","ja":"form-compileは、1C：Enterprise開発とCursor IDE向けの包括的なAIエージェントとルールツールキットです","ko":"form-compile은 1C Enterprise 개발과 Cursor IDE를 위한 포괄적인 AI 에이전트 및 규칙 툴킷입니다","es":"form-compile es una herramienta de automatización para 1C:Enterprise que genera Form.xml a partir de definiciones JSON en Cursor IDE, simplificando el proceso de desarrollo.","fr":"form-compile est un outil d''automatisation pour 1C:Enterprise qui génère des Form.xml à partir de définitions JSON dans Cursor IDE, simplifiant le processus de développement.","de":"form-compile ist ein Automatisierungstool für 1C:Enterprise, das Form.xml aus JSON-Definitionen in Cursor IDE generiert und den Entwicklungsprozess vereinfacht.","pt":"O Form-Compile é uma ferramenta de geração de código para 1C:Enterprise que converte JSON DSL em Form.xml","ru":"Form-Compile — это инструмент генерации кода для 1C:Enterprise, который преобразует JSON DSL в Form.xml с помощью ИИ Агентов","ar":"Form-Compile هو أداة генераة كود ل 1C:Enterprise التي تحول JSON DSL إلى Form.xml مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"form-compile: Automated Form.xml Generation for AI Agents...","zh":"form-compile_SETUP GUIDE：1C：Enterprise开发自动化","ja":"form-compileベストプラクティス：AIエージェントによるCursor IDE開発","ko":"form-compile설정 가이드: 1C Enterprise 개발 자동화","es":"Guía de configuración de form-compile para desarrolladore...","fr":"Guide de démarrage rapide pour form-compile dans le dével...","de":"Einrichtungsleitfaden für form-compile in 1C:Enterprise-E...","pt":"Form-Compile: Guia de Configuração para Desenvolvedores 1...","ru":"Form-Compile: Руководство по настройке для разработчиков ...","ar":"Form-Compile: دليل الإعداد للمانحين 1C:Enterprise مع أدوا..."},"description":{"en":"Discover how form-compile streamlines 1C:Enterprise development in Cursor IDE. Learn to generate Form.xml from JSON DSL and boost your development workflow t...","zh":"使用form-compile AI工具，快速生成Form.xml并自动化1C：Enterprise开发流程","ja":"AIエージェントを活用したCursor IDE開発：form-compileでForm.xmlを生成","ko":"form-compile을 사용하여 Form.xml을 자동 생성하고 1C Enterprise 개발을 자동화합니다","es":"Aprende a generar Form.xml desde definiciones JSON con form-compile, la herramienta de automatización para 1C:Enterprise en Cursor IDE","fr":"Découvrez comment générer des Form.xml à partir de définitions JSON avec form-compile, l''outil d''automatisation pour 1C:Enterprise dans Cursor IDE","de":"Erfahren Sie, wie Sie mit form-compile Form.xml aus JSON-Definitionen generieren, das Automatisierungstool für 1C:Enterprise in Cursor IDE","pt":"Aprenda a usar o Form-Compile para gerar Form.xml a partir de JSON DSL e melhore sua produtividade em 1C:Enterprise","ru":"Узнайте, как использовать Form-Compile для генерации Form.xml из JSON DSL и повысьте свою производительность в 1C:Enterprise с ИИ Агентами","ar":"تعرف على كيفية استخدام Form-Compile لإنشاء Form.xml من JSON DSL و تحسين إنتاجيتك في 1C:Enterprise مع أدوات الذكاء الاصطناعي"},"definition":{"en":"form-compile is a toolkit for generating Form.xml files from JSON DSL definitions, used in 1C:Enterprise development with Cursor IDE.","zh":"form-compile是一种AI工具，用于生成Form.xml并自动化1C：Enterprise开发流程","ja":"form-compileは、Form.xmlを生成し、1C：Enterprise開発プロセスを自動化するAIエージェントです","ko":"form-compile은 Form.xml을 생성하여 1C Enterprise 개발 프로세스를 자동화하는 AI 에이전트입니다","es":"form-compile es un agente de inteligencia artificial para generar Form.xml desde definiciones JSON en 1C:Enterprise","fr":"form-compile est un agent d''intelligence artificielle pour générer des Form.xml à partir de définitions JSON dans 1C:Enterprise","de":"form-compile ist ein künstlicher Intelligenz-Agent, der Form.xml aus JSON-Definitionen in 1C:Enterprise generiert","pt":"Form-Compile é uma ferramenta de automação de código que gera Form.xml a partir de JSON DSL","ru":"Form-Compile — это инструмент автоматизации кода, который генерирует Form.xml из JSON DSL с ИИ Агентами","ar":"Form-Compile هو أداة أتمتة كود التي تولد Form.xml من JSON DSL مع أدوات الذكاء الاصطناعي"},"features":{"en":["Generates complete Form.xml files from compact JSON definitions","Supports namespace declarations and autogenerates companion elements","Creates sequential IDs for form elements","Integrates with Cursor IDE for streamlined 1C:Enterprise development","Accepts JSON DSL definitions with 20-50 lines of code","Produces Form.xml files with 100-500+ lines of code"],"zh":["支持JSON DSL定义","自动生成Form.xml","支持namespace声明和伴侣元素","支持自动ID生成"],"ja":["JSON DSL定義をサポート","Form.xmlを自動生成","namespace宣言と伴侶要素をサポート","自動ID生成をサポート"],"ko":["JSON DSL 정의 지원","Form.xml 자동 생성","namespace 선언 및 동반 요소 지원","자동 ID 생성 지원"],"es":["Generación de Form.xml a partir de definiciones JSON","Compatibilidad con Cursor IDE","Automatización de la generación de namespace-declaraciones","Creación de companion-elementos autogenerados","Asignación de ID secuenciales"],"fr":["Génération de Form.xml à partir de définitions JSON","Compatibilité avec Cursor IDE","Automatisation de la génération de déclarations de namespace","Création d''éléments companion autogénérés","Attribution d''ID séquentiels"],"de":["Generierung von Form.xml aus JSON-Definitionen","Kompatibilität mit Cursor IDE","Automatisierung der Generierung von Namespace-Deklarationen","Erstellung von autogenerierten Companion-Elementen","Zuweisung von sequenziellen ID"],"pt":["Geração de Form.xml a partir de JSON DSL","Suporte a namespace-declarações e companion-elementos","Geração de IDs sequenciais","Integração com o Cursor IDE","Suporte a arquiteturas de forma complexas","Melhoria da produtividade em 1C:Enterprise"],"ru":["Генерация Form.xml из JSON DSL","Поддержка namespace-деклараций и companion-элементов","Генерация последовательных ID","Интеграция с Cursor IDE","Поддержка сложных архитектур форм","Повышение производительности в 1C:Enterprise с ИИ Агентами"],"ar":["إنشاء Form.xml من JSON DSL","دعم namespace-إعلانات و companion-عناصر","إنشاء IDs متسلسلة","التكامل مع Cursor IDE","دعم هياكل Forms المعقدة","تحسين الإنتاجية في 1C:Enterprise مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use form-compile","form-compile setup guide","1C:Enterprise development tools","Cursor IDE integration","JSON DSL to Form.xml generation","form-compile alternative","automated form generation","1C:Enterprise AI agents","form-compile install"],"zh":["1C：Enterprise开发","AI工具","Cursor IDE","Form.xml生成","自动化开发","JSON DSL","namespace声明","伴侣元素"],"ja":["1C：Enterprise開発","AIエージェント","Cursor IDE","Form.xml生成","自動化開発","JSON DSL","namespace宣言","伴侶要素"],"ko":["1C Enterprise 개발","AI 에이전트","Cursor IDE","Form.xml 생성","자동화 개발","JSON DSL","namespace 선언","동반 요소"],"es":["form-compile","1C:Enterprise","Cursor IDE","generación de Form.xml","definiciones JSON","automatización de desarrollo","herramientas de desarrollo","agentes de inteligencia artificial","desarrollo de software"],"fr":["form-compile","1C:Enterprise","Cursor IDE","génération de Form.xml","définitions JSON","automatisation du développement","outils de développement","agents d''intelligence artificielle","développement de logiciels"],"de":["form-compile","1C:Enterprise","Cursor IDE","Generierung von Form.xml","JSON-Definitionen","Automatisierung der Entwicklung","Entwicklungstools","künstliche Intelligenz-Agenten","Software-Entwicklung"],"pt":["Form-Compile","1C:Enterprise","JSON DSL","Form.xml","Cursor IDE","automação de código","geração de código","desenvolvimento de software","produtividade em 1C:Enterprise"],"ru":["Form-Compile","1C:Enterprise","JSON DSL","Form.xml","Cursor IDE","автоматизация кода","генерация кода","разработка программного обеспечения","производительность в 1C:Enterprise","ИИ Агенты"],"ar":["Form-Compile","1C:Enterprise","JSON DSL","Form.xml","Cursor IDE","أتمتة كود","توليد كود","تطوير برمجيات","إنتاجية في 1C:Enterprise","أدوات الذكاء الاصطناعي"]}},"owner":"Arman-Kudaibergenov","repo":"1c-ai-development-kit","repoPath":"Arman-Kudaibergenov/1c-ai-development-kit","stars":64,"forks":6,"updatedAt":"2026-02-24T12:56:13Z","topics":["1c-enterprise","ai-agents","automation","bsl","code-generation","cursor-ide","development-tools","mcp-servers"],"category":"community","skillMd":{"name":"form-compile","description":"Компиляция управляемой формы 1С из компактного JSON-определения. Используй когда нужно создать форму с нуля по описанию элементов","bodyPreview":"# /form-compile — Генерация Form.xml из JSON DSL\n\nПринимает компактное JSON-определение формы (20–50 строк) и генерирует полный корректный Form.xml (100–500+ строк) с namespace-декларациями, автогенерированными companion-элементами, последовательными ID.\n\n> **При проектировании формы с нуля (5+ элементов или нечёткие требования)** — вызовите `/form-patterns` для загрузки справочника: архетипы, конвенции именования, продвинутые паттерны. Для простых форм (1–3 поля, пользователь описал что нужно)","body":"# /form-compile — Генерация Form.xml из JSON DSL\n\nПринимает компактное JSON-определение формы (20–50 строк) и генерирует полный корректный Form.xml (100–500+ строк) с namespace-декларациями, автогенерированными companion-элементами, последовательными ID.\n\n> **При проектировании формы с нуля (5+ элементов или нечёткие требования)** — вызовите `/form-patterns` для загрузки справочника: архетипы, конвенции именования, продвинутые паттерны. Для простых форм (1–3 поля, пользователь описал что нужно) — не нужно.\n\n## Использование\n\n```\n/form-compile <JsonPath> <OutputPath>\n```\n\n## Параметры\n\n| Параметр   | Обязательный | Описание                          |\n|------------|:------------:|-----------------------------------|\n| JsonPath   | да           | Путь к JSON-определению формы     |\n| OutputPath | да           | Путь к выходному файлу Form.xml   |\n\n## Команда\n\n```powershell\npowershell.exe -NoProfile -File .claude/skills/form-compile/scripts/form-compile.ps1 -JsonPath \"<json>\" -OutputPath \"<xml>\"\n```\n\n## JSON DSL — справка\n\n### Структура верхнего уровня\n\n```json\n{\n  \"title\": \"Заголовок формы\",\n  \"properties\": { \"autoTitle\": false, ... },\n  \"events\": { \"OnCreateAtServer\": \"ПриСозданииНаСервере\" },\n  \"excludedCommands\": [\"Reread\"],\n  \"elements\": [ ... ],\n  \"attributes\": [ ... ],\n  \"commands\": [ ... ],\n  \"parameters\": [ ... ]\n}\n```\n\n- `title` — заголовок формы (multilingual). Можно указать и в `properties`, но лучше на верхнем уровне\n- `properties` — свойства формы: `autoTitle`, `windowOpeningMode`, `commandBarLocation`, `saveDataInSettings`, `width`, `height` и др.\n- `events` — обработчики событий формы (ключ: имя события 1С, значение: имя процедуры)\n- `excludedCommands` — исключённые стандартные команды\n\n### Элементы (ключ определяет тип)\n\n| DSL ключ     | XML элемент       | Значение ключа                                    |\n|--------------|-------------------|---------------------------------------------------|\n| `\"group\"`    | UsualGroup        | `\"horizontal\"` / `\"vertical\"` / `\"alwaysHorizontal\"` / `\"alwaysVertical\"` / `\"collapsible\"` |\n| `\"input\"`    | InputField        | имя элемента                                      |\n| `\"check\"`    | CheckBoxField     | имя                                               |\n| `\"label\"`    | LabelDecoration   | имя (текст задаётся через `title`)                |\n| `\"labelField\"` | LabelField      | имя                                               |\n| `\"table\"`    | Table             | имя                                               |\n| `\"pages\"`    | Pages             | имя                                               |\n| `\"page\"`     | Page              | имя                                               |\n| `\"button\"`   | Button            | имя                                               |\n| `\"picture\"`  | PictureDecoration | имя                                               |\n| `\"picField\"` | PictureField      | имя                                               |\n| `\"calendar\"` | CalendarField     | имя                                               |\n| `\"cmdBar\"`   | CommandBar        | имя                                               |\n| `\"popup\"`    | Popup             | имя                                               |\n\n### Общие свойства (все типы элементов)\n\n| Ключ | Описание |\n|------|----------|\n| `name` | Переопределить имя (по умолчанию = значение ключа типа) |\n| `title` | Заголовок элемента |\n| `visible: false` | Скрыть (синоним: `hidden: true`) |\n| `enabled: false` | Сделать недоступным (синоним: `disabled: true`) |\n| `readOnly: true` | Только чтение |\n| `on: [...]` | События с автоименованием обработчиков |\n| `handlers: {...}` | Явное задание имён обработчиков: `{\"OnChange\": \"МоёИмя\"}` |\n\n### Допустимые имена событий (`on`)\n\nКомпилятор предупреждает о неизвестных событиях. Имена регистрозависимы — используйте точно как указано.\n\n**Форма** (`events`): `OnCreateAtServer`, `OnOpen`, `BeforeClose`, `OnClose`, `NotificationProcessing`, `ChoiceProcessing`, `OnReadAtServer`, `BeforeWriteAtServer`, `OnWriteAtServer`, `AfterWriteAtServer`, `BeforeWrite`, `AfterWrite`, `FillCheckProcessingAtServer`, `BeforeLoadDataFromSettingsAtServer`, `OnLoadDataFromSettingsAtServer`, `ExternalEvent`, `Opening`\n\n**input / picField**: `OnChange`, `StartChoice`, `ChoiceProcessing`, `AutoComplete`, `TextEditEnd`, `Clearing`, `Creating`, `EditTextChange`\n\n**check**: `OnChange`\n\n**table**: `OnStartEdit`, `OnEditEnd`, `OnChange`, `Selection`, `ValueChoice`, `BeforeAddRow`, `BeforeDeleteRow`, `AfterDeleteRow`, `BeforeRowChange`, `BeforeEditEnd`, `OnActivateRow`, `OnActivateCell`, `Drag`, `DragStart`, `DragCheck`, `DragEnd`\n\n**label / picture**: `Click`, `URLProcessing`\n\n**labelField**: `OnChange`, `StartChoice`, `ChoiceProcessing`, `Click`, `URLProcessing`, `Clearing`\n\n**button**: `Click`\n\n**pages**: `OnCurrentPageChange`\n\n### Поле ввода (input)\n\n| Ключ | Описание | Пример |\n|------|----------|--------|\n| `path` | DataPath — привязка к данным | `\"Объект.Организация\"` |\n| `titleLocation` | Размещение заголовка | `\"none\"`, `\"left\"`, `\"top\"` |\n| `multiLine: true` | Многострочное поле | текстовое поле, комментарий |\n| `passwordMode: true` | Режим пароля (звёздочки) | поле ввода пароля |\n| `choiceButton: true` | Кнопка выбора (\"...\") | ссылочное поле |\n| `clearButton: true` | Кнопка очистки (\"X\") | |\n| `spinButton: true` | Кнопка прокрутки | числовые поля |\n| `dropListButton: true` | Кнопка выпадающего списка | |\n| `markIncomplete: true` | Пометка незаполненного | обязательные поля |\n| `skipOnInput: true` | Пропускать при обходе Tab | |\n| `inputHint` | Подсказка в пустом поле | `\"Введите наименование...\"` |\n| `width` / `height` | Размер | числа |\n| `autoMaxWidth: false` | Отключить авто-ширину | для фиксированных полей |\n| `horizontalStretch: true` | Растягивать по ширине | |\n\n### Чекбокс (check)\n\n| Ключ | Описание |\n|------|----------|\n| `path` | DataPath |\n| `titleLocation` | Размещение заголовка |\n\n### Надпись-декорация (label)\n\n| Ключ | Описание |\n|------|----------|\n| `title` | Текст надписи (обязательно) |\n| `hyperlink: true` | Сделать ссылкой |\n| `width` / `height` | Размер |\n\n### Группа (group)\n\nЗначение ключа задаёт ориентацию: `\"horizontal\"`, `\"vertical\"`, `\"alwaysHorizontal\"`, `\"alwaysVertical\"`, `\"collapsible\"`.\n\n| Ключ | Описание |\n|------|----------|\n| `showTitle: true` | Показывать заголовок группы |\n| `united: false` | Не объединять рамку |\n| `representation` | `\"none\"`, `\"normal\"`, `\"weak\"`, `\"strong\"` |\n| `children: [...]` | Вложенные элементы |\n\n### Таблица (table)\n\n**Важно**: таблица требует связанный реквизит формы типа `ValueTable` с колонками (см. раздел \"Связки\").\n\n| Ключ | Описание |\n|------|----------|\n| `path` | DataPath (привязка к реквизиту-таблице) |\n| `columns: [...]` | Колонки — массив элементов (обычно `input`) |\n| `changeRowSet: true` | Разрешить добавление/удаление строк |\n| `changeRowOrder: true` | Разрешить перемещение строк |\n| `height` | Высота в строках таблицы |\n| `header: false` | Скрыть шапку |\n| `footer: true` | Показать подвал |\n| `commandBarLocation` | `\"None\"`, `\"Top\"`, `\"Auto\"` |\n| `searchStringLocation` | `\"None\"`, `\"Top\"`, `\"Auto\"` |\n\n### Страницы (pages + page)\n\n| Ключ (pages) | Описание |\n|------|----------|\n| `pagesRepresentation` | `\"None\"`, `\"TabsOnTop\"`, `\"TabsOnBottom\"` и др. |\n| `children: [...]` | Массив `page` |\n\n| Ключ (page) | Описание |\n|------|----------|\n| `title` | Заголовок вкладки |\n| `group` | Ориентация внутри страницы |\n| `children: [...]` | Содержимое страницы |\n\n### Кнопка (button)\n\n| Ключ | Описание |\n|------|----------|\n| `command` | Имя команды формы → `Form.Command.Имя` |\n| `stdCommand` | Стандартная команда: `\"Close\"` → `Form.StandardCommand.Close`; с точкой: `\"Товары.Add\"` → `Form.Item.Товары.StandardCommand.Add` |\n| `defaultButton: true` | Кнопка по умолчанию |\n| `type` | `\"usual\"`, `\"hyperlink\"`, `\"commandBar\"` |\n| `picture` | Картинка кнопки |\n| `representation` | `\"Auto\"`, `\"Text\"`, `\"Picture\"`, `\"PictureAndText\"` |\n| `locationInCommandBar` | `\"Auto\"`, `\"InCommandBar\"`, `\"InAdditionalSubmenu\"` |\n\n### Командная панель (cmdBar)\n\n| Ключ | Описание |\n|------|----------|\n| `autofill: true` | Автозаполнение стандартными командами |\n| `children: [...]` | Кнопки панели |\n\n### Выпадающее меню (popup)\n\n| Ключ | Описание |\n|------|----------|\n| `title` | Заголовок подменю |\n| `children: [...]` | Кнопки подменю |\n\nИспользуется внутри `cmdBar` для группировки кнопок в подменю:\n```json\n{ \"cmdBar\": \"Панель\", \"children\": [\n  { \"popup\": \"Добавить\", \"title\": \"Добавить\", \"children\": [\n    { \"button\": \"ДобавитьСтроку\", \"stdCommand\": \"Товары.Add\" },\n    { \"button\": \"ДобавитьИзДокумента\", \"command\": \"ДобавитьИзДокумента\", \"title\": \"Из документа\" }\n  ]}\n]}\n```\n\n### Реквизиты (attributes)\n\n```json\n{ \"name\": \"Объект\", \"type\": \"DataProcessorObject.Загрузка\", \"main\": true }\n{ \"name\": \"Итого\", \"type\": \"decimal(15,2)\" }\n{ \"name\": \"Таблица\", \"type\": \"ValueTable\", \"columns\": [\n    { \"name\": \"Номенклатура\", \"type\": \"CatalogRef.Номенклатура\" },\n    { \"name\": \"Количество\", \"type\": \"decimal(10,3)\" }\n]}\n```\n\n- `savedData: true` — сохраняемые данные\n\n### Команды (commands)\n\n```json\n{ \"name\": \"Загрузить\", \"action\": \"ЗагрузитьОбработка\", \"shortcut\": \"Ctrl+Enter\" }\n```\n\n- `title` — заголовок (если отличается от name)\n- `picture` — картинка команды\n\n### Система типов\n\n| DSL                    | XML                                    |\n|------------------------|----------------------------------------|\n| `\"string\"` / `\"string(100)\"` | `xs:string` + StringQualifiers  |\n| `\"decimal(15,2)\"`     | `xs:decimal` + NumberQualifiers        |\n| `\"decimal(10,0,nonneg)\"` | с AllowedSign=Nonnegative           |\n| `\"boolean\"`            | `xs:boolean`                          |\n| `\"date\"` / `\"dateTime\"` / `\"time\"` | `xs:dateTime` + DateFractions |\n| `\"CatalogRef.XXX\"`    | `cfg:CatalogRef.XXX`                   |\n| `\"DocumentRef.XXX\"`   | `cfg:DocumentRef.XXX`                  |\n| `\"ValueTable\"`         | `v8:ValueTable`                       |\n| `\"ValueList\"`          | `v8:ValueListType`                    |\n| `\"Type1 \\| Type2\"`    | составной тип                          |\n\n## Связки: элемент + реквизит\n\nТаблица и некоторые поля требуют связанный реквизит. Элемент ссылается на реквизит через `path`.\n\n**Таблица** — элемент `table` + реквизит `ValueTable`:\n```json\n{\n  \"elements\": [\n    { \"table\": \"Товары\", \"path\": \"Объект.Товары\", \"columns\": [\n      { \"input\": \"Номенклатура\", \"path\": \"Объект.Товары.Номенклатура\" }\n    ]}\n  ],\n  \"attributes\": [\n    { \"name\": \"Объект\", \"type\": \"DataProcessorObject.Загрузка\", \"main\": true,\n      \"columns\": [\n        { \"name\": \"Товары\", \"type\": \"ValueTable\", \"columns\": [\n          { \"name\": \"Номенклатура\", \"type\": \"CatalogRef.Номенклатура\" }\n        ]}\n      ]\n    }\n  ]\n}\n```\n\nИли, если таблица привязана к реквизиту формы (не к Объект):\n```json\n{\n  \"elements\": [\n    { \"table\": \"ТаблицаДанных\", \"path\": \"ТаблицаДанных\", \"columns\": [\n      { \"input\": \"Наименование\", \"path\": \"ТаблицаДанных.Наименование\" }\n    ]}\n  ],\n  \"attributes\": [\n    { \"name\": \"ТаблицаДанных\", \"type\": \"ValueTable\", \"columns\": [\n      { \"name\": \"Наименование\", \"type\": \"string(150)\" }\n    ]}\n  ]\n}\n```\n\n## Паттерны\n\n### Диалог загрузки файла\n\n```json\n{\n  \"title\": \"Загрузка из файла\",\n  \"properties\": { \"autoTitle\": false },\n  \"events\": { \"OnCreateAtServer\": \"ПриСозданииНаСервере\" },\n  \"elements\": [\n    { \"group\": \"horizontal\", \"name\": \"ГруппаФайл\", \"children\": [\n      { \"input\": \"ИмяФайла\", \"path\": \"ИмяФайла\", \"title\": \"Файл\", \"inputHint\": \"Выберите файл...\", \"choiceButton\": true, \"on\": [\"StartChoice\"] },\n      { \"check\": \"ПерваяСтрокаЗаголовок\", \"path\": \"ПерваяСтрокаЗаголовок\" }\n    ]},\n    { \"input\": \"Результат\", \"path\": \"Результат\", \"multiLine\": true, \"height\": 8, \"readOnly\": true, \"title\": \"Лог\" },\n    { \"group\": \"horizontal\", \"name\": \"ГруппаКнопок\", \"children\": [\n      { \"button\": \"Загрузить\", \"command\": \"Загрузить\", \"defaultButton\": true },\n      { \"button\": \"Закрыть\", \"stdCommand\": \"Close\" }\n    ]}\n  ],\n  \"attributes\": [\n    { \"name\": \"Объект\", \"type\": \"ExternalDataProcessorObject.ЗагрузкаИзФайла\", \"main\": true },\n    { \"name\": \"ИмяФайла\", \"type\": \"string\" },\n    { \"name\": \"ПерваяСтрокаЗаголовок\", \"type\": \"boolean\" },\n    { \"name\": \"Результат\", \"type\": \"string\" }\n  ],\n  \"commands\": [\n    { \"name\": \"Загрузить\", \"action\": \"ЗагрузитьОбработка\", \"shortcut\": \"Ctrl+Enter\" }\n  ]\n}\n```\n\n### Мастер (wizard) с шагами\n\n```json\n{\n  \"title\": \"Мастер настройки\",\n  \"properties\": { \"autoTitle\": false },\n  \"elements\": [\n    { \"pages\": \"СтраницыМастера\", \"pagesRepresentation\": \"None\", \"children\": [\n      { \"page\": \"Шаг1\", \"title\": \"Параметры\", \"children\": [\n        { \"input\": \"Параметр1\", \"path\": \"Параметр1\" }\n      ]},\n      { \"page\": \"Шаг2\", \"title\": \"Результат\", \"children\": [\n        { \"input\": \"Итог\", \"path\": \"Итог\", \"readOnly\": true }\n      ]}\n    ]},\n    { \"group\": \"horizontal\", \"name\": \"Навигация\", \"children\": [\n      { \"button\": \"Назад\", \"command\": \"Назад\", \"title\": \"< Назад\" },\n      { \"button\": \"Далее\", \"command\": \"Далее\", \"title\": \"Далее >\" }\n    ]}\n  ],\n  \"attributes\": [\n    { \"name\": \"Объект\", \"type\": \"ExternalDataProcessorObject.Мастер\", \"main\": true },\n    { \"name\": \"Параметр1\", \"type\": \"string\" },\n    { \"name\": \"Итог\", \"type\": \"string\" }\n  ],\n  \"commands\": [\n    { \"name\": \"Назад\", \"action\": \"НазадОбработка\" },\n    { \"name\": \"Далее\", \"action\": \"ДалееОбработка\" }\n  ]\n}\n```\n\n### Список с фильтром и таблицей\n\n```json\n{\n  \"title\": \"Просмотр данных\",\n  \"elements\": [\n    { \"group\": \"horizontal\", \"name\": \"Фильтр\", \"children\": [\n      { \"input\": \"Период\", \"path\": \"Период\", \"on\": [\"OnChange\"] },\n      { \"input\": \"Организация\", \"path\": \"Организация\", \"on\": [\"OnChange\"] }\n    ]},\n    { \"table\": \"Данные\", \"path\": \"Данные\", \"changeRowSet\": true, \"columns\": [\n      { \"input\": \"Дата\", \"path\": \"Данные.Дата\" },\n      { \"input\": \"Сумма\", \"path\": \"Данные.Сумма\" },\n      { \"input\": \"Комментарий\", \"path\": \"Данные.Комментарий\" }\n    ]}\n  ],\n  \"attributes\": [\n    { \"name\": \"Объект\", \"type\": \"ExternalDataProcessorObject.Просмотр\", \"main\": true },\n    { \"name\": \"Период\", \"type\": \"date\" },\n    { \"name\": \"Организация\", \"type\": \"string\" },\n    { \"name\": \"Данные\", \"type\": \"ValueTable\", \"columns\": [\n      { \"name\": \"Дата\", \"type\": \"date\" },\n      { \"name\": \"Сумма\", \"type\": \"decimal(15,2)\" },\n      { \"name\": \"Комментарий\", \"type\": \"string(200)\" }\n    ]}\n  ]\n}\n```\n\n## Автогенерация\n\n- **Companion-элементы**: ContextMenu, ExtendedTooltip и др. создаются автоматически\n- **Обработчики событий**: `\"on\": [\"OnChange\"]` → `ОрганизацияПриИзменении`\n- **Namespace**: все 17 namespace-деклараций\n- **ID**: последовательная нумерация, AutoCommandBar = id=\"-1\"\n- **Unknown keys**: выводится предупреждение о нераспознанных ключах\n\n## Верификация\n\n```\n/form-validate <OutputPath>    — проверка корректности XML\n/form-info <OutputPath>        — визуальная сводка структуры\n```\n\n## Особенности для внешних обработок (EPF)\n\n- **Тип главного реквизита**: `ExternalDataProcessorObject.ИмяОбработки` (не `DataProcessorObject`)\n- **DataPath**: используйте реквизиты формы (`ИмяРеквизита`), а не `Объект.ИмяРеквизита` — у внешних обработок нет реквизитов объекта в метаданных\n- **Ссылочные типы**: `CatalogRef.XXX`, `DocumentRef.XXX` допустимы в XML, но для сборки EPF потребуется база с целевой конфигурацией (см. `/epf-build`)\n"},"lastSynced":"2026-03-06T06:34:36.643Z","agentAnalysis":{"suitability":{"en":"Ideal for 1C:Enterprise development agents requiring automated Form.xml generation from compact JSON definitions.","zh":"适用于需要从紧凑JSON定义自动生成Form.xml的1C:Enterprise开发代理。","ja":"1C:Enterprise開発エージェントがコンパクトなJSON定義からForm.xmlを自動生成する必要がある場合に最適です。","ko":"コンパクトなJSON定義からForm.xml를 자동 생성해야 하는 1C:Enterprise 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de 1C:Enterprise que requieren la generación automática de Form.xml a partir de definiciones JSON compactas.","fr":"Idéal pour les agents de développement 1C:Enterprise nécessitant la génération automatique de Form.xml à partir de définitions JSON compactes.","de":"Ideal für 1C:Enterprise-Entwicklungsagenten, die die automatisierte Form.xml-Generierung aus kompakten JSON-Definitionen erfordern.","pt":"Ideal para agentes de desenvolvimento 1C:Enterprise que requerem geração automática de Form.xml a partir de definições JSON compactas.","ru":"Идеально подходит для агентов разработки 1C:Enterprise, требующих автоматической генерации Form.xml из компактных определений JSON.","ar":"مثالي لعميل تطوير 1C:Enterprise الذي يتطلب توليد Form.xml آليًا من تعريفات JSON المضغوطة."},"recommendation":{"en":"Empowers agents to generate complete Form.xml files with namespace declarations, auto-generated companion elements, and sequential IDs, leveraging JSON DSL for efficient form development, and integrates seamlessly with Cursor IDE and other AI agents for streamlined 1C:Enterprise projects.","zh":"赋予代理生成完整的Form.xml文件的能力，包括命名空间声明、自动生成的伴侣元素和顺序ID，利用JSON DSL进行高效的表单开发，并与Cursor IDE和其他AI代理无缝集成，以实现1C:Enterprise项目的流程化。","ja":"エージェントに、名前空間宣言、自動生成されたコンパニオンモデル、およびシーケンシャルIDを含む完全なForm.xmlファイルを生成する機能を提供します。JSON DSLを利用して効率的なフォーム開発を行い、Cursor IDEや他のAIエージェントと無縁に統合して、1C:Enterpriseプロジェクトの統合を実現します。","ko":"에이전트가 완전한 Form.xml 파일을 생성할 수 있는 기능을 제공합니다. 이름공간 선언, 자동 생성된 동료 요소 및 시퀀셜 ID를 포함하여 JSON DSL을 사용한 효율적인 양식 개발을 지원하며, Cursor IDE 및 기타 AI 에이전트와无缝 통합하여 1C:Enterprise 프로젝트의 통합을 실현합니다.","es":"Habilita a los agentes a generar archivos Form.xml completos con declaraciones de espacios de nombres, elementos acompañantes autogenerados y IDs secuenciales, aprovechando JSON DSL para un desarrollo de formularios eficiente, e integra de forma transparente con Cursor IDE y otros agentes de inteligencia artificial para proyectos 1C:Enterprise optimizados.","fr":"Permet aux agents de générer des fichiers Form.xml complets avec des déclarations d''espaces de noms, des éléments accompagnants autogénérés et des ID séquentiels, en exploitant JSON DSL pour un développement de formulaires efficace, et s''intègre sans heurts avec Cursor IDE et d''autres agents d''intelligence artificielle pour des projets 1C:Enterprise rationalisés.","de":"Ermächtigt Agenten, vollständige Form.xml-Dateien mit Namensraumdeklarationen, automatisch generierten Begleitelementen und sequenziellen IDs zu generieren, indem JSON DSL für eine effiziente Formularentwicklung genutzt wird, und integriert sich nahtlos mit Cursor IDE und anderen KI-Agents für optimierte 1C:Enterprise-Projekte.","pt":"Habilita os agentes a gerar arquivos Form.xml completos com declarações de namespace, elementos acompanhantes auto-gerados e IDs sequenciais, aproveitando o JSON DSL para desenvolvimento de formulários eficiente, e se integra perfeitamente com o Cursor IDE e outros agentes de IA para projetos 1C:Enterprise simplificados.","ru":"Наделяет агентов возможностью генерировать полные файлы Form.xml с объявлениями пространства имен, автоматически сгенерированными сопутствующими элементами и последовательными идентификаторами, используя JSON DSL для эффективного разработки форм, и интегрируется без проблем с Cursor IDE и другими агентами ИИ для упрощения проектов 1C:Enterprise.","ar":"يمنح الوكيل القدرة على توليد ملفات Form.xml كاملة مع إعلانات مساحة الاسم والعناصر المرافقة المولدة تلقائيًا والمعرفات التسلسلية، مستفيدًا من JSON DSL من أجل تطوير نموذج فعال، ويتكامل بسلاسة مع Cursor IDE ووكلاء ذكاء اصطناعي آخرون من أجل مشاريع 1C:Enterprise مبسطة."},"useCases":{"en":["Generating complete Form.xml files from compact JSON definitions","Automating form development for 1C:Enterprise projects with JSON DSL","Creating polished forms with auto-generated companion elements and namespace declarations"],"zh":["从紧凑的JSON定义生成完整的Form.xml文件","使用JSON DSL自动化1C:Enterprise项目的表单开发","创建带有自动生成的伴侣元素和命名空间声明的精致表单"],"ja":["コンパクトなJSON定義から完全なForm.xmlファイルを生成する","JSON DSLを使用して1C:Enterpriseプロジェクトのフォーム開発を自動化する","自動生成されたコンパニオンモデルと名前空間宣言を含む洗練されたフォームを作成する"],"ko":["コンパクト한 JSON 정의에서 완전한 Form.xml 파일을 생성하는こと","JSON DSL을 사용하여 1C:Enterprise 프로젝트의 양식 개발을 자동화하는こと","자동 생성된 동료 요소 및 이름공간 선언을 포함하여 정련된 양식을 생성하는こと"],"es":["Generar archivos Form.xml completos a partir de definiciones JSON compactas","Automatizar el desarrollo de formularios para proyectos 1C:Enterprise con JSON DSL","Crear formularios pulidos con elementos acompañantes autogenerados y declaraciones de espacios de nombres"],"fr":["Générer des fichiers Form.xml complets à partir de définitions JSON compactes","Automatiser le développement de formulaires pour les projets 1C:Enterprise avec JSON DSL","Créer des formulaires polis avec des éléments accompagnants autogénérés et des déclarations d''espaces de noms"],"de":["Erzeugen von vollständigen Form.xml-Dateien aus kompakten JSON-Definitionen","Automatisieren der Formularentwicklung für 1C:Enterprise-Projekte mit JSON DSL","Erstellen von verfeinerten Formularen mit automatisch generierten Begleitelementen und Namensraumdeklarationen"],"pt":["Gerar arquivos Form.xml completos a partir de definições JSON compactas","Automatizar o desenvolvimento de formulários para projetos 1C:Enterprise com JSON DSL","Criar formulários polidos com elementos acompanhantes auto-gerados e declarações de namespace"],"ru":["Генерировать полные файлы Form.xml из компактных определений JSON","Авт