INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Arman-Kudaibergenov/1c-ai-development-kit/form-compile', 'form-compile', 'Arman-Kudaibergenov', '1c-ai-development-kit', 'community', 'form-compile Arman-Kudaibergenov 1c-ai-development-kit community 1c-enterprise ai-agents automation bsl code-generation cursor-ide development-tools mcp-servers The form-compile skill is a comprehensive toolkit for 1C:Enterprise development, generating complete Form.xml files from compact JSON definitions. It benefits developers working with Cursor IDE and AI agents. form-compile是一种Comprehensive AI agents和规则工具包，用于1C：Enterprise开发和Cursor IDE form-compileは、1C：Enterprise開発とCursor IDE向けの包括的なAIエージェントとルールツールキットです form-compile은 1C Enterprise 개발과 Cursor IDE를 위한 포괄적인 AI 에이전트 및 규칙 툴킷입니다 form-compile es una herramienta de automatización para 1C:Enterprise que genera Form.xml a partir de definiciones JSON en Cursor IDE, simplificando el proceso de desarrollo. form-compile est un outil d''automatisation pour 1C:Enterprise qui génère des Form.xml à partir de définitions JSON dans Cursor IDE, simplifiant le processus de développement. form-compile ist ein Automatisierungstool für 1C:Enterprise, das Form.xml aus JSON-Definitionen in Cursor IDE generiert und den Entwicklungsprozess vereinfacht. O Form-Compile é uma ferramenta de geração de código para 1C:Enterprise que converte JSON DSL em Form.xml Form-Compile — это инструмент генерации кода для 1C:Enterprise, который преобразует JSON DSL в Form.xml с помощью ИИ Агентов Form-Compile هو أداة генераة كود ل 1C:Enterprise التي تحول JSON DSL إلى Form.xml مع أدوات الذكاء الاصطناعي how to use form-compile form-compile setup guide 1C:Enterprise development tools Cursor IDE integration JSON DSL to Form.xml generation form-compile alternative automated form generation 1C:Enterprise AI agents form-compile install 1C：Enterprise开发 AI工具 Cursor IDE Form.xml生成 自动化开发 JSON DSL namespace声明 伴侣元素 Generates complete Form.xml files from compact JSON definitions Supports namespace declarations and autogenerates companion elements Creates sequential IDs for form elements Integrates with Cursor IDE for streamlined 1C:Enterprise development Accepts JSON DSL definitions with 20-50 lines of code Produces Form.xml files with 100-500+ lines of code form-compile is a toolkit for generating Form.xml files from JSON DSL definitions, used in 1C:Enterprise development with Cursor IDE.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muxinc/ai/develop-ai-functions-example', 'community', 'muxinc', 'ai', 'muxinc/ai', 'develop-ai-functions-example', 57, 2, 50, '2026-02-24T18:53:02Z', '2026-03-06T06:34:33.849Z', 'a8bbd98d8873d65391d19b295e97f8911d2678d6f716730229c100b366024b26', '{"id":"muxinc/ai/develop-ai-functions-example","name":"develop-ai-functions-example","description":{"en":"The develop-ai-functions-example skill connects videos in your Mux account to multi-modal LLMs using a TypeScript library. It benefits developers working with AI SDK functions.","zh":"develop-ai-functions-example 是一个 TypeScript 库，用于连接 Mux 视频到多模态 LLMs。它提供了 AI SDK 函数的示例和测试脚本","ja":"develop-ai-functions-example は、Mux ビデオを多モーダル LLMs に接続するための TypeScript ライブラリです。AI SDK 関数の例とテストスクリプトを提供します","ko":"develop-ai-functions-example는 Mux 비디오를 다중 모드 LLMs에 연결하기 위한 TypeScript 라이브러리입니다. AI SDK 함수의 예시와 테스트 스크립트를 제공합니다","es":"La biblioteca develop-ai-functions-example es una herramienta en TypeScript para conectar videos de Mux con LLMs multimodales. Ofrece ejemplos de funciones de AI para validar y probar SDK de AI.","fr":"La bibliothèque develop-ai-functions-example est un outil en TypeScript pour relier des vidéos Mux à des LLMs multimodaux. Elle propose des exemples de fonctions d''IA pour valider et tester des SDK d''IA.","de":"Die Bibliothek develop-ai-functions-example ist ein Tool in TypeScript, um Videos von Mux mit multimodalen LLMs zu verbinden. Sie bietet Beispiele für AI-Funktionen, um AI-SDKs zu validieren und zu testen.","pt":"A biblioteca develop-ai-functions-example é uma ferramenta em TypeScript para conectar vídeos no Mux a LLMs multi-modais.","ru":"Библиотека develop-ai-functions-example — это инструмент на TypeScript для подключения видео в Mux к многомодальным LLM.","ar":"مكتبة develop-ai-functions-example هي أداة بلغة TypeScript لربط الفيديوهات في Mux مع LLM