INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('muxinc/ai/develop-ai-functions-example', 'develop-ai-functions-example', 'muxinc', 'ai', 'community', 'develop-ai-functions-example muxinc ai community The develop-ai-functions-example skill connects videos in your Mux account to multi-modal LLMs using a TypeScript library. It benefits developers working with AI SDK functions. develop-ai-functions-example 是一个 TypeScript 库，用于连接 Mux 视频到多模态 LLMs。它提供了 AI SDK 函数的示例和测试脚本 develop-ai-functions-example は、Mux ビデオを多モーダル LLMs に接続するための TypeScript ライブラリです。AI SDK 関数の例とテストスクリプトを提供します develop-ai-functions-example는 Mux 비디오를 다중 모드 LLMs에 연결하기 위한 TypeScript 라이브러리입니다. AI SDK 함수의 예시와 테스트 스크립트를 제공합니다 La biblioteca develop-ai-functions-example es una herramienta en TypeScript para conectar videos de Mux con LLMs multimodales. Ofrece ejemplos de funciones de AI para validar y probar SDK de AI. La bibliothèque develop-ai-functions-example est un outil en TypeScript pour relier des vidéos Mux à des LLMs multimodaux. Elle propose des exemples de fonctions d''IA pour valider et tester des SDK d''IA. Die Bibliothek develop-ai-functions-example ist ein Tool in TypeScript, um Videos von Mux mit multimodalen LLMs zu verbinden. Sie bietet Beispiele für AI-Funktionen, um AI-SDKs zu validieren und zu testen. A biblioteca develop-ai-functions-example é uma ferramenta em TypeScript para conectar vídeos no Mux a LLMs multi-modais. Библиотека develop-ai-functions-example — это инструмент на TypeScript для подключения видео в Mux к многомодальным LLM. مكتبة develop-ai-functions-example هي أداة بلغة TypeScript لربط الفيديوهات في Mux مع LLMs متعددة الأوضاع. how to use develop-ai-functions-example develop-ai-functions-example alternative develop-ai-functions-example setup guide what is develop-ai-functions-example develop-ai-functions-example vs Mux install develop-ai-functions-example develop-ai-functions-example TypeScript library AI SDK integration with Mux multi-modal LLMs with develop-ai-functions-example AI 函数开发 Mux 视频连接 多模态 LLMs TypeScript 库 AI 驱动的视频分析 LLMs 接口 视频分析工具 Provides scripts for validating and testing AI SDK functions in the examples/ai-functions/ directory Organizes examples by AI SDK function in examples/ai-functions/src/ Supports non-streaming text generation with generateText() in generate-text/ directory Includes example categories for different AI SDK functions, such as streaming and non-streaming text generation develop-ai-functions-example is a TypeScript library for integrating AI SDK functions with Mux video accounts, providing examples for validation and testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SocketDev/socket-sdk-js/quality-scan', 'community', 'SocketDev', 'socket-sdk-js', 'SocketDev/socket-sdk-js', 'quality-scan', 44, 15, 50, '2026-02-24T19:28:14Z', '2026-03-06T06:36:26.074Z', 'b2c15220d890b826c1ec850cb47775c008645ef0ea7c9ad722dff0f288c20866', '{"id":"SocketDev/socket-sdk-js/quality-scan","name":"quality-scan","description":{"en":"The quality-scan skill performs comprehensive quality scans across the socket-sdk-js codebase to identify critical bugs, logic errors, and workflow problems, benefiting developers and DevOps teams.","zh":"质量扫描是使用专门的AIエージェント来系统地分析代码，识别关键错误和逻辑问题。它支持Socket.dev API的JavaScript SDK","ja":"Quality Scanは、専用のAIエージェントを使用してコードを分析し、クリティカルなバグやロジックエラーを特定する機能です。Socket.dev APIのJavaScript SDKに対応しています","ko":"품질 스캔은 전문적인 AI 에이전트를 사용하여 코드를 분석하여 중요한 버그 및 논리 오류를 식별하는 기능입니다. Socket.dev API의 JavaScript SDK를 지원합니다","es":"Quality-scan es una herramienta de análisis de código que utiliza agentes especializados para identificar errores y problemas en el código JavaScript","fr":"Quality-scan est un outil d''analyse de code qui utilise des agents spécialisés pour détecter les erreurs et les problèmes dans le code JavaScript","de":"Quality-scan ist ein Code-Analyse-Tool, das spezialisierte Agenten verwendet, um Fehler und Probleme im JavaScript-Code zu identifizieren","pt":"O quality-scan é uma ferramenta de análise de código JavaScript que utiliza agentes de inteligência artificial para identificar bugs e melhorar a qualidade do código","ru":"Quality-scan - это инструмент для проверки кода JavaScript, использующий ИИ агентов для выявления ошибок и улучшения качества кода","ar":"quality-scan هو أداة فحص الشفرة البرمجية JavaScript التي تستخدم أدوات الذكاء الاصطناعي لتحديد الأخطاء وتحسين جودة الكود"},"seo":{"title":{"en":"quality-scan: Comprehensive Code Review for AI Agents | A...","zh":"质量扫描设置指南 - 使用Socket.dev API的JavaScript SDK","ja":"Quality Scanセットアップガイド - Socket.dev APIのJavaScript SDK","ko":"품질 스캔 설정 가이드 - Socket.dev API의 JavaScript SDK","es":"Guía de configuración de quality-scan para JavaScript SDK","fr":"Paramétrer quality-scan pour le SDK JavaScript de Socket.dev","de":"Einrichtungsleitfaden für quality-scan mit JavaScript SDK","pt":"Guia de Configuração do quality-scan: Análise de Código c...","ru":"Настройка quality-scan: Проверка Кодов с Помощью ИИ Агентов","ar":"دليل إعداد quality-scan: فحص الشفرة البرمجية باستخدام أدو..."},"description":{"en":"Discover how quality-scan''s JavaScript SDK for Socket.dev API identifies critical bugs and logic errors. Get started with our setup guide and improve your co...","zh":"了解如何使用质量扫描（Quality Scan）AIエージェント来识别代码中的关键错误和逻辑问题，优化Socket.dev API的JavaScript SDK","ja":"Quality Scan AIエージェントを使用して、Socket.dev APIのJavaScript SDKのコードを分析し、クリティカルなバグやロジックエラーを特定します","ko":"품질 스캔 AI 에이전트를 사용하여 Socket.dev API의 JavaScript SDK 코드를 분석하고 중요한 버그 및 논리 오류를 식별하는 방법에 대해 알아보세요","es":"Aprende a utilizar quality-scan para identificar errores críticos en tu código JavaScript con el SDK de Socket.dev","fr":"Découvrez comment utiliser quality-scan pour détecter les bogues critiques dans votre code JavaScript avec le SDK Socket.dev","de":"Erfahren Sie, wie Sie quality-scan verwenden, um kritische Fehler in Ihrem JavaScript-Code mit dem Socket.dev-SDK zu finden","pt":"Aprenda a configurar o quality-scan para análise de código JavaScript com agentes de inteligência artificial e melhore a qualidade do seu código","ru":"Узнайте, как настроить quality-scan для проверки кода JavaScript с помощью ИИ агентов и улучшить качество своего кода","ar":"تعرف على كيفية إعداد quality-scan لفحص الشفرة البرمجية JavaScript باستخدام أدوات الذكاء الاصطناعي وتحسين جودة كودك"},"definition":{"en":"quality-scan is a JavaScript SDK for Socket.dev API that uses specialized AI agents to systematically analyze code for defects and generate prioritized reports","zh":"质量扫描是代码分析技术，使用AIエージェント来识别错误和逻辑问题","ja":"Quality Scanは、コードを分析してバグやロジックエラーを特定する技術です。AIエージェントを使用します","ko":"품질 스캔은 코드 분석 기술로 AI 에이전트를 사용하여 버그 및 논리 오류를 식별합니다","es":"Quality-scan es un proceso de análisis de código que utiliza herramientas de inteligencia artificial para detectar errores y mejorar la calidad del código","fr":"Quality-scan est un processus d''analyse de code qui utilise des outils d''intelligence artificielle pour détecter les erreurs et améliorer la qualité du code","de":"Quality-scan ist ein Code-Analyse-Prozess, der künstliche Intelligenz-Tools verwendet, um Fehler zu erkennen und die Code-Qualität zu verbessern","pt":"O que é quality-scan? É uma ferramenta de análise de código que utiliza agentes de inteligência artificial para identificar bugs e melhorar a qualidade do código","ru":"Что такое quality-scan? Это инструмент для проверки кода, использующий ИИ агентов для выявления ошибок и улучшения качества кода","ar":"ما هو quality-scan؟ هي أداة فحص الشفرة البرمجية التي تستخدم أدوات الذكاء الاصطناعي لتحديد الأخطاء وتحسين جودة الكود"},"features":{"en":["Updates dependencies to ensure a clean and organized repository","Cleans up junk files to prepare for comprehensive quality scans","Uses specialized AI agents to identify critical bugs, logic errors, and workflow problems","Generates a prioritized report with actionable improvement tasks","Supports TypeScript for robust and maintainable code"],"zh":["支持Socket.dev API的JavaScript SDK","使用专门的AIエージェント来分析代码","识别关键错误和逻辑问题","生成优先级报告以改进代码","支持TypeScript和JavaScript"],"ja":["Socket.dev APIのJavaScript SDKに対応","専用のAIエージェントを使用してコードを分析","クリティカルなバグやロジックエラーを特定","改善タスクの優先順位を付けたレポートを生成","TypeScriptとJavaScriptをサポート"],"ko":["Socket.dev API의 JavaScript SDK 지원","전문적인 AI 에이전트를 사용하여 코드 분석","중요한 버그 및 논리 오류 식별","개선 작업의 우선 순위를 정한 보고서 생성","TypeScript 및 JavaScript 지원"],"es":["Análisis de código JavaScript con agentes especializados","Identificación de errores críticos y problemas de lógica","Generación de informes priorizados con tareas de mejora","Integración con el SDK de Socket.dev","Soporte para TypeScript","Limpieza de archivos innecesarios y actualización de dependencias"],"fr":["Analyse de code JavaScript avec des agents spécialisés","Détection d''erreurs critiques et de problèmes de logique","Génération de rapports priorisés avec des tâches d''amélioration","Intégration avec le SDK Socket.dev","Prise en charge de TypeScript","Nettoyage de fichiers inutiles et mise à jour des dépendances"],"de":["JavaScript-Code-Analyse mit spezialisierten Agenten","Erkennung kritischer Fehler und Logikprobleme","Generierung priorisierter Berichte mit Verbesserungsaufgaben","Integration mit dem Socket.dev-SDK","Unterstützung für TypeScript","Bereinigung unnötiger Dateien und Aktualisierung von Abhängigkeiten"],"pt":["Análise de código JavaScript com agentes de inteligência artificial","Identificação de bugs e erros de lógica","Geração de relatórios priorizados com tarefas de melhoria","Suporte à atualização de dependências e limpeza de arquivos","Integração com o Socket.dev API"],"ru":["Проверка кода JavaScript с помощью ИИ агентов","Выявление ошибок и логических ошибок","Генерация отчетов с приоритетными задачами для улучшения","Поддержка обновления зависимостей и очистки файлов","Интеграция с Socket.dev API"],"ar":["فحص الشفرة البرمجية JavaScript باستخدام أدوات الذكاء الاصطناعي","تحديد الأخطاء والأخطاء المنطقية","توليد تقارير ذات أولوية مع مهام تحسين","دعم تحديث الاعتماديات وتنظيف الملفات","التكامل مع Socket.dev API"]},"keywords":{"en":["how to use quality-scan","quality-scan alternative","quality-scan setup guide","what is quality-scan","quality-scan vs socket.io","quality-scan install","socket-dev api tutorial","javascript sdk for socket dev","comprehensive code review tools"],"zh":["质量扫描","AIエージェント","Socket.dev API","JavaScript SDK","代码分析","错误识别","逻辑问题","TypeScript","JavaScript"],"ja":["Quality Scan","AIエージェント","Socket.dev API","JavaScript SDK","コード分析","バグ特定","ロジックエラー","TypeScript","JavaScript"],"ko":["품질 스캔","AI 에이전트","Socket.dev API","JavaScript SDK","코드 분석","버그 식별","논리 오류","TypeScript","JavaScript"],"es":["quality-scan","análisis de código","JavaScript SDK","Socket.dev","herramientas de inteligencia artificial","agentes de calidad","mejora de código","detención de errores","TypeScript","desarrollo de software"],"fr":["quality-scan","analyse de code","SDK JavaScript","Socket.dev","outils d''intelligence artificielle","agents de qualité","amélioration de code","détection d''erreurs","TypeScript","développement de logiciels"],"de":["quality-scan","Code-Analyse","JavaScript-SDK","Socket.dev","künstliche Intelligenz-Tools","Qualitätsagenten","Code-Verbesserung","Fehlererkennung","TypeScript","Softwareentwicklung"],"pt":["quality-scan","análise de código","agentes de inteligência artificial","JavaScript","Socket.dev API","segurança","desenvolvimento de software"],"ru":["quality-scan","проверка кода","ИИ агенты","JavaScript","Socket.dev API","безопасность","разработка программного обеспечения"],"ar":["quality-scan","فحص الشفرة البرمجية","أدوات الذكاء الاصطناعي","JavaScript","Socket.dev API","أمان","تطوير البرمجيات"]}},"owner":"SocketDev","repo":"socket-sdk-js","repoPath":"SocketDev/socket-sdk-js","stars":44,"forks":15,"updatedAt":"2026-02-24T19:28:14Z","topics":["api","javascript","sdk","security","socket","typescript"],"category":"community","skillMd":{"name":"quality-scan","description":"Updates dependencies, cleans up junk files, and performs comprehensive quality scans across codebase to identify critical bugs, logic errors, and workflow problems. Spawns specialized agents for targeted analysis and generates prioritized improvement tasks. Use when improving code quality, before releases, or investigating issues.","bodyPreview":"# quality-scan\n\n<task>\nYour task is to perform comprehensive quality scans across the socket-sdk-js codebase using specialized agents to identify critical bugs, logic errors, and workflow problems. Before scanning, update dependencies and clean up junk files to ensure a clean and organized repository. Generate a prioritized report with actionable improvement tasks.\n</task>\n\n<context>\n**What is Quality Scanning?**\nQuality scanning uses specialized AI agents to systematically analyze code for diff","body":"# quality-scan\n\n<task>\nYour task is to perform comprehensive quality scans across the socket-sdk-js codebase using specialized agents to identify critical bugs, logic errors, and workflow problems. Before scanning, update dependencies and clean up junk files to ensure a clean and organized repository. Generate a prioritized report with actionable improvement tasks.\n</task>\n\n<context>\n**What is Quality Scanning?**\nQuality scanning uses specialized AI agents to systematically analyze code for different categories of issues. Each agent type focuses on specific problem domains and reports findings with severity levels and actionable fixes.\n\n**socket-sdk-js Architecture:**\nThis is Socket Security''s TypeScript/JavaScript SDK that:\n- Provides programmatic access to Socket.dev security analysis\n- Implements HTTP client with retry logic and rate limiting\n- Handles API authentication and request/response validation\n- Generates strict TypeScript types from OpenAPI specifications\n- Supports package scanning, SBOM generation, and organization management\n- Implements comprehensive test coverage with Vitest\n\n**Scan Types Available:**\n1. **critical** - Crashes, security vulnerabilities, resource leaks, data corruption\n2. **logic** - Algorithm errors, edge cases, type guards, off-by-one errors\n3. **workflow** - Build scripts, CI issues, cross-platform compatibility\n4. **security** - GitHub Actions workflow security (zizmor scanner)\n5. **documentation** - README accuracy, outdated docs, missing documentation\n\n**Why Quality Scanning Matters:**\n- Catches bugs before they reach production\n- Identifies security vulnerabilities early\n- Improves code quality systematically\n- Provides actionable fixes with file:line references\n- Prioritizes issues by severity for efficient remediation\n- Keeps dependencies up-to-date\n- Cleans up junk files for a well-organized repository\n\n**Agent Prompts:**\nAll agent prompts are embedded in `reference.md` with structured <context>, <instructions>, <pattern>, and <output_format> tags following Claude best practices.\n</context>\n\n<constraints>\n**CRITICAL Requirements:**\n- Read-only analysis (no code changes during scan)\n- Must complete all enabled scans before reporting\n- Findings must be prioritized by severity (Critical → High → Medium → Low)\n- Must generate actionable tasks with file:line references\n- All findings must include suggested fixes\n\n**Do NOT:**\n- Fix issues during scan (analysis only - report findings)\n- Skip critical scan types without user permission\n- Report findings without file/line references\n- Proceed if codebase has uncommitted changes (warn but continue)\n\n**Do ONLY:**\n- Update dependencies before scanning\n- Run enabled scan types in priority order (critical → logic → workflow)\n- Generate structured findings with severity levels\n- Provide actionable improvement tasks with specific code changes\n- Report statistics and coverage metrics\n- Deduplicate findings across scans\n</constraints>\n\n<instructions>\n\n## Process\n\nExecute the following phases sequentially to perform comprehensive quality analysis.\n\n### Phase 1: Validate Environment\n\n<prerequisites>\nVerify the environment before starting scans:\n</prerequisites>\n\n```bash\ngit status\n```\n\n<validation>\n**Expected State:**\n- Working directory should be clean (warn if dirty but continue)\n- On a valid branch\n- Node modules installed\n\n**If working directory dirty:**\n- Warn user: \"Working directory has uncommitted changes - continuing with scan\"\n- Continue with scans (quality scanning is read-only)\n\n</validation>\n\n---\n\n### Phase 2: Update Dependencies\n\n<action>\nUpdate dependencies across Socket Security SDK repositories to ensure latest versions:\n</action>\n\n**Target Repositories:**\n1. **socket-sdk-js** (current repository)\n2. **socket-cli** (`../socket-cli/`)\n3. **socket-btm** (`../socket-btm/`)\n4. **socket-registry** (`../socket-registry/`)\n\n**Update Process:**\n\nFor each repository, run dependency updates:\n\n```bash\n# socket-sdk-js (current repo)\npnpm run update\n\n# socket-cli\ncd ../socket-cli && pnpm run update && cd -\n\n# socket-btm\ncd ../socket-btm && pnpm run update && cd -\n\n# socket-registry\ncd ../socket-registry && pnpm run update && cd -\n```\n\n<validation>\n**For each repository:**\n1. Check if directory exists (skip if not found)\n2. Run `pnpm run update` command\n3. Report success or failure\n4. Track updated packages count\n5. Continue even if some repos fail\n\n**Expected Results:**\n- Dependencies updated in available repositories\n- Report number of packages updated per repository\n- Note any repositories that were skipped (not found)\n- Continue with scan even if updates fail\n\n**Track for reporting:**\n- Repositories updated: N/4\n- Total packages updated: N\n- Failed updates: N (continue with warnings)\n- Skipped repositories: [list]\n\n</validation>\n\n---\n\n### Phase 3: Repository Cleanup\n\n<action>\nClean up junk files and organize the repository before scanning:\n</action>\n\n**Cleanup Tasks:**\n\n1. **Remove SCREAMING_TEXT.md files** (all-caps .md files) that are NOT:\n   - Inside `.claude/` directory\n   - Inside `docs/` directory\n   - Named `README.md`, `LICENSE`, or `SECURITY.md`\n\n2. **Remove temporary test files** in wrong locations:\n   - `.test.mjs` or `.test.mts` files outside `test/` or `__tests__/` directories\n   - Temp files: `*.tmp`, `*.temp`, `.DS_Store`, `Thumbs.db`\n   - Editor backups: `*~`, `*.swp`, `*.swo`, `*.bak`\n   - Test artifacts: `*.log` files in root or package directories (not logs/)\n\n```bash\n# Find SCREAMING_TEXT.md files (all caps with .md extension)\nfind . -type f -name ''*.md'' \\\n  ! -path ''./.claude/*'' \\\n  ! -path ''./docs/*'' \\\n  ! -name ''README.md'' \\\n  ! -name ''LICENSE'' \\\n  ! -name ''SECURITY.md'' \\\n  | grep -E ''/[A-Z_]+\\.md$''\n\n# Find test files in wrong locations\nfind . -type f \\( -name ''*.test.mjs'' -o -name ''*.test.mts'' \\) \\\n  ! -path ''*/test/*'' \\\n  ! -path ''*/__tests__/*'' \\\n  ! -path ''*/node_modules/*''\n\n# Find temp files\nfind . -type f \\( \\\n  -name ''*.tmp'' -o \\\n  -name ''*.temp'' -o \\\n  -name ''.DS_Store'' -o \\\n  -name ''Thumbs.db'' -o \\\n  -name ''*~'' -o \\\n  -name ''*.swp'' -o \\\n  -name ''*.swo'' -o \\\n  -name ''*.bak'' \\\n\\) ! -path ''*/node_modules/*''\n\n# Find log files in wrong places (not in logs/ or build/ directories)\nfind . -type f -name ''*.log'' \\\n  ! -path ''*/logs/*'' \\\n  ! -path ''*/build/*'' \\\n  ! -path ''*/node_modules/*'' \\\n  ! -path ''*/.git/*''\n```\n\n<validation>\n**For each file found:**\n1. Show the file path to user\n2. Explain why it''s considered junk\n3. Ask user for confirmation before deleting (use AskUserQuestion)\n4. Delete confirmed files: `git rm` if tracked, `rm` if untracked\n5. Report files removed\n\n**If no junk files found:**\n- Report: \"✓ Repository is clean - no junk files found\"\n\n**Important:**\n- Always get user confirmation before deleting\n- Show file contents if user is unsure\n- Track deleted files for reporting\n\n</validation>\n\n---\n\n### Phase 4: Determine Scan Scope\n\n<action>\nAsk user which scans to run:\n</action>\n\n**Default Scan Types** (run all unless user specifies):\n1. **critical** - Critical bugs (crashes, security, resource leaks)\n2. **logic** - Logic errors (algorithms, edge cases, type guards)\n3. **workflow** - Workflow problems (scripts, CI, git hooks)\n4. **security** - GitHub Actions security (template injection, cache poisoning, etc.)\n5. **documentation** - Documentation accuracy (README errors, outdated docs)\n\n**User Interaction:**\nUse AskUserQuestion tool:\n- Question: \"Which quality scans would you like to run?\"\n- Header: \"Scan Types\"\n- multiSelect: true\n- Options:\n  - \"All scans (recommended)\" → Run all scan types\n  - \"Critical only\" → Run critical scan only\n  - \"Critical + Logic\" → Run critical and logic scans\n  - \"Custom selection\" → Ask user to specify which scans\n\n**Default:** If user doesn''t specify, run all scans.\n\n<validation>\nValidate selected scan types exist in reference.md:\n- critical-scan → reference.md line ~5\n- logic-scan → reference.md line ~100\n- workflow-scan → reference.md line ~300\n- security-scan → reference.md line ~400\n- documentation-scan → reference.md line ~810\n\nIf user requests non-existent scan type, report error and suggest valid types.\n</validation>\n\n---\n\n### Phase 5: Execute Scans\n\n<action>\nFor each enabled scan type, spawn a specialized agent using Task tool:\n</action>\n\n```typescript\n// Example: Critical scan\nTask({\n  subagent_type: \"general-purpose\",\n  description: \"Critical bugs scan\",\n  prompt: `${CRITICAL_SCAN_PROMPT_FROM_REFERENCE_MD}\n\nFocus on src/ directory (HTTP client, SDK class, type generation scripts).\n\nSDK-specific patterns to check:\n- HTTP client error handling (src/http-client.ts)\n- API method validation (src/socket-sdk-class.ts)\n- Type generation scripts (scripts/generate-*.mjs)\n- Promise handling and retry logic\n- JSON parsing errors\n- Rate limiting and timeout handling\n\nReport findings in this format:\n- File: path/to/file.ts:lineNumber\n- Issue: Brief description\n- Severity: Critical/High/Medium/Low\n- Pattern: Code snippet\n- Trigger: What input triggers this\n- Fix: Suggested fix\n- Impact: What happens if triggered\n\nScan systematically and report all findings. If no issues found, state that explicitly.`\n})\n```\n\n**For each scan:**\n1. Load agent prompt template from `reference.md`\n2. Customize for socket-sdk-js context (focus on src/, scripts/, test/)\n3. Spawn agent with Task tool using \"general-purpose\" subagent_type\n4. Capture findings from agent response\n5. Parse and categorize results\n\n**Execution Order:** Run scans sequentially in priority order:\n- critical (highest priority)\n- logic\n- workflow\n- security\n- documentation (lowest priority)\n\n**Agent Prompt Sources:**\n- Critical scan: reference.md starting at line ~12\n- Logic scan: reference.md starting at line ~100\n- Workflow scan: reference.md starting at line ~300\n- Security scan: reference.md starting at line ~400\n- Documentation scan: reference.md starting at line ~810\n\n<validation>\n**Structured Output Validation:**\n\nAfter each agent returns, validate output structure before parsing:\n\n```bash\n# 1. Verify agent completed successfully\nif [ -z \"\" ]; then\n  echo \"ERROR: Agent returned no output\"\n  exit 1\nfi\n\n# 2. Check for findings or clean report\nif ! echo \"\" | grep -qE ''(File:.*Issue:|No .* issues found|✓ Clean)''; then\n  echo \"WARNING: Agent output missing expected format\"\n  echo \"Agent may have encountered an error or found no issues\"\nfi\n\n# 3. Verify severity levels if findings exist\nif echo \"\" | grep -q \"File:\"; then\n  if ! echo \"\" | grep -qE ''Severity: (Critical|High|Medium|Low)''; then\n    echo \"WARNING: Findings missing severity classification\"\n  fi\nfi\n\n# 4. Verify fix suggestions if findings exist\nif echo \"\" | grep -q \"File:\"; then\n  if ! echo \"\" | grep -q \"Fix:\"; then\n    echo \"WARNING: Findings missing suggested fixes\"\n  fi\nfi\n```\n\n**Manual Verification Checklist:**\n- [ ] Agent output includes findings OR explicit \"No issues found\" statement\n- [ ] All findings include file:line references\n- [ ] All findings include severity level (Critical/High/Medium/Low)\n- [ ] All findings include suggested fixes\n- [ ] Agent output is parseable and structured\n\n**For each scan completion:**\n- Verify agent completed without errors\n- Extract findings from agent output (or confirm \"No issues found\")\n- Parse into structured format (file, issue, severity, fix)\n- Track scan coverage (files analyzed)\n- Log any validation warnings for debugging\n</validation>\n\n---\n\n### Phase 6: Aggregate Findings\n\n<action>\nCollect all findings from agents and aggregate:\n</action>\n\n```typescript\ninterface Finding {\n  file: string           // \"src/http-client.ts:89\"\n  issue: string          // \"Potential null pointer access\"\n  severity: \"Critical\" | \"High\" | \"Medium\" | \"Low\"\n  scanType: string       // \"critical\"\n  pattern: string        // Code snippet showing the issue\n  trigger: string        // What causes this issue\n  fix: string            // Suggested code change\n  impact: string         // What happens if triggered\n}\n```\n\n**Deduplication:**\n- Remove duplicate findings across scans (same file:line, same issue)\n- Keep the finding from the highest priority scan\n- Track which scans found the same issue\n\n**Prioritization:**\n- Sort by severity: Critical → High → Medium → Low\n- Within same severity, sort by scanType priority\n- Within same severity+scanType, sort alphabetically by file path\n\n<validation>\n**Checkpoint:** Verify aggregation:\n- Total findings count\n- Breakdown by severity (N critical, N high, N medium, N low)\n- Breakdown by scan type\n- Duplicate removal count (if any)\n</validation>\n\n---\n\n### Phase 7: Generate Report\n\n<action>\nCreate structured quality report with all findings:\n</action>\n\n```markdown\n# Quality Scan Report\n\n**Date:** YYYY-MM-DD\n**Repository:** socket-sdk-js\n**Scans:** [list of scan types run]\n**Files Scanned:** N\n**Findings:** N critical, N high, N medium, N low\n\n## Critical Issues (Priority 1) - N found\n\n### src/http-client.ts:89\n- **Issue**: Potential null pointer access in retry logic\n- **Pattern**: `const result = response.data.items[0]`\n- **Trigger**: When API returns empty array\n- **Fix**: `const items = response.data?.items ?? []; if (items.length === 0) throw new Error(''No items found''); const result = items[0]`\n- **Impact**: Crashes SDK, breaks user applications\n- **Scan**: critical\n\n## High Issues (Priority 2) - N found\n\n[Similar format for high severity issues]\n\n## Medium Issues (Priority 3) - N found\n\n[Similar format for medium severity issues]\n\n## Low Issues (Priority 4) - N found\n\n[Similar format for low severity issues]\n\n## Scan Coverage\n\n- **Critical scan**: N files analyzed in src/, scripts/\n- **Logic scan**: N files analyzed (API methods, type generation)\n- **Workflow scan**: N files analyzed (package.json, scripts/, .github/)\n\n## Recommendations\n\n1. Address N critical issues immediately before next release\n2. Review N high-severity logic errors in HTTP client\n3. Schedule N medium issues for next sprint\n4. Low-priority items can be addressed during refactoring\n\n## No Findings\n\n[If a scan found no issues, list it here:]\n- Critical scan: ✓ Clean\n- Logic scan: ✓ Clean\n```\n\n**Output Report:**\n1. Display report to console (user sees it)\n2. Offer to save to file (optional): `reports/quality-scan-YYYY-MM-DD.md`\n\n<validation>\n**Report Quality Checks:**\n- All findings include file:line references\n- All findings include suggested fixes\n- Findings are grouped by severity\n- Scan coverage statistics included\n- Recommendations are actionable\n</validation>\n\n---\n\n### Phase 8: Complete\n\n<completion_signal>\n```xml\n<promise>QUALITY_SCAN_COMPLETE</promise>\n```\n</completion_signal>\n\n<summary>\nReport these final metrics to the user:\n\n**Quality Scan Complete**\n========================\n✓ Dependency updates: N repositories, N packages updated\n✓ Repository cleanup: N junk files removed\n✓ Scans completed: [list of scan types]\n✓ Total findings: N (N critical, N high, N medium, N low)\n✓ Files scanned: N\n✓ Report generated: Yes\n✓ Scan duration: [calculated from start to end]\n\n**Dependency Update Summary:**\n- socket-sdk-js: N packages updated\n- socket-cli: N packages updated (or skipped)\n- socket-btm: N packages updated (or skipped)\n- socket-registry: N packages updated (or skipped)\n\n**Repository Cleanup Summary:**\n- SCREAMING_TEXT.md files removed: N\n- Temporary test files removed: N\n- Temp/backup files removed: N\n- Log files cleaned up: N\n\n**Critical Issues Requiring Immediate Attention:**\n- N critical issues found\n- Review report above for details and fixes\n\n**Next Steps:**\n1. Address critical issues immediately\n2. Review high-severity findings\n3. Schedule medium/low issues appropriately\n4. Re-run scans after fixes to verify\n\nAll findings include file:line references and suggested fixes.\n</summary>\n\n</instructions>\n\n## Success Criteria\n\n- ✅ `<promise>QUALITY_SCAN_COMPLETE</promise>` output\n- ✅ Dependencies updated in available repositories\n- ✅ All enabled scans completed without errors\n- ✅ Findings prioritized by severity (Critical → Low)\n- ✅ All findings include file:line references\n- ✅ Actionable suggestions provided for all findings\n- ✅ Report generated with statistics and coverage metrics\n- ✅ Duplicate findings removed\n\n## Scan Types\n\nSee `reference.md` for detailed agent prompts with structured tags:\n\n- **critical-scan** - Null access, promise rejections, race conditions, resource leaks\n- **logic-scan** - Off-by-one errors, type guards, edge cases, algorithm correctness\n- **workflow-scan** - Scripts, package.json, git hooks, CI configuration\n- **security-scan** - GitHub Actions workflow security (runs zizmor scanner)\n- **documentation-scan** - README accuracy, outdated examples, incorrect package names, missing documentation\n\nAll agent prompts follow Claude best practices with <context>, <instructions>, <pattern>, <output_format>, and <quality_guidelines> tags.\n\n## Commands\n\nThis skill is self-contained. No external commands needed.\n\n## Context\n\nThis skill provides systematic code quality analysis for socket-sdk-js by:\n- Updating dependencies before scanning to ensure latest versions\n- Spawning specialized agents for targeted analysis\n- Using Task tool to run agents autonomously\n- Embedding agent prompts in reference.md following best practices\n- Generating prioritized, actionable reports\n- Supporting partial scans (user can select specific scan types)\n\nFor detailed agent prompts with best practices structure, see `reference.md`.\n"},"lastSynced":"2026-03-06T06:36:26.074Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced bug detection and code analysis capabilities in JavaScript projects.","zh":"适用于需要高级错误检测和代码分析功能的 JavaScript 项目的代码审查代理。","ja":"JavaScript プロジェクトで高度なバグ検出とコード分析機能を必要とするコードレビュー エージェントに適しています。","ko":"JavaScript 프로젝트에서 고급 버그 감지 및 코드 분석 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan detección avanzada de errores y capacidades de análisis de código en proyectos JavaScript.","fr":"Parfait pour les agents de révision de code nécessitant une détection avancée de bogues et des capacités d''analyse de code dans les projets JavaScript.","de":"Perfekt für Code-Review-Agenten, die erweiterte Fehlersuche- und Codeanalysefunktionen in JavaScript-Projekten benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de detecção avançada de bugs e capacidades de análise de código em projetos JavaScript.","ru":"Идеально подходит для агентов проверки кода, которым требуются продвинутые возможности обнаружения ошибок и анализа кода в проектах JavaScript.","ar":"مثالي للوكلاء قليلي الكود الذين يحتاجون إلى كشف متقدم عن الأخطاء ووظائف تحليل الشفرة في مشاريع JavaScript."},"recommendation":{"en":"Empowers agents to perform comprehensive quality scans across codebases, identifying critical bugs, logic errors, and workflow problems using socket-sdk-js, and generates prioritized reports with actionable improvement tasks, leveraging dependencies update and cleanup for a clean repository.","zh":"赋予代理执行整个代码库的全面质量扫描的能力，使用 socket-sdk-js 识别关键错误、逻辑错误和工作流问题，并生成带有可操作的改进任务的优先报告，利用依赖项更新和清理以保持干净的存储库。","ja":"エージェントが socket-sdk-js を使用してコードベース全体の包括的な品質スキャンを実行し、重要なバグ、論理エラー、ワークフローの問題を識別し、優先度の付いた報告書を生成し、依存関係の更新とクリーンアップを活用してクリーンなリポジトリを維持できるようにします。","ko":"에이전트가 socket-sdk-js를 사용하여 전체 코드베이스에 대한 종합적인 품질 스キャ닝을 수행하여 중요한 버그, 논리 오류 및 워크플로우 문제를 식별하고, 작업할 수 있는 개선 작업이 포함된 우선 순위 보고서를 생성하며, 의존성 업데이트와 정리를 통해 깔끔한 저장소를 유지할 수 있도록 합니다.","es":"Habilita a los agentes a realizar análisis de calidad exhaustivos en codebases, identificando errores críticos, errores lógicos y problemas de flujo de trabajo utilizando socket-sdk-js, y genera informes prioritarios con tareas de mejora accionables, aprovechando la actualización y limpieza de dependencias para un repositorio limpio.","fr":"Permet aux agents d''effectuer des analyses de qualité exhaustives sur les codebases, en identifiant les bogues critiques, les erreurs logiques et les problèmes de workflow en utilisant socket-sdk-js, et génère des rapports priorisés avec des tâches d''amélioration actionnables, en exploitant la mise à jour et le nettoyage des dépendances pour un référentiel propre.","de":"Ermächtigt Agenten, umfassende Qualitätsprüfungen über Codebasen hinweg durchzuführen, indem kritische Fehler, Logikfehler und Workflowprobleme unter Verwendung von socket-sdk-js identifiziert werden, und generiert priorisierte Berichte mit handhabbaren Verbesserungsaufgaben, indem die Aktualisierung und Bereinigung von Abhängigkeiten für ein sauberes Repository genutzt wird.","pt":"Habilita agentes a realizar varreduras de qualidade abrangentes em repositórios de código, identificando bugs críticos, erros lógicos e problemas de fluxo de trabalho usando socket-sdk-js, e gera relatórios prioritários com tarefas de melhoria viáveis, aproveitando a atualização e limpeza de dependências para um repositório limpo.","ru":"Позволяет агентам выполнять всесторонние проверки качества кода, выявляя критические ошибки, логические ошибки и проблемы с рабочим процессом с помощью socket-sdk-js, и генерирует отчеты с приоритезацией и задачами по улучшению, используя обновление и очистку зависимостей для чистого репозитория.","ar":"يمنح الوكلاء khảية إجراء فحوصات شاملة لجودة الشفرة عبر مستودعات الشفرة، وتحديد الأخطاء الحرجة وأخطاء المنطق ومشاكل سير العمل باستخدام socket-sdk-js، ويت动生成 تقارير ذات أولوية مع مهام تحسين قابلة للتنفيذ، يستفيد من تحديث وتنظيف الإعتماديات من أجل مستودع نظيف."},"useCases":{"en":["Automating code reviews for JavaScript projects","Debugging critical bugs in socket-sdk-js codebases","Generating quality reports for DevOps teams"],"zh":["为 JavaScript 项目自动执行代码审查","调试 socket-sdk-js 代码库中的关键错误","为 DevOps 团队生成质量报告"],"ja":["JavaScript プロジェクトのコード レビューを自動化する","socket-sdk-js コード ベースの重要なバグをデバッグする","DevOps チームの品質報告書を生成する"],"ko":["JavaScript 프로젝트의 코드 리뷰를 자동화하는 것","socket-sdk-js 코드베이스의 중요한 버그를 디버깅하는 것","DevOps 팀을 위한 품질 보고서를 생성하는 것"],"es":["Automatización de revisiones de código para proyectos JavaScript","Depuración de errores críticos en codebases de socket-sdk-js","Generación de informes de calidad para equipos de DevOps"],"fr":["Automatisation des révisions de code pour les projets JavaScript","Débogage des bogues critiques dans les codebases de socket-sdk-js","Génération de rapports de qualité pour les équipes DevOps"],"de":["Automatisierung von Code-Reviews für JavaScript-Projekte","Fehlersuche bei kritischen Fehlern in socket-sdk-js-Codebasen","Generierung von Qualitätsberichten für DevOps-Teams"],"pt":["Automatizar revisões de código para projetos JavaScript","Depurar bugs críticos em codebases socket-sdk-js","Gerar relatórios de qualidade para equipes DevOps"],"ru":["Автоматизировать проверку кода для проектов JavaScript","Отладить критические ошибки в коде socket-sdk-js","Генерировать отчеты о качестве для команд DevOps"],"ar":["توفير automatizar مراجعة الشفرة لمشاريع JavaScript","تصحيح الأخطاء الحرجة في код socket-sdk-js","توليد تقارير الجودة لفريق DevOps"]},"limitations":{"en":["Requires access to the socket-sdk-js codebase","JavaScript projects only","Needs dependencies update and cleanup for optimal performance"],"zh":["需要访问 socket-sdk-js 代码库","仅限 JavaScript 项目","需要依赖项更新和清理以实现最佳性能"],"ja":["socket-sdk-js コード ベースへのアクセスが必要","JavaScript プロジェクトのみ","最適なパフォーマンスを実現するには依存関係の更新とクリーンアップが必要"],"ko":["socket-sdk-js 코드베이스에 대한 액세스가 필요합니다","JavaScript 프로젝트만 해당","최적의 성능을 달성하려면 종속성 업데이트와 정리가 필요"],"es":["Requiere acceso a la codebase de socket-sdk-js","Solo proyectos JavaScript","Necesita actualización y limpieza de dependencias para un rendimiento óptimo"],"fr":["Nécessite un accès à la codebase de socket-sdk-js","Uniquement les projets JavaScript","Nécessite une mise à jour et un nettoyage des dépendances pour des performances optimales"],"de":["Benötigt Zugriff auf die socket-sdk-js-Codebase","Nur JavaScript-Projekte","Benötigt Aktualisierung und Bereinigung von Abhängigkeiten für optimale Leistung"],"pt":["Requer acesso ao codebase socket-sdk-js","Apenas projetos JavaScript","Necessita de atualização e limpeza de dependências para desempenho ótimo"],"ru":["Требует доступа к коду socket-sdk-js","Только проекты JavaScript","Требует обновления и очистки зависимостей для оптимальной производительности"],"ar":["يتطلب الوصول إلى قاعدة الشفرة socket-sdk-js","مشاريع JavaScript فقط","يحتاج إلى تحديث وتنظيف الإعتماديات لأداء مثالي"]},"version":4},"contentHash":"b2c15220d890b826c1ec850cb47775c008645ef0ea7c9ad722dff0f288c20866","qualityScore":50}');
