INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SocketDev/socket-sdk-js/quality-scan', 'quality-scan', 'SocketDev', 'socket-sdk-js', 'community', 'quality-scan SocketDev socket-sdk-js community api javascript sdk security socket typescript The quality-scan skill performs comprehensive quality scans across the socket-sdk-js codebase to identify critical bugs, logic errors, and workflow problems, benefiting developers and DevOps teams. 质量扫描是使用专门的AIエージェント来系统地分析代码，识别关键错误和逻辑问题。它支持Socket.dev API的JavaScript SDK Quality Scanは、専用のAIエージェントを使用してコードを分析し、クリティカルなバグやロジックエラーを特定する機能です。Socket.dev APIのJavaScript SDKに対応しています 품질 스캔은 전문적인 AI 에이전트를 사용하여 코드를 분석하여 중요한 버그 및 논리 오류를 식별하는 기능입니다. Socket.dev API의 JavaScript SDK를 지원합니다 Quality-scan es una herramienta de análisis de código que utiliza agentes especializados para identificar errores y problemas en el código JavaScript Quality-scan est un outil d''analyse de code qui utilise des agents spécialisés pour détecter les erreurs et les problèmes dans le code JavaScript Quality-scan ist ein Code-Analyse-Tool, das spezialisierte Agenten verwendet, um Fehler und Probleme im JavaScript-Code zu identifizieren O quality-scan é uma ferramenta de análise de código JavaScript que utiliza agentes de inteligência artificial para identificar bugs e melhorar a qualidade do código Quality-scan - это инструмент для проверки кода JavaScript, использующий ИИ агентов для выявления ошибок и улучшения качества кода quality-scan هو أداة فحص الشفرة البرمجية JavaScript التي تستخدم أدوات الذكاء الاصطناعي لتحديد الأخطاء وتحسين جودة الكود how to use quality-scan quality-scan alternative quality-scan setup guide what is quality-scan quality-scan vs socket.io quality-scan install socket-dev api tutorial javascript sdk for socket dev comprehensive code review tools 质量扫描 AIエージェント Socket.dev API JavaScript SDK 代码分析 错误识别 逻辑问题 TypeScript JavaScript Updates dependencies to ensure a clean and organized repository Cleans up junk files to prepare for comprehensive quality scans Uses specialized AI agents to identify critical bugs, logic errors, and workflow problems Generates a prioritized report with actionable improvement tasks Supports TypeScript for robust and maintainable code quality-scan is a JavaScript SDK for Socket.dev API that uses specialized AI agents to systematically analyze code for defects and generate prioritized reports');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('powroom/flins/clack-guidelines', 'community', 'powroom', 'flins', 'powroom/flins', 'clack-guidelines', 34, 7, 50, '2026-02-24T23:17:13Z', '2026-03-06T06:38:12.516Z', '0f0a50d4d70e0e8fc6b092d73383eab6166f32113c377bb53ff4ea76777bd84c', '{"id":"powroom/flins/clack-guidelines","name":"clack-guidelines","description":{"en":"The clack-guidelines skill provides guidance for building interactive command-line interfaces using Clack, benefiting AI agent developers. It covers common patterns for text input and selections.","zh":"Clack 指南提供了构建交互式命令行界面的指导，包括文本输入、选择、自动完成和进度跟踪等功能","ja":"Clack ガイドラインは、インタラクティブコマンドラインインターフェイスを構築するためのガイダンスを提供し、テキスト入力、選択、自動完了、進度追跡などの機能をカバー","ko":"클랙 가이드라인은 인터랙티브 커맨드라인 인터페이스를 구축하는 방법에 대한 안내를 제공하며 텍스트 입력, 선택, 자동 완성, 진행 추적 등의 기능을 다룹니다","es":"Clack Guidelines es una herramienta para crear interfaces de línea de comandos interactivas para agentes de AI. Permite la creación de aplicaciones de CLI completas.","fr":"Clack Guidelines est un outil pour créer des interfaces de ligne de commande interactives pour les agents d''IA. Il permet de créer des applications de CLI complètes.","de":"Clack Guidelines ist ein Tool zum Erstellen interaktiver Kommandozeilen-Interfaces für KI-Agents. Es ermöglicht die Erstellung vollständiger CLI-Anwendungen.","pt":"Clack-Guidelines é uma habilidade universal para instalar agentes de codificação de AI. Fornece orientação para criar interfaces de linha de comando interativas.","ru":"Clack-Guidelines - это универсальный навык для установки агентов кодирования ИИ. Предоставляет руководство по созданию интерактивных командных интерфейсов.","ar":"Clack-Guidelines هو مهارة شاملة لتثبيت وكلاء ترميز الذكاء الاصطناعي. يوفر إرشادات لإنشاء واجهات سطر الأوامر التفاعلية"},"seo":{"title":{"en":"clack-guidelines: Setup Guide for AI Agents | Interactive...","zh":"Clack 指南：AI 编码代理的交互