INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('powroom/flins/clack-guidelines', 'clack-guidelines', 'powroom', 'flins', 'community', 'clack-guidelines powroom flins community agent agentic-ai ai ai-agents ai-tools The clack-guidelines skill provides guidance for building interactive command-line interfaces using Clack, benefiting AI agent developers. It covers common patterns for text input and selections. Clack 指南提供了构建交互式命令行界面的指导，包括文本输入、选择、自动完成和进度跟踪等功能 Clack ガイドラインは、インタラクティブコマンドラインインターフェイスを構築するためのガイダンスを提供し、テキスト入力、選択、自動完了、進度追跡などの機能をカバー 클랙 가이드라인은 인터랙티브 커맨드라인 인터페이스를 구축하는 방법에 대한 안내를 제공하며 텍스트 입력, 선택, 자동 완성, 진행 추적 등의 기능을 다룹니다 Clack Guidelines es una herramienta para crear interfaces de línea de comandos interactivas para agentes de AI. Permite la creación de aplicaciones de CLI completas. Clack Guidelines est un outil pour créer des interfaces de ligne de commande interactives pour les agents d''IA. Il permet de créer des applications de CLI complètes. Clack Guidelines ist ein Tool zum Erstellen interaktiver Kommandozeilen-Interfaces für KI-Agents. Es ermöglicht die Erstellung vollständiger CLI-Anwendungen. Clack-Guidelines é uma habilidade universal para instalar agentes de codificação de AI. Fornece orientação para criar interfaces de linha de comando interativas. Clack-Guidelines - это универсальный навык для установки агентов кодирования ИИ. Предоставляет руководство по созданию интерактивных командных интерфейсов. Clack-Guidelines هو مهارة شاملة لتثبيت وكلاء ترميز الذكاء الاصطناعي. يوفر إرشادات لإنشاء واجهات سطر الأوامر التفاعلية how to use clack-guidelines clack-guidelines setup guide clack-guidelines alternative clack-guidelines vs agentic-ai install clack-guidelines clack-guidelines for AI agents building interactive CLI applications what is clack-guidelines clack-guidelines install npm clack-guidelines tutorial Clack 指南 AI 编码代理 交互式命令行界面 文本输入 选择 自动完成 进度跟踪 CLI 应用程序 npm 安装 Installs @clack/prompts via npm for interactive CLI applications Supports text input with await text({ message: }) syntax Handles selections and autocomplete for user input Enables progress tracking and streaming output for CLI applications Allows creation of complete interactive CLI applications using Clack clack-guidelines is a universal skill installer for AI coding agents, providing guidance for building beautiful interactive command-line interfaces using Clack.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RtlZeroMemory/Zireael/zireael-header-layering', 'community', 'RtlZeroMemory', 'Zireael', 'RtlZeroMemory/Zireael', 'zireael-header-layering', 34, 3, 50, '2026-02-27T12:38:19Z', '2026-03-06T06:38:21.449Z', '4176485c4f113312650daa15872d4510f43b23c7fad302297f119fb33e4ee4a5', '{"id":"RtlZeroMemory/Zireael/zireael-header-layering","name":"zireael-header-layering","description":{"en":"zireael-header-layering is a C-based terminal UI core engine that enables deterministic rendering. It benefits developers working with cross-platform, performance-oriented applications.","zh":"Zireael Header Layering是一个eterministic的终端UI核心引擎，使用C语言和FFI/ABI后端，适用于Rezi","ja":"Zireael Header Layeringは、C言語とFFI/ABIバックエンドを使用した決定論的なターミナルUIコアエンジンです。Rezi用に設計されています","ko":"Zireael Header Layering은 C 언어와 FFI/ABI 백엔드를 사용하는 결정론적인 터미널 UI 코어 엔진입니다. Rezi용으로 설계되었습니다","es":"zireael-header-layering es un núcleo de UI determinista en C con FFI/ABI para Rezi, que permite la creación de interfaces de usuario cross-platform","fr":"zireael-header-layering est un noyau de UI déterministe en C avec FFI/ABI pour Rezi, qui permet la création d''interfaces utilisateur cross-platform","de":"zireael-header-layering ist ein deterministischer UI-Kern in C mit FFI/ABI für Rezi, der die Erstellung von cross-plattformfähigen Benutzeroberflächen ermöglicht","pt":"O zireael-header-layering é um núcleo de interface de usuário terminal determinístico em C, com suporte a FFI/ABI para Rezi, projetado para melhorar a performance e a compatibilidade cruzada.","ru":"zireael-header-layering - детерминированный терминальный UI-ядер в C, с поддержкой FFI/ABI для Rezi, предназначенный для повышения производительности и кроссплатформенной совместимости","ar":"أداة zireael-header-layering هي نواة واجهة المستخدم الطرفية القطعية بلغة C، مع دعم FFI/ABI من أجل Rezi، مصممة لتحسين الأداء والتوافق المتبادل"},"seo":{"title":{"en":"zireael-header-layering: Deterministic Terminal UI Core E...","zh":"Zireael Header Layering Setup Guide - AIエージェント终端UI核心引擎","ja":"Zireael Header Layering Best Practices - AIエージェント用C言語UIコア...","ko":"Zireael Header Layering Configuration - AI 도구 터미널 UI 코어 엔진","es":"Guía de configuración de zireael-header-layering para UI ...","fr":"Guide de mise en place de zireael-header-layering pour UI...","de":"Einrichtungsleitfaden für zireael-header-layering zur det...","pt":"Guia de Configuração do zireael-header-layering para Dese...","ru":"ИИ Агент zireael-header-layering: Руководство по Настройке","ar":"إعداد أداة zireael-header-layering للتنمية: دليل الشروحات"},"description":{"en":"Unlock efficient terminal UI development with zireael-header-layering. Learn how to leverage its deterministic core engine and refactor includes for seamless...","zh":"了解Zireael Header Layering的技术细节和使用场景，实现高性能的终端UI核心引擎","ja":"Zireael Header Layeringの技術的な詳細と使用シーンを学び、高パフォーマンスのターミナルUIコアエンジンを実現しましょう","ko":"Zireael Header Layering의 기술적인 세부 정보와 사용 사례를 알아보고, 고성능 터미널 UI 코어 엔진을 구현하세요","es":"Aprende a utilizar zireael-header-layering para crear interfaces de usuario deterministas y cross-platform con C y FFI/ABI","fr":"Découvrez comment utiliser zireael-header-layering pour créer des interfaces utilisateur déterministes et cross-platform avec C et FFI/ABI","de":"Erfahren Sie, wie Sie zireael-header-layering verwenden können, um deterministische und cross-plattformfähige Benutzeroberflächen mit C und FFI/ABI zu erstellen","pt":"Aprenda a utilizar o zireael-header-layering para melhorar a performance e a compatibilidade cruzada dos seus projetos em C com FFI/ABI","ru":"Узнайте, как использовать zireael-header-layering для повышения производительности и кроссплатформенной совместимости ваших проектов на C с FFI/ABI","ar":"تعرف على كيفية استخدام أداة zireael-header-layering لتحسين الأداء والتوافق المتبادل للمشاريع المبرمجة بلغة C مع FFI/ABI"},"definition":{"en":"zireael-header-layering is a deterministic terminal UI core engine in C, utilizing FFI/ABI backend for Rezi, designed for efficient and cross-platform development.","zh":"Zireael Header Layering是一种用于构建高性能终端UI的技术，使用C语言和FFI/ABI后端","ja":"Zireael Header Layeringは、高パフォーマンスのターミナルUIを構築するための技術であり、C言語とFFI/ABIバックエンドを使用します","ko":"Zireael Header Layering은 고성능 터미널 UI를 구축하기 위한 기술로, C 언어와 FFI/ABI 백엔드를 사용합니다","es":"zireael-header-layering es un motor de UI determinista que utiliza C y FFI/ABI para crear interfaces de usuario cross-platform","fr":"zireael-header-layering est un moteur de UI déterministe qui utilise C et FFI/ABI pour créer des interfaces utilisateur cross-platform","de":"zireael-header-layering ist ein deterministischer UI-Motor, der C und FFI/ABI verwendet, um cross-plattformfähige Benutzeroberflächen zu erstellen","pt":"O zireael-header-layering é um motor de interface de usuário terminal em C que fornece uma camada de abstração para FFI/ABI","ru":"zireael-header-layering - это терминальный UI-движок на C, предоставляющий уровень абстракции для FFI/ABI","ar":"أداة zireael-header-layering هي محرك واجهة المستخدم الطرفية بلغة C التي توفر مستوى تجريد ل FFI/ABI"},"features":{"en":["Enforces include layering rules for OS-header-free and internal dependency management","Supports POSIX and ANSI standards for cross-platform compatibility","Utilizes src/util, src/unicode, and src/core for modular and efficient code organization","Follows #ifdef policy and stdlib usage constraints as outlined in LIBC_POLICY.md","Refactors includes and manages circular dependencies for optimized performance","Complies with REPO_LAYOUT.md for dependency direction and management"],"zh":["使用C语言和FFI/ABI后端","支持跨平台开发","实现确定性的终端UI核心引擎","遵循POSIX和ANSI标准","支持Unicode字符集","与Golang和TypeScript集成"],"ja":["C言語とFFI/ABIバックエンドを使用","クロスプラットフォーム開発をサポート","決定論的なターミナルUIコアエンジンを実現","POSIXとANSIの標準に準拠","Unicode文字セットをサポート","GolangとTypeScriptとの統合"],"ko":["C 언어와 FFI/ABI 백엔드를 사용","크로스 플랫폼 개발을 지원","결정론적인 터미널 UI 코어 엔진을 구현","POSIX와 ANSI의 표준을 준수","유니코드 문자 집합을 지원","Golang과 TypeScriptとの 통합"],"es":["Compatibilidad con C y FFI/ABI","Soporte para interfaces de usuario deterministas","Capacidad de creación de interfaces de usuario cross-platform","Seguimiento de las reglas de capas de inclusión","Compatibilidad con POSIX y ANSI","Soporte para Unicode"],"fr":["Compatibilité avec C et FFI/ABI","Prise en charge d''interfaces utilisateur déterministes","Capacité de création d''interfaces utilisateur cross-platform","Suivi des règles de couches d''inclusion","Compatibilité avec POSIX et ANSI","Prise en charge de Unicode"],"de":["Kompatibilität mit C und FFI/ABI","Unterstützung für deterministische Benutzeroberflächen","Fähigkeit zur Erstellung von cross-plattformfähigen Benutzeroberflächen","Einhaltung der Regeln für die Einbindung von Header-Dateien","Kompatibilität mit POSIX und ANSI","Unterstützung für Unicode"],"pt":["Suporte a FFI/ABI para Rezi","Núcleo de interface de usuário terminal determinístico em C","Compatibilidade cruzada com POSIX e Windows","Otimização de desempenho com tecnologia de renderização de terminal","Suporte a Unicode e ANSI","Integração com GoLang e TypeScript"],"ru":["Поддержка FFI/ABI для Rezi","Детерминированный терминальный UI-ядер на C","Кроссплатформенная совместимость с POSIX и Windows","Оптимизация производительности с технологией рендеринга терминала","Поддержка Unicode и ANSI","Интеграция с GoLang и TypeScript"],"ar":["دعم FFI/ABI ل Rezi","نواة واجهة المستخدم الطرفية القطعية بلغة C","التوافق المتبادل مع POSIX و Windows","تحسين الأداء مع تكنولوجيا عرض الطرفية","دعم Unicode و ANSI","التكامل مع GoLang و TypeScript"]},"keywords":{"en":["zireael-header-layering setup guide","deterministic terminal UI development","C-based core engine for Rezi","cross-platform development with POSIX","how to use zireael-header-layering with ANSI","zireael-header-layering vs other terminal UI engines","zireael-header-layering install for Windows and Unix","refactoring includes with zireael-header-layering","performance optimization with zireael-header-layering","zireael-header-layering documentation and tutorials"],"zh":["Zireael Header Layering","AIエージェント","终端UI核心引擎","C语言","FFI/ABI","Rezi","跨平台开发","POSIX","ANSI","Unicode"],"ja":["Zireael Header Layering","AIエージェント","ターミナルUIコアエンジン","C言語","FFI/ABI","Rezi","クロスプラットフォーム開発","POSIX","ANSI","Unicode"],"ko":["Zireael Header Layering","AI 도구","터미널 UI 코어 엔진","C 언어","FFI/ABI","Rezi","크로스 플랫폼 개발","POSIX","ANSI","유니코드"],"es":["zireael-header-layering","UI determinista","C y FFI/ABI","interfaces de usuario cross-platform","reglas de capas de inclusión","POSIX y ANSI","Unicode","Herramientas de desarrollo de UI","Bibliotecas de UI en C"],"fr":["zireael-header-layering","UI déterministe","C et FFI/ABI","interfaces utilisateur cross-platform","règles de couches d''inclusion","POSIX et ANSI","Unicode","Outils de développement de UI","Bibliothèques de UI en C"],"de":["zireael-header-layering","deterministische Benutzeroberfläche","C und FFI/ABI","cross-plattformfähige Benutzeroberflächen","Regeln für die Einbindung von Header-Dateien","POSIX und ANSI","Unicode","Entwicklertools für Benutzeroberflächen","Bibliotheken für Benutzeroberflächen in C"],"pt":["zireael-header-layering","desenvolvimento em C","FFI/ABI","Rezi","interface de usuário terminal","compatibilidade cruzada","performance","renderização de terminal","Unicode","ANSI","GoLang","TypeScript"],"ru":["zireael-header-layering","разработка на C","FFI/ABI","Rezi","терминальный UI","кроссплатформенная совместимость","производительность","рендеринг терминала","Unicode","ANSI","GoLang","TypeScript"],"ar":["zireael-header-layering","البرمجة بلغة C","FFI/ABI","Rezi","واجهة المستخدم الطرفية","التوافق المتبادل","الأداء","عرض الطرفية","Unicode","ANSI","GoLang","TypeScript"]}},"owner":"RtlZeroMemory","repo":"Zireael","repoPath":"RtlZeroMemory/Zireael","stars":34,"forks":3,"updatedAt":"2026-02-27T12:38:19Z","topics":["abi","ansi","c","cross-platform","deterministic","ffi","golang","performance","posix","renderer","terminal","tui","typescript","unicode","windows","zireael-ui"],"category":"community","skillMd":{"name":"zireael-header-layering","description":"Prevent include cycles and platform-boundary leaks by enforcing header layering.","bodyPreview":"## When to use\n\nUse this skill when:\n\n- adding new headers or refactoring includes\n- encountering circular dependencies\n- tightening the platform boundary\n\n## Source of truth\n\n- `docs/REPO_LAYOUT.md` — dependency direction and `#ifdef` policy\n- `docs/LIBC_POLICY.md` — stdlib usage constraints\n\n## Include layering rules (must follow)\n\n```\nsrc/util/      → OS-header-free, no internal deps\n      ↑\nsrc/unicode/   → may include util; OS-header-free\n      ↑\nsrc/core/      → may include util, unicode,","body":"## When to use\n\nUse this skill when:\n\n- adding new headers or refactoring includes\n- encountering circular dependencies\n- tightening the platform boundary\n\n## Source of truth\n\n- `docs/REPO_LAYOUT.md` — dependency direction and `#ifdef` policy\n- `docs/LIBC_POLICY.md` — stdlib usage constraints\n\n## Include layering rules (must follow)\n\n```\nsrc/util/      → OS-header-free, no internal deps\n      ↑\nsrc/unicode/   → may include util; OS-header-free\n      ↑\nsrc/core/      → may include util, unicode, platform interface; OS-header-free\n      ↑\nsrc/platform/  → implements zr_platform.h; may include OS headers\n```\n\n## Specific rules\n\n- `src/util/**` MUST be OS-header-free\n- `src/unicode/**` may include `src/util/**` only; MUST be OS-header-free\n- `src/core/**` may include util, unicode, and `zr_platform.h`; MUST be OS-header-free\n- `src/platform/**` implements `zr_platform.h`; may include OS headers\n\n## Best practices\n\n- Prefer forward declarations in headers to avoid deep include trees\n- Keep ABI-visible headers POD-only (fixed-width ints)\n- Ensure no OS headers are transitively included by core/unicode/util\n- Platform `#ifdef` exists only in platform backends and selection TU\n\n## Checklist\n\n- [ ] No OS headers in core/unicode/util\n- [ ] No circular includes\n- [ ] Forward declarations where possible\n- [ ] ABI headers use fixed-width types only\n"},"lastSynced":"2026-03-06T06:38:21.449Z","agentAnalysis":{"suitability":{"en":"Perfect for C-based Terminal UI Agents needing deterministic rendering and cross-platform compatibility.","zh":"适合需要确定性渲染和跨平台兼容性的基于C的终端UI代理。","ja":"CベースのターミナルUIエージェントが確定的レンダリングとクロスプラットフォームの互換性を必要とする場合に適しています。","ko":"결정적 렌더링과 크로스 플랫폼 호환성을 필요로 하는 C 기반 터미널 UI 에이전트에 적합합니다.","es":"Perfecto para agentes de interfaz de usuario de terminal basados en C que necesitan renderizado determinista y compatibilidad entre plataformas.","fr":"Parfait pour les agents d''interface utilisateur de terminal basés sur C nécessitant un rendu déterministe et une compatibilité multi-plateforme.","de":"Perfekt für C-basierte Terminal-UI-Agents, die deterministisches Rendering und Cross-Platform-Kompatibilität benötigen.","pt":"Perfeito para agentes de interface de terminal baseados em C que precisam de renderização determinística e compatibilidade entre plataformas.","ru":"Идеально подходит для агентов интерфейса терминала на основе C, требующих определённой отрисовки и совместимости между платформами.","ar":"مثالي لوكلاء واجهة الطرفية المعتمدة على C التي تحتاج إلى تقديم محدد وتوافق عبر منصات."},"recommendation":{"en":"Empowers agents to manage complex header dependencies and refactor includes efficiently, utilizing OS-header-free layers and stdlib usage constraints as defined in LIBC_POLICY.md, while enforcing include layering rules for util, unicode, and core components.","zh":"赋予代理管理复杂的头文件依赖并高效地重构包含，利用操作系统头文件免费层和stdlib使用约束，如LIBC_POLICY.md中定义的，同时强制执行util、unicode和核心组件的包含层次规则。","ja":"エージェントが複雑なヘッダ依存関係を管理し、インクルードを効率的にリファクタリングできるようにし、OSヘッダーフリーレイヤーとstdlibの使用制約を使用し、LIBC_POLICY.mdで定義されたように、util、unicode、コアコンポーネントのインクルード階層ルールを適用します。","ko":"에이전트가 복잡한 헤더 종속성을 관리하고 포함을 효율적으로 리팩토링 할 수 있도록 하며 OS 헤더가 없는 레이어와 stdlib 사용 제약을 사용하며 LIBC_POLICY.md에서 정의한 대로 유틸, 유니코드 및 핵심 구성 요소의 포함 계층 규칙을 적용합니다.","es":"Permite a los agentes gestionar complejas dependencias de cabecera y refactorizar includes de manera eficiente, utilizando capas libres de cabeceras del sistema operativo y restricciones de uso de stdlib según lo definido en LIBC_POLICY.md, mientras que se aplican reglas de capas de inclusión para componentes de util, unicode y core.","fr":"Permet aux agents de gérer des dépendances d''en-tête complexes et de refactoriser les includes de manière efficace, en utilisant des couches libres d''en-tête du système d''exploitation et des contraintes d''utilisation de stdlib telles que définies dans LIBC_POLICY.md, tout en imposant des règles de superposition d''inclusion pour les composants util, unicode et core.","de":"Ermöglich es Agents, komplexe Header-Abhängigkeiten zu verwalten und Includes effizient umzustrukturieren, indem OS-Header-freie Schichten und stdlib-Nutzungsbeschränkungen gemäß den Definitionen in LIBC_POLICY.md verwendet werden, während Include-Schichtregeln für util-, unicode- und core-Komponenten durchgesetzt werden.","pt":"Habilita os agentes a gerenciar dependências de cabeçalho complexas e reestruturar inclusões de forma eficiente, utilizando camadas livres de cabeçalhos do sistema e restrições de uso de stdlib conforme definido em LIBC_POLICY.md, ao mesmo tempo em que impõe regras de estratificação de inclusões para componentes de util, unicode e core.","ru":"Наделяет агентов возможностью управлять сложными зависимостями заголовков и перерабатывать включения эффективно, используя слои, свободные от заголовков операционной системы, и ограничения использования stdlib, определенные в LIBC_POLICY.md, а также обеспечивает соблюдение правил слоистости включений для компонентов util, unicode и core.","ar":"تمكّن الوكلاء من إدارة تبعيات رأس معقدة وإعادة هيكلة الإدراج بفعالية، باستخدام طبقات خالية من رؤوس النظام وقيود استخدام stdlib كما هو محدد في LIBC_POLICY.md، وفي الوقت نفسه تفرض قواعد طبقات الإدراج لمكونات util و unicode و core."},"useCases":{"en":["Refactoring includes to avoid circular dependencies","Tightening platform boundaries for performance-oriented applications","Adding new headers while maintaining deterministic rendering"],"zh":["重构包含以避免循环依赖","为性能导向的应用程序紧化平台边界","在保持确定性渲染的同时添加新头文件"],"ja":["循環依存を避けるためにインクルードをリファクタリングする","パフォーマンス指向のアプリケーションのプラットフォームの境界を締める","決定的なレンダリングを維持しながら新しいヘッダーを追加する"],"ko":["순환 종속성을 피하기 위해 포함을 리팩토링합니다.","성능 지향 애플리케이션의 플랫폼 경계를 조정합니다.","결정적 렌더링을 유지하면서 새로운 헤더를 추가합니다."],"es":["Reorganizar includes para evitar dependencias circulares","Establecer límites de plataforma para aplicaciones orientadas al rendimiento","Agregar nuevos encabezados manteniendo el renderizado determinista"],"fr":["Réorganiser les includes pour éviter les dépendances circulaires","Définir les limites de plate-forme pour les applications orientées performances","Ajouter de nouveaux en-têtes tout en maintenant un rendu déterministe"],"de":["Umschreiben von Includes, um zirkuläre Abhängigkeiten zu vermeiden","Festlegen von Plattformgrenzen für leistungsorientierte Anwendungen","Hinzufügen neuer Header unter Beibehaltung des deterministischen Renderings"],"pt":["Reestruturar inclusões para evitar dependências circulares","Ajustar limites de plataforma para aplicações orientadas ao desempenho","Adicionar novos cabeçalhos mantendo a renderização determinística"],"ru":["Перестроить включения, чтобы избежать круговых зависимостей","Затянуть границы платформы для приложений, ориентированных на производительность","Добавить новые заголовки, сохраняя определённую отрисовку"],"ar":["إعادة هيكلة الإدراج لتجنب التبعيات الدائرية","ضبط حدود المنصة لبرامج توجيه الأداء","إضافة رؤوس جديدة مع الحفاظ على تقديم محدد"]},"limitations":{"en":["Requires adherence to include layering rules","C-based terminal UI core engine only","Compliance with dependency direction and #ifdef policy as outlined in REPO_LAYOUT.md"],"zh":["需要遵守包含层次规则","仅限C基于终端UI核心引擎","遵守依赖方向和#ifdef策略，如REPO_LAYOUT.md中概述的"],"ja":["インクルード階層ルールに従う必要がある","CベースのターミナルUIコアエンジンのみ","依存方向と#ifdefポリシーに準拠すること、REPO_LAYOUT.mdに概説されているように"],"ko":["包含 계층 규칙을 준수해야 함","C 기반 터미널 UI 핵심 엔진만","종속성 방향 및 #ifdef 정책을 준수해야 함, REPO_LAYOUT.md에 요약된 대로"],"es":["Requiere adherencia a las reglas de capas de inclusión","Motor de interfaz de usuario de terminal basado en C solo","Cumplimiento de la dirección de dependencia y la política de #ifdef según lo descrito en REPO_LAYOUT.md"],"fr":["Nécessite l''adhésion aux règles de superposition d''inclusion","Moteur d''interface utilisateur de terminal basé sur C uniquement","Conformité à la direction de dépendance et à la politique de #ifdef telle que décrite dans REPO_LAYOUT.md"],"de":["Erfordert die Einhaltung von Include-Schichtregeln","Nur C-basiertes Terminal-UI-Core-Engine","Einhaltung der Abhängigkeitsrichtung und der #ifdef-Richtlinie wie in REPO_LAYOUT.md beschrieben"],"pt":["Exige aderência às regras de estratificação de inclusões","Motor de núcleo de interface de terminal baseado em C apenas","Conformidade com a direção de dependência e política #ifdef conforme delineado em REPO_LAYOUT.md"],"ru":["Требует соблюдения правил слоистости включений","Ядро интерфейса терминала только на основе C","Соблюдение направления зависимости и политики #ifdef, изложенной в REPO_LAYOUT.md"],"ar":["يتطلب الالتزام بقواعد طبقات الإدراج","محرك 핵ي لواجهة الطرفية المعتمدة على C فقط","الامتثال لتوجيه التبعية وسياسة #ifdef كما هو محدد في REPO_LAYOUT.md"]},"version":4},"contentHash":"4176485c4f113312650daa15872d4510f43b23c7fad302297f119fb33e4ee4a5","qualityScore":50}');
