INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RtlZeroMemory/Zireael/zireael-header-layering', 'zireael-header-layering', 'RtlZeroMemory', 'Zireael', 'community', 'zireael-header-layering RtlZeroMemory Zireael community abi ansi c cross-platform deterministic ffi golang performance posix renderer terminal tui typescript unicode windows zireael-ui zireael-header-layering is a C-based terminal UI core engine that enables deterministic rendering. It benefits developers working with cross-platform, performance-oriented applications. Zireael Header Layering是一个eterministic的终端UI核心引擎，使用C语言和FFI/ABI后端，适用于Rezi Zireael Header Layeringは、C言語とFFI/ABIバックエンドを使用した決定論的なターミナルUIコアエンジンです。Rezi用に設計されています Zireael Header Layering은 C 언어와 FFI/ABI 백엔드를 사용하는 결정론적인 터미널 UI 코어 엔진입니다. Rezi용으로 설계되었습니다 zireael-header-layering es un núcleo de UI determinista en C con FFI/ABI para Rezi, que permite la creación de interfaces de usuario cross-platform zireael-header-layering est un noyau de UI déterministe en C avec FFI/ABI pour Rezi, qui permet la création d''interfaces utilisateur cross-platform zireael-header-layering ist ein deterministischer UI-Kern in C mit FFI/ABI für Rezi, der die Erstellung von cross-plattformfähigen Benutzeroberflächen ermöglicht O zireael-header-layering é um núcleo de interface de usuário terminal determinístico em C, com suporte a FFI/ABI para Rezi, projetado para melhorar a performance e a compatibilidade cruzada. zireael-header-layering - детерминированный терминальный UI-ядер в C, с поддержкой FFI/ABI для Rezi, предназначенный для повышения производительности и кроссплатформенной совместимости أداة zireael-header-layering هي نواة واجهة المستخدم الطرفية القطعية بلغة C، مع دعم FFI/ABI من أجل Rezi، مصممة لتحسين الأداء والتوافق المتبادل zireael-header-layering setup guide deterministic terminal UI development C-based core engine for Rezi cross-platform development with POSIX how to use zireael-header-layering with ANSI zireael-header-layering vs other terminal UI engines zireael-header-layering install for Windows and Unix refactoring includes with zireael-header-layering performance optimization with zireael-header-layering zireael-header-layering documentation and tutorials Zireael Header Layering AIエージェント 终端UI核心引擎 C语言 FFI/ABI Rezi 跨平台开发 POSIX ANSI Unicode Enforces include layering rules for OS-header-free and internal dependency management Supports POSIX and ANSI standards for cross-platform compatibility Utilizes src/util, src/unicode, and src/core for modular and efficient code organization Follows #ifdef policy and stdlib usage constraints as outlined in LIBC_POLICY.md Refactors includes and manages circular dependencies for optimized performance Complies with REPO_LAYOUT.md for dependency direction and management zireael-header-layering is a deterministic terminal UI core engine in C, utilizing FFI/ABI backend for Rezi, designed for efficient and cross-platform development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aicodingstack/aicodingstack.io/i18n', 'community', 'aicodingstack', 'aicodingstack.io', 'aicodingstack/aicodingstack.io', 'i18n', 28, 7, 50, '2026-02-04T01:02:14Z', '2026-03-06T06:39:22.408Z', 'd46e075d29f64514056a20d1b66ddc46a7f0b325d23601db9a9455bedd197087', '{"id":"aicodingstack/aicodingstack.io/i18n","name":"i18n","description":{"en":"The i18n skill helps developers manage multilingual content in the translations/ directory, using next-intl for internationalization with JSON message files.","zh":"i18n 技能提供多语言内容管理工具，使用 next-intl 实现国际化","ja":"i18n スキルは多言語コンテンツ管理ツールを提供し、next-intl を使用して国際化を実現","ko":"i18n 기능은 다국어 콘텐츠 관리 도구를 제공하며 next-intl을 사용하여 국제화를 구현","es":"El skill i18n gestiona contenido multilingüe en el directorio translations/ con next-intl","fr":"Le skill i18n gère le contenu multilingue dans le répertoire translations/ avec next-intl","de":"Der i18n-Skill verwaltet mehrsprachigen Inhalt im Verzeichnis translations/ mit next-intl","pt":"O i18n é uma habilidade que gerencia conteúdo multilíngue no diretório translations/.","ru":"I18n — это умение, которое управляет многоязычным контентом в директории translations/.","ar":"i18n هو مهارة لإدارة المحتوى المتعدد اللغات في الدليل translations/."},"seo":{"title":{"en":"i18n: Internationalization Setup Guide for AI Agents","zh":"i18n 设置指南 - AI Coding Stack 多语言支持","ja":"i18n セットアップガイド - AIエージェントによる多言語対応","ko":"i18n 설정 가이드 - AI 코딩 스택의 다국어 지원","es":"Guía de configuración de i18n para Agentes de Inteligenci...","fr":"Guide de configuration i18n pour les Outils d''Intelligenc...","de":"i18n-Setup-Leitfaden für KI-Entwickler","pt":"Guia de Configuração i18n para Ferramentas de Desenvolvim...","ru":"Настройка i18n для ИИ Агентов: Руководство по локализации","ar":"دليل إعداد i18n لأدوات التطوير الإصطناعي"},"description":{"en":"Discover how to manage multilingual content with i18n. Learn to synchronize language files and assist with translations. Get started now!","zh":"使用 i18n 技能管理多语言内容，实现语言文件同步和翻译辅助","ja":"i18n スキルを使用して多言語コンテンツを管理し、言語ファイルの同期と翻訳支援を実現","ko":"i18n 기능을 사용하여 다국어 콘텐츠를 관리하고 언어 파일 동기화 및 번역 지원을 구현","es":"Aprende a gestionar contenido multilingüe con i18n y next-intl en tu proyecto de Inteligencia Artificial","fr":"Découvrez comment gérer le contenu multilingue avec i18n et next-intl dans votre projet d''Intelligence Artificielle","de":"Erfahren Sie, wie Sie mehrsprachigen Inhalt mit i18n und next-intl in Ihrem KI-Projekt verwalten","pt":"Aprenda a gerenciar conteúdo multilíngue com i18n e next-intl para Ferramentas de Desenvolvimento de IA","ru":"Узнайте, как управлять многоязычным контентом с помощью i18n и next-intl для ИИ Агентов","ar":"تعرف على كيفية إدارة المحتوى المتعدد اللغات باستخدام i18n و next-intl لأدوات التطوير الإصطناعي"},"definition":{"en":"i18n is a skill that provides tools to synchronize language files with the English reference and assist with translations in the translations/ directory.","zh":"i18n 是一种多语言内容管理技能，用于同步语言文件和辅助翻译","ja":"i18n は多言語コンテンツ管理スキルで、言語ファイルの同期と翻訳支援に使用","ko":"i18n은 다국어 콘텐츠 관리 기능으로 언어 파일 동기화 및 번역 지원에 사용","es":"i18n es una habilidad para gestionar contenido multilingüe en proyectos de Inteligencia Artificial","fr":"i18n est une compétence pour gérer le contenu multilingue dans les projets d''Intelligence Artificielle","de":"i18n ist eine Fähigkeit zur Verwaltung von mehrsprachigem Inhalt in KI-Projekten","pt":"O que é i18n? É uma habilidade para gerenciar conteúdo multilíngue em aplicações de IA.","ru":"Что такое i18n? Это умение для управления многоязычным контентом в приложениях ИИ.","ar":"ما هي i18n؟ هي مهارة لإدارة المحتوى المتعدد اللغات في تطبيقات الإصطناعي."},"features":{"en":["Uses next-intl for internationalization with JSON message files","Organizes language files in the translations/ directory","Synchronizes language files with the English reference","Assists with translations using the translations/ directory structure","Supports multiple language files, including en/, for multilingual content management","Utilizes a directory structure with index.ts and JSON files for message management"],"zh":["使用 next-intl 实现国际化","语言文件组织在 translations/ 目录下","支持多语言内容管理和同步","辅助翻译功能","使用 JSON 消息文件"],"ja":["next-intl を使用して国際化を実現","言語ファイルは translations/ ディレクトリに組織","多言語コンテンツ管理と同期をサポート","翻訳支援機能","JSON メッセージファイルを使用"],"ko":["next-intl을 사용하여 국제화를 구현","언어 파일은 translations/ 디렉토리에 구성","다국어 콘텐츠 관리 및 동기화를 지원","번역 지원 기능","JSON 메시지 파일 사용"],"es":["Gestión de archivos de idioma con next-intl","Sincronización de archivos de idioma con el inglés como referencia","Organización de archivos de idioma en el directorio translations/","Compatibilidad con formatos JSON para mensajes","Generación de archivos de idioma para es, fr y de","Integración con la línea de comandos CLI"],"fr":["Gestion des fichiers de langue avec next-intl","Synchronisation des fichiers de langue avec l''anglais comme référence","Organisation des fichiers de langue dans le répertoire translations/","Compatibilité avec les formats JSON pour les messages","Génération de fichiers de langue pour es, fr et de","Intégration avec la ligne de commande CLI"],"de":["Verwaltung von Sprachdateien mit next-intl","Synchronisation von Sprachdateien mit Englisch als Referenz","Organisation von Sprachdateien im Verzeichnis translations/","Unterstützung von JSON-Formaten für Nachrichten","Erzeugung von Sprachdateien für es, fr und de","Integration mit der Kommandozeile CLI"],"pt":["Suporte a next-intl para internacionalização","Organização de arquivos de tradução em JSON","Sincronização de arquivos de linguagem com o inglês como referência","Geração de traduções para pt, ru e ar","Integração com o diretório translations/"],"ru":["Поддержка next-intl для международализации","Организация файлов перевода в JSON","Синхронизация файлов языка с английским как справочным","Генерация переводов для pt, ru и ar","Интеграция с директорий translations/"],"ar":["دعم next-intl للتوطين","تنظيم ملفات الترجمة في JSON","مزامنة ملفات اللغة مع الإنجليزية كمرجع","توليد الترجمات لل pt و ru و ar","التكامل مع الدليل translations/"]},"keywords":{"en":["how to use i18n","what is i18n","i18n setup guide","i18n internationalization","next-intl tutorial","JSON message files","multilingual content management","i18n install","i18n vs gettext"],"zh":["i18n","多语言内容管理","next-intl","国际化","语言文件同步","翻译辅助","AI Coding Stack","AIエージェント"],"ja":["i18n","多言語コンテンツ管理","next-intl","国際化","言語ファイル同期","翻訳支援","AIエージェント","AI Coding Stack"],"ko":["i18n","다국어 콘텐츠 관리","next-intl","국제화","언어 파일 동기화","번역 지원","AI 코딩 스택","AI 에이전트"],"es":["i18n para agentes de inteligencia artificial","intl en proyectos de ia","gestión de contenido multilingüe","next-intl en español","traducciones en proyectos de inteligencia artificial","desarrollo de software con i18n","herramientas de inteligencia artificial para desarrolladores","i18n y cli","intl y json"],"fr":["i18n pour les outils d''intelligence artificielle","intl dans les projets d''ia","gestion de contenu multilingue","next-intl en français","traductions dans les projets d''intelligence artificielle","développement de logiciels avec i18n","outils d''intelligence artificielle pour les développeurs","i18n et cli","intl et json"],"de":["i18n für ki-entwickler","intl in ki-projekten","verwaltung von mehrsprachigem inhalt","next-intl auf deutsch","übersetzungen in ki-projekten","softwareentwicklung mit i18n","ki-tools für entwickler","i18n und cli","intl und json"],"pt":["i18n para desenvolvimento de IA","ferramentas de desenvolvimento de IA","next-intl","internacionalização de aplicações","gerenciamento de conteúdo multilíngue","traduções para pt","traduções para ru","traduções para ar"],"ru":["i18n для ИИ Агентов","инструменты разработки ИИ","next-intl","интернационализация приложений","управление многоязычным контентом","переводы на pt","переводы на ru","переводы на ar"],"ar":["i18n لأدوات التطوير الإصطناعي","أدوات تطوير الإصطناعي","next-intl","توطين التطبيقات","إدارة المحتوى المتعدد اللغات","ترجمات لل pt","ترجمات لل ru","ترجمات لل ar"]}},"owner":"aicodingstack","repo":"aicodingstack.io","repoPath":"aicodingstack/aicodingstack.io","stars":28,"forks":7,"updatedAt":"2026-02-04T01:02:14Z","topics":["ai","ai-development","cli","coding-tools","developer-tools","extension","ide","llm","model-provider","models"],"category":"community","skillMd":{"name":"i18n","description":"Internationalization management tool for syncing and translating language files","bodyPreview":"# I18n Management Skill\n\nManage multilingual content in the `translations/` directory. This skill provides tools to synchronize language files with the English reference and assist with translations.\n\n## Overview\n\nThis project uses `next-intl` for internationalization with JSON message files organized in `translations/`:\n\n```\ntranslations/\n├── en/                    # English (source of truth)\n│   ├── index.ts           # Main export file\n│   ├── shared.json\n│   ├── components.json\n│   └── pages","body":"# I18n Management Skill\n\nManage multilingual content in the `translations/` directory. This skill provides tools to synchronize language files with the English reference and assist with translations.\n\n## Overview\n\nThis project uses `next-intl` for internationalization with JSON message files organized in `translations/`:\n\n```\ntranslations/\n├── en/                    # English (source of truth)\n│   ├── index.ts           # Main export file\n│   ├── shared.json\n│   ├── components.json\n│   └── pages/\n│       ├── home.json\n│       ├── manifesto.json\n│       ├── docs.json\n│       ├── articles.json\n│       ├── curated-collections.json\n│       ├── stacks.json\n│       ├── comparison.json\n│       ├── landscape.json\n│       ├── open-source-rank.json\n│       └── search.json\n├── de/                    # German\n├── es/                    # Spanish\n├── fr/                    # French\n├── id/                    # Indonesian\n├── ja/                    # Japanese\n├── ko/                    # Korean\n├── pt/                    # Portuguese\n├── ru/                    # Russian\n├── tr/                    # Turkish\n├── zh-Hans/               # Simplified Chinese\n└── zh-Hant/               # Traditional Chinese\n```\n\n**Important:** Each locale must maintain the exact same file structure and JSON key order as `en/`.\n\n## I18n Architecture\n\nThe project has **two separate internationalization systems** that share the same 12 locale configuration:\n\n### 1. UI Translation System (next-intl)\n- **Purpose:** Translates static UI strings (buttons, labels, page content, etc.)\n- **Location:** `translations/{locale}/*.json`\n- **Usage:** Via `useTranslations()` hook or `getTranslations()` server function\n- **Managed by:** This skill''s sync and translate commands\n\n### 2. Manifest Translation System\n- **Purpose:** Translates manifest data (IDEs, CLIs, models, providers, etc.)\n- **Location:** `manifests/**/*.json` (in each manifest file''s `translations` field)\n- **Usage:** Via `localizeManifestItem()` and `localizeManifestItems()` functions\n- **Managed by:** Manual editing of manifest files or manifest automation tools\n\n**This skill manages only the UI Translation System.** For manifest translations, edit the manifest JSON files directly or use the manifest-automation skill.\n\n## Enabled Locales\n\nCurrently enabled locales in `src/i18n/config.ts`:\n- `en` - English (source of truth)\n- `de` - Deutsch (German)\n- `es` - Español (Spanish)\n- `fr` - Français (French)\n- `id` - Bahasa Indonesia (Indonesian)\n- `ja` - 日本語 (Japanese)\n- `ko` - 한국어 (Korean)\n- `pt` - Português (Portuguese)\n- `ru` - Русский (Russian)\n- `tr` - Türkçe (Turkish)\n- `zh-Hans` - 简体中文 (Simplified Chinese)\n- `zh-Hant` - 繁體中文 (Traditional Chinese)\n\nAll 12 locales are fully enabled and must be maintained in sync.\n\n## Subcommands\n\n### `sync`\n\nSynchronize all enabled locale directories with `en/` as the source of truth.\n\n**What it does:**\n\n- Scans all locale directories in `translations/` that are enabled in config\n- Compares each JSON file''s keys with the corresponding English file\n- **Adds missing keys** with English text as placeholder (needs translation)\n- **Removes extra keys** not present in English files\n- **Preserves JSON structure, key order, and formatting** (2-space indentation)\n- **Keeps the `index.ts` file structure** for each locale\n\n**Usage:**\n\nWhen you need to sync language files, use this command in Claude Code:\n\n```\nPlease run the i18n sync command\n```\n\nClaude Code will execute:\n\n```bash\nnode .claude/skills/i18n/scripts/sync.mjs\n```\n\n**Output Example:**\n\n```\n🔄 Syncing translation files with en/...\n\n✓ Synced de/\n  + Added 3 keys in components.json\n  + Added 5 keys in pages/home.json\n  - Removed 1 key in shared.json\n\n✓ Synced zh-Hans/\n  + Added 8 keys in pages/stacks.json\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n✓ Sync complete!\n  Modified: 2 locales\n  Added: 16 keys\n  Removed: 1 key\n```\n\n**When to use:**\n\n- After adding new keys to any English JSON file\n- After removing obsolete keys from any English JSON file\n- After adding new JSON files to the English structure\n- Before starting translation work (ensures all keys exist)\n- When adding a new locale\n\n---\n\n### `translate <locale>`\n\nGenerate translation tasks for Claude Code to translate missing content.\n\n**What it does:**\n\n- Reads all JSON files from `en/` and `<locale>/`\n- Identifies keys that need translation (currently in English or missing)\n- Outputs a structured translation task with guidelines\n- Provides context and instructions for accurate translation\n\n**Usage:**\n\nWhen you need to translate content, use this command in Claude Code:\n\n```\nPlease run the i18n translate command for ja\n```\n\nClaude Code will execute:\n\n```bash\nnode .claude/skills/i18n/scripts/translate.mjs ja\n```\n\n**Workflow:**\n\n1. The script outputs content that needs translation in JSON format\n2. Claude Code reads the guidelines and translates the content\n3. You provide the translated JSON back\n4. Claude Code updates the locale JSON files\n\n**Translation Guidelines (automatically enforced):**\n\n✓ **Preserve brand names:** `AI Coding Stack`, `Claude Code`, etc.\n✓ **Keep placeholders intact:** `{count}`, `{name}`, `${variable}`\n✓ **Don''t translate URLs:** `https://example.com`\n✓ **Don''t translate file paths:** `/path/to/file`\n✓ **Maintain terminology consistency** throughout the translation\n✓ **Preserve reference syntax:** `@:path.to.key` for internal references\n\n**Output Example:**\n\n```\n🌐 Translation Assistant for ja\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n📝 Translation Task\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nTarget Language: 日本語 (Japanese)\nEntries to translate: 15\n\nFiles affected:\n  - components.json: 5 entries\n  - pages/home.json: 8 entries\n  - shared.json: 2 entries\n\n⚠ Translation Guidelines:\n  1. Preserve brand names: \"AI Coding Stack\", \"Claude Code\"\n  2. Keep placeholders intact: {count}, {name}, ${variable}\n  3. Don''t translate URLs and file paths\n  4. Maintain consistent terminology\n  5. Preserve reference syntax: @:path.to.key\n\nContent to translate:\n\n```json\n{\n  \"components.languageSwitcher.english\": \"English\",\n  \"pages.home.hero.title\": \"Welcome to AI Coding Stack\",\n  \"shared.navigation.docs\": \"Documentation\",\n  ...\n}\n```\n```\n\n---\n\n## File Structure\n\n```\n.claude/skills/i18n/\n├── SKILL.md              # This documentation\n└── scripts/\n    ├── sync.mjs          # Synchronization script\n    └── translate.mjs     # Translation assistant script\n```\n\n## Technical Details\n\n**Language:** Node.js (ES Modules)\n**Dependencies:** Built-in Node.js modules only (`fs`, `path`)\n**JSON Format:** 2-space indentation, trailing newline\n**Encoding:** UTF-8\n\n### Translation File Structure\n\nEach locale has:\n1. **JSON files**: Contain the actual message data\n2. **index.ts**: Imports and assembles messages\n\n```typescript\n// translations/en/index.ts\nimport components from ''./components.json''\nimport articles from ''./pages/articles.json''\nimport comparison from ''./pages/comparison.json''\nimport curatedCollections from ''./pages/curated-collections.json''\nimport docs from ''./pages/docs.json''\nimport home from ''./pages/home.json''\nimport landscape from ''./pages/landscape.json''\nimport manifesto from ''./pages/manifesto.json''\nimport openSourceRank from ''./pages/open-source-rank.json''\nimport search from ''./pages/search.json''\nimport stacks from ''./pages/stacks.json''\nimport shared from ''./shared.json''\n\nconst messages = {\n  shared,\n  components,\n  pages: {\n    home,\n    manifesto,\n    docs,\n    articles,\n    curatedCollections,\n    stacks,\n    comparison,\n    landscape,\n    openSourceRank,\n    search,\n  },\n}\n\nexport default messages\n```\n\n### How Keys Are Compared\n\nThe scripts use recursive traversal to handle nested JSON structures. Keys are compared using dot notation:\n\n```json\n{\n  \"pages\": {\n    \"home\": {\n      \"hero\": {\n        \"title\": \"Welcome\"\n      }\n    }\n  }\n}\n```\n\nBecomes: `pages.home.hero.title = \"Welcome\"`\n\n### Adding a New Language\n\n**Note:** The project currently supports 12 locales. To add a new locale (e.g., Italian ''it''):\n\n1. Add the locale to `src/i18n/config.ts`:\n\n```typescript\nexport const locales = [\n  ''en'', ''de'', ''es'', ''fr'', ''id'', ''ja'', ''ko'', ''pt'', ''ru'', ''tr'', ''zh-Hans'', ''zh-Hant'',\n  ''it''  // Add new locale\n] as const;\n```\n\n2. Update locale names:\n\n```typescript\nexport const localeNames: Record<Locale, string> = {\n  // ... existing locales\n  it: ''Italiano'',\n}\n\nexport const localeToOgLocale: Record<Locale, string> = {\n  // ... existing locales\n  it: ''it_IT'',\n}\n```\n\n3. Add to translate.mjs LOCALE_NAMES (`.claude/skills/i18n/scripts/translate.mjs`):\n\n```javascript\nconst LOCALE_NAMES = {\n  // ... existing locales\n  it: ''Italiano (Italian)'',\n}\n```\n\n4. Create the locale directory structure:\n\n```bash\nmkdir -p translations/it/pages\ncp translations/en/index.ts translations/it/index.ts\ncp translations/en/*.json translations/it/\ncp translations/en/pages/*.json translations/it/pages/\n```\n\n5. Run sync to ensure structure matches:\n\n```\nPlease run the i18n sync command\n```\n\n6. Run translate to generate translation tasks:\n\n```\nPlease run the i18n translate command for it\n```\n\n## Best Practices\n\n1. **Always run `sync` before `translate`** to ensure all keys exist\n2. **Make changes to English files first**, then sync other locales\n3. **Review translations** for context accuracy, especially technical terms\n4. **Use Git** to track changes and review diffs before committing\n5. **Keep brand names consistent** across all languages\n6. **Test translations** in the actual UI to verify formatting and length\n7. **Preserve key order** to make diffs easier to review\n8. **Use reference syntax** (`@:path.to.key`) for reused content\n\n## Troubleshooting\n\n**Problem:** Script says \"directory not found\"\n\n- **Solution:** Ensure you''re running from project root\n- Check that `translations/` directory exists\n\n**Problem:** Keys are out of sync after adding new content\n\n- **Solution:** Run `sync` command to update all locale files\n\n**Problem:** Translation contains placeholders like `{0}` instead of `{count}`\n\n- **Solution:** Verify the English source uses named placeholders, re-translate\n\n**Problem:** Some text appears in English in the translated app\n\n- **Solution:** Run `translate` to find missing translations, check for English fallbacks\n\n**Problem:** index.ts imports are wrong after sync\n\n- **Solution:** The sync script preserves index.ts structure; manually check imports match actual JSON files\n\n## Integration with next-intl\n\nThis skill is designed to work with the project''s `next-intl` setup:\n\n```typescript\n// src/i18n/request.ts\nconst rawMessages = (await import(`../../translations/${locale}/index.ts`)).default\nconst messages = resolveReferences(rawMessages)\n```\n\nThe JSON files are loaded through the index.ts for each locale, and the `resolveReferences` function handles reference syntax.\n\n### Reference Resolution\n\nThe project supports **reference syntax** for reusing translations:\n\n**Basic Reference:** `@:path.to.key`\n```json\n{\n  \"shared\": {\n    \"appName\": \"AI Coding Stack\",\n    \"welcome\": \"Welcome to @:shared.appName\"\n  }\n}\n// Result: \"Welcome to AI Coding Stack\"\n```\n\n**Reference with Modifiers:** `@.modifier:path.to.key`\n\nSupported modifiers:\n- `@.upper:path` - Convert to UPPERCASE\n- `@.lower:path` - Convert to lowercase\n- `@.capitalize:path` - Capitalize first letter\n\n```json\n{\n  \"terms\": {\n    \"documentation\": \"documentation\",\n    \"title\": \"@.capitalize:terms.documentation Guide\"\n  }\n}\n// Result: \"Documentation Guide\"\n```\n\n**Important:**\n- References are resolved at runtime by `src/i18n/lib-core.ts`\n- Circular references are detected and will throw an error\n- References can be nested (references within references)\n- Keep reference syntax intact during translation\n\n## License\n\nThis skill is part of the AI Coding Stack project and follows the project''s Apache 2.0 license.\n"},"lastSynced":"2026-03-06T06:39:22.408Z","agentAnalysis":{"suitability":{"en":"Ideal for Multilingual AI Agents requiring seamless internationalization management with JSON message files.","zh":"适用于需要无缝国际化管理的多语言 AI 代理，使用 JSON 消息文件。","ja":"JSON メッセージファイルを使用してシームレスな国際化管理が必要なマルチリンガル AI エージェントに最適です。","ko":"JSON 메시지 파일을 사용하여 무縫 internacionalization 관리가 필요한 다국어 AI 에이전트에 적합합니다.","es":"Ideal para agentes de inteligencia artificial multilingües que requieren una gestión de internacionalización sin problemas con archivos de mensajes JSON.","fr":"Idéal pour les agents d''intelligence artificielle multilingues nécessitant une gestion d''internationalisation transparente avec des fichiers de messages JSON.","de":"Ideal für mehrsprachige KI-Agents, die eine nahtlose Internationalisierungsverwaltung mit JSON-Nachrichtendateien erfordern.","pt":"Ideal para Agentes de IA Multilíngues que requerem gestão de internacionalização sem problemas com arquivos de mensagens JSON.","ru":"Идеально для многоязычных агентов ИИ, требующих бесшовного управления интернационализацией с помощью файлов сообщений JSON.","ar":"مثالي لعميل الذكاء الاصطناعي متعددة اللغات التي تتطلب إدارة التدويل دون مشاكل مع ملفات الرسائل JSON."},"recommendation":{"en":"Empowers agents to synchronize language files with the English reference using next-intl, assisting with translations and managing multilingual content in the translations/ directory with JSON files.","zh":"赋予代理人使用 next-intl 同步语言文件与英文参考文件的能力，并在 translations/ 目录中使用 JSON 文件协助翻译和管理多语言内容。","ja":"next-intl を使用して言語ファイルを英語の参考ファイルと同期し、translations/ ディレクトリで JSON ファイルを使用して翻訳を支援し、多言語コンテンツを管理する機能をエージェントに提供します。","ko":"next-intl를 사용하여 언어 파일을 영어 참고 파일과 동기화하는 기능을 제공하며, translations/ 디렉토리에서 JSON 파일을 사용하여 번역을 지원하고 다국어 콘텐츠를 관리합니다.","es":"Habilita a los agentes a sincronizar archivos de idioma con la referencia en inglés utilizando next-intl, asistiendo con traducciones y gestionando contenido multilingüe en el directorio translations/ con archivos JSON.","fr":"Permet aux agents de synchroniser les fichiers de langue avec la référence anglaise en utilisant next-intl, en aidant à la traduction et en gérant le contenu multilingue dans le répertoire translations/ avec des fichiers JSON.","de":"Ermöglicht es den Agents, Sprachdateien mit der englischen Referenz mithilfe von next-intl zu synchronisieren, und unterstützt bei der Übersetzung und der Verwaltung von mehrsprachigem Inhalt im Verzeichnis translations/ mit JSON-Dateien.","pt":"Habilita os agentes a sincronizar arquivos de idioma com o referencial em inglês usando next-intl, assistindo com traduções e gerenciando conteúdo multilíngue no diretório translations/ com arquivos JSON.","ru":"Наделяет агентов возможностью синхронизировать языковые файлы с английским справочником, используя next-intl, что помогает с переводами и управлением многоязычным контентом в директории translations/ с файлами JSON.","ar":"تمكّن الوكيل من مزامنة ملفات اللغة مع المرجع الإنجليزي باستخدام next-intl، مما يساعد في الترجمات وإدارة المحتوى المتعدد اللغات في الدليل translations / مع ملفات JSON."},"useCases":{"en":["Synchronizing language files with the English reference","Assisting with translations in the translations/ directory","Managing multilingual content with next-intl and JSON message files"],"zh":["与英文参考文件同步语言文件","在 translations/ 目录中协助翻译","使用 next-intl 和 JSON 消息文件管理多语言内容"],"ja":["英語の参考ファイルと言語ファイルを同期する","translations/ ディレクトリで翻訳を支援する","next-intl と JSON メッセージファイルを使用して多言語コンテンツを管理する"],"ko":["영어 참고 파일과 언어 파일을 동기화하는","translations/ 디렉토리에서 번역을 지원하는","next-intl와 JSON 메시지 파일을 사용하여 다국어 콘텐츠를 관리하는"],"es":["Sincronizar archivos de idioma con la referencia en inglés","Asistir con traducciones en el directorio translations/","Gestionar contenido multilingüe con next-intl y archivos de mensajes JSON"],"fr":["Synchroniser les fichiers de langue avec la référence anglaise","Aider à la traduction dans le répertoire translations/","Gérer le contenu multilingue avec next-intl et des fichiers de messages JSON"],"de":["Sprachdateien mit der englischen Referenz synchronisieren","Bei der Übersetzung im Verzeichnis translations/ unterstützen","Mehrsprachigen Inhalt mit next-intl und JSON-Nachrichtendateien verwalten"],"pt":["Sincronizar arquivos de idioma com o referencial em inglês","Assistir com traduções no diretório translations/","Gerenciar conteúdo multilíngue com next-intl e arquivos de mensagens JSON"],"ru":["Синхронизировать языковые файлы с английским справочником","Помогать с переводами в директории translations/","Управлять многоязычным контентом с помощью next-intl и файлов сообщений JSON"],"ar":["مزامنة ملفات اللغة مع المرجع الإنجليزي","مساعدة في الترجمات في الدليل translations /","إدارة المحتوى المتعدد اللغات مع next-intl وملفات الرسائل JSON"]},"limitations":{"en":["Requires next-intl for internationalization","JSON message files organized in translations/ directory"],"zh":["需要 next-intl 进行国际化","JSON 消息文件组织在 translations/ 目录中"],"ja":["国際化には next-intl が必要","JSON メッセージファイルは translations/ ディレクトリに組織される"],"ko":["국제화에는 next-intl이 필요","JSON 메시지 파일은 translations/ 디렉토리에 조직"],"es":["Requiere next-intl para la internacionalización","Archivos de mensajes JSON organizados en el directorio translations/"],"fr":["Nécessite next-intl pour l''internationalisation","Fichiers de messages JSON organisés dans le répertoire translations/"],"de":["Benötigt next-intl für die Internationalisierung","JSON-Nachrichtendateien im Verzeichnis translations/ organisiert"],"pt":["Requer next-intl para internacionalização","Arquivos de mensagens JSON organizados no diretório translations/"],"ru":["Требует next-intl для интернационализации","Файлы сообщений JSON, организованные в директории translations/"],"ar":["يتطلب next-intl للتنويع","ملفات الرسائل JSON المنظمة في الدليل translations /"]},"version":4},"contentHash":"d46e075d29f64514056a20d1b66ddc46a7f0b325d23601db9a9455bedd197087","qualityScore":50}');
