INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('loonghao/auroraview/vx-usage', 'vx-usage', 'loonghao', 'auroraview', 'community', 'vx-usage loonghao auroraview community vx-usage is a lightweight framework that automatically installs and manages development tools like Node.js and Python. It benefits developers by streamlining their workflow. vx-usage是一款基于Rust和Python的WebView框架，用于数字内容创作软件，提供自动安装和管理开发工具 vx-usageは、RustとPythonで構築されたデジタルコンテンツ作成ソフトウェア向けのWebViewフレームワークです vx-usage는 러스트와 파이썬으로 구축된 디지털 콘텐츠 제작 소프트웨어를 위한 웹뷰 프레임워크입니다 vx-usage es un marco de trabajo ligero y rápido para la gestión de herramientas de desarrollo, construido con Rust y Python vx-usage est un cadre de travail léger et rapide pour la gestion des outils de développement, construit avec Rust et Python vx-usage ist ein leichtes und schnelles Framework für die Verwaltung von Entwicklungstools, entwickelt mit Rust und Python A ferramenta vx-usage é uma solução leve e rápida para gerenciar ferramentas de desenvolvimento como Node.js, Python e Rust Инструмент vx-usage является легким и быстрым решением для управления инструментами разработки, такими как Node.js, Python и Rust أداة vx-usage هي حل خفيف وسريع لإدارة أدوات التطوير مثل Node.js و Python و Rust how to use vx-usage vx-usage alternative vx-usage install vx-usage vs Docker what is vx-usage vx-usage setup guide vx-usage Node.js integration vx-usage Python support vx-usage WebView框架 数字内容创作软件 Rust Python 自动安装 开发工具管理 轻量级 高性能 Auto-installs Node.js with the `vx node` command Supports Python development with `vx uv pip` command Enables Go development with `vx go build` command Manages Rust tools with `vx cargo build` command Requires zero configuration for development tool setup vx-usage is a universal development tool manager that auto-installs tools like Node.js, Python, and Go with zero configuration using the `vx` command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ionfury/homelab/sre', 'community', 'ionfury', 'homelab', 'ionfury/homelab', 'sre', 22, 3, 50, '2026-02-25T17:35:15Z', '2026-03-06T06:40:56.669Z', '3ecc82e2345263462a1fff3054846a29c1678cd4cf79113c169f6da11c8a322c', '{"id":"ionfury/homelab/sre","name":"sre","description":{"en":"The sre skill enables AI agents to debug Kubernetes incidents using 5 Whys Analysis and Multi-Source Correlation, benefiting devops teams and Kubernetes administrators.","zh":"SRE 技术提供了 Kubernetes 故障排除、集群访问和内部服务 URL 的解决方案，帮助开发者提高效率","ja":"SRE 技術は、Kubernetes のトラブルシューティング、クラスタアクセス、内部サービス URL の解決策を提供し、開発者の効率を向上させます","ko":"SRE 기술은 Kubernetes 문제 해결, 클러스터 액세스 및 내부 서비스 URL의 해결책을 제공하여 개발자의 효율성을 향상시킵니다","es":"SRE es una habilidad que permite la configuración y el análisis de incidentes en clústeres Kubernetes","fr":"SRE est une compétence qui permet la configuration et l''analyse des incidents dans les clusters Kubernetes","de":"SRE ist eine Fähigkeit, die die Konfiguration und Analyse von Incidenten in Kubernetes-Clustern ermöglicht","pt":"O SRE é uma habilidade que fornece acesso a clusters, padrões de KUBECONFIG e URLs de serviços internos, com foco em depuração de incidentes","ru":"SRE - это навык, который предоставляет доступ к кластерам, шаблонам KUBECONFIG и внутренним URL-адресам служб, с фокусом на устранении несоответствий","ar":"SRE هو مهارة توفر وصولًا إلى المجموعات، ونماذج KUBECONFIG، و عناوين URL للخدمات الداخلية، مع التركيز على تحليل الحوادث"},"seo":{"title":{"en":"sre: Kubernetes Debugging Setup Guide | AI Agent Skill","zh":"SRE Setup Guide: Kubernetes 故障排除和集群访问","ja":"SRE セットアップガイド: Kubernetes トラブルシューティングとクラスタアクセス","ko":"SRE 설정 가이드: Kubernetes 문제 해결 및 클러스터 액세스","es":"Guía de configuración de SRE para Kubernetes","fr":"Guide de configuration SRE pour Kubernetes","de":"SRE-Setup-Anleitung für Kubernetes","pt":"Guia de Configuração SRE: Práticas de Depuração de Incide...","ru":"ИИ Агенты SRE: Руководство по Настройке и Устранению Несо...","ar":"إعداد مرشد SRE: أفضل الممارسات للتحليل الفني"},"description":{"en":"Unlock efficient Kubernetes incident debugging with sre. Learn how to apply 5 Whys Analysis and Multi-Source Correlation for root cause identification","zh":"了解 SRE 技术，掌握 Kubernetes 故障排除、集群访问和内部服务 URL 的最佳实践","ja":"SRE 技術を学び、Kubernetes のトラブルシューティング、クラスタアクセス、内部サービス URL のベストプラクティスを習得する","ko":"SRE 기술을 학습하고 Kubernetes 문제 해결, 클러스터 액세스 및 내부 서비스 URL의 모범 사례를 습득하세요","es":"Aprende a implementar SRE con Kubernetes, incluyendo acceso a clústeres y análisis de incidentes","fr":"Découvrez comment mettre en œuvre SRE avec Kubernetes, y compris l''accès aux clusters et l''analyse des incidents","de":"Erfahren Sie, wie Sie SRE mit Kubernetes implementieren, einschließlich Cluster-Zugriff und Incident-Analyse","pt":"Aprenda a configurar e depurar incidentes com o SRE, utilizando técnicas de análise de 5 Whys e investigação de apenas leitura","ru":"Узнайте, как настроить и устранить несоответствия с помощью SRE, используя методы анализа 5 Whys и только чтение","ar":"تعرف على كيفية إعداد وتحليل الحوادث باستخدام SRE، باستخدام تقنيات تحليل 5 Whys والتحقيق القراءة فقط"},"definition":{"en":"sre is a skill for debugging Kubernetes incidents, focusing on root cause analysis and multi-source correlation for efficient issue resolution","zh":"SRE 是一种 Site Reliability Engineering 技术，用于提高 Kubernetes 集群的可靠性和效率","ja":"SRE は、Kubernetes クラスタの信頼性と効率を向上させるための Site Reliability Engineering 技術です","ko":"SRE는 Kubernetes 클러스터의 신뢰성과 효율성을 향상시키기 위한 사이트 신뢰성 엔지니어링 기술입니다","es":"SRE es una habilidad que combina la configuración de clústeres Kubernetes con análisis de incidentes","fr":"SRE est une compétence qui combine la configuration de clusters Kubernetes avec l''analyse des incidents","de":"SRE ist eine Fähigkeit, die die Konfiguration von Kubernetes-Clustern mit der Analyse von Incidenten kombiniert","pt":"O SRE é uma habilidade que se refere à engenharia de confiabilidade de sites, com foco em depuração de incidentes e análise de causa raiz","ru":"SRE - это навык, который относится к инженерии надежности сайтов, с фокусом на устранении несоответствий и анализе коренной причины","ar":"SRE هو مهارة ترجع إلى هندسة موثوقية المواقع، مع التركيز على تحليل الحوادث وتحليل السبب الجذري"},"features":{"en":["Applies 5 Whys Analysis for root cause identification","Utilizes Read-Only Investigation for observing and analyzing Kubernetes resources","Combines logs, events, and metrics for Multi-Source Correlation","Integrates with k8s skill for cluster access and KUBECONFIG patterns","Supports direct mutations for debugging in dev clusters"],"zh":["Kubernetes 故障排除和集群访问","内部服务 URL 和 KUBECONFIG 模式","5 Whys 分析和读写分离调查","多源关联和日志、事件、指标分析","支持 devops、harvester、k8s-at-home、rancher、rke"],"ja":["Kubernetes トラブルシューティングとクラスタアクセス","内部サービス URL と KUBECONFIG パターン","5 Whys 分析と読み取り専用調査","多源関連とログ、イベント、メトリクス分析","devops、harvester、k8s-at-home、rancher、rke をサポート"],"ko":["Kubernetes 문제 해결 및 클러스터 액세스","내부 서비스 URL 및 KUBECONFIG 패턴","5 Whys 분석 및 읽기 전용 조사","다중 소스 상관 관계 및 로그, 이벤트, 메트릭 분석","devops, harvester, k8s-at-home, rancher, rke 지원"],"es":["Acceso a clústeres Kubernetes","Análisis de incidentes con 5 Whys","Investigación de solo lectura","Correlación de múltiples fuentes","Integración con herramientas de DevOps como Rancher y RKE"],"fr":["Accès aux clusters Kubernetes","Analyse des incidents avec 5 Whys","Investigation en lecture seule","Corrélation de multiples sources","Intégration avec des outils DevOps tels que Rancher et RKE"],"de":["Zugriff auf Kubernetes-Cluster","Incidentenanalyse mit 5 Whys","Schreibgeschützte Untersuchung","Korrelation mehrerer Quellen","Integration mit DevOps-Tools wie Rancher und RKE"],"pt":["Acesso a clusters e padrões de KUBECONFIG","Análise de 5 Whys para identificar a causa raiz","Investigação de apenas leitura para evitar modificações","Combinação de logs, eventos e métricas para análise completa","Integração com Kubernetes e Rancher"],"ru":["Доступ к кластерам и шаблонам KUBECONFIG","Анализ 5 Whys для выявления коренной причины","Только чтение для избежания модификаций","Объединение логов, событий и метрик для полного анализа","Интеграция с Kubernetes и Rancher"],"ar":["الوصول إلى المجموعات و نماذج KUBECONFIG","تحليل 5 Whys لتحديد السبب الجذري","التحقيق القراءة فقط لتجنب التعديلات","مجموعة السجلات والأحداث والمقاييس للتحليل الكامل","التكامل مع Kubernetes و Rancher"]},"keywords":{"en":["how to use sre for Kubernetes debugging","sre vs traditional debugging methods","sre setup guide for AI agents","what is sre in devops","sre alternative for Kubernetes incident management","kubernetes debugging best practices with sre"],"zh":["SRE","Kubernetes","故障排除","集群访问","内部服务 URL","KUBECONFIG","5 Whys 分析","devops","harvester","k8s-at-home","rancher","rke"],"ja":["SRE","Kubernetes","トラブルシューティング","クラスタアクセス","内部サービス URL","KUBECONFIG","5 Whys 分析","devops","harvester","k8s-at-home","rancher","rke"],"ko":["SRE","Kubernetes","문제 해결","클러스터 액세스","내부 서비스 URL","KUBECONFIG","5 Whys 분석","devops","harvester","k8s-at-home","rancher","rke"],"es":["SRE","Kubernetes","DevOps","análisis de incidentes","configuración de clústeres","5 Whys","Rancher","RKE","herramientas de DevOps"],"fr":["SRE","Kubernetes","DevOps","analyse des incidents","configuration de clusters","5 Whys","Rancher","RKE","outils DevOps"],"de":["SRE","Kubernetes","DevOps","Incidentenanalyse","Cluster-Konfiguration","5 Whys","Rancher","RKE","DevOps-Tools"],"pt":["sre","depuração de incidentes","análise de 5 whys","investigação de apenas leitura","kubernetes","rancher","k8s","devops","harvester"],"ru":["sre","устранение несоответствий","анализ 5 whys","только чтение","kubernetes","rancher","k8s","devops","harvester"],"ar":["sre","تحليل الحوادث","تحليل 5 whys","التحقيق القراءة فقط","kubernetes","rancher","k8s","devops","harvester"]}},"owner":"ionfury","repo":"homelab","repoPath":"ionfury/homelab","stars":22,"forks":3,"updatedAt":"2026-02-25T17:35:15Z","topics":["devops","harvester","k8s-at-home","kubernetes","rancher","rke"],"category":"community","skillMd":{"name":"sre","description":"|","bodyPreview":"> **Cluster access, KUBECONFIG patterns, and internal service URLs** are in the `k8s` skill.\n\n# Debugging Kubernetes Incidents\n\n## Core Principles\n\n- **5 Whys Analysis** - NEVER stop at symptoms. Ask \"why\" until you reach the root cause.\n- **Read-Only Investigation** - Observe and analyze, never modify resources on integration/live. Dev cluster permits direct mutations for debugging (see troubleshooter agent boundaries)\n- **Multi-Source Correlation** - Combine logs, events, metrics for complete","body":"> **Cluster access, KUBECONFIG patterns, and internal service URLs** are in the `k8s` skill.\n\n# Debugging Kubernetes Incidents\n\n## Core Principles\n\n- **5 Whys Analysis** - NEVER stop at symptoms. Ask \"why\" until you reach the root cause.\n- **Read-Only Investigation** - Observe and analyze, never modify resources on integration/live. Dev cluster permits direct mutations for debugging (see troubleshooter agent boundaries)\n- **Multi-Source Correlation** - Combine logs, events, metrics for complete picture\n- **Research Unknown Services** - Check documentation before deep investigation\n- **Zero Alert Tolerance** - Every firing alert must be addressed immediately: fix the root cause, or as a last resort, create a declarative Silence CR with justification. Never ignore, defer, or dismiss a firing alert.\n\n## The 5 Whys Analysis (CRITICAL)\n\n**You MUST apply 5 Whys before concluding any investigation.** Stopping at symptoms leads to ineffective fixes.\n\n### How to Apply\n\n1. Start with the observed symptom\n2. Ask \"Why did this happen?\" for each answer\n3. Continue until you reach an actionable root cause (typically 5 levels)\n\n### Example\n\n```\nSymptom: Helm install failed with \"context deadline exceeded\"\n\nWhy #1: Why did Helm timeout?\n  → Pods never became Ready\n\nWhy #2: Why weren''t pods Ready?\n  → Pods stuck in Pending state\n\nWhy #3: Why were pods Pending?\n  → PVCs couldn''t bind (StorageClass \"fast\" not found)\n\nWhy #4: Why was StorageClass missing?\n  → longhorn-storage Kustomization failed to apply\n\nWhy #5: Why did the Kustomization fail?\n  → numberOfReplicas was integer instead of string\n\nROOT CAUSE: YAML type coercion issue\nFIX: Use properly typed variable for StorageClass parameters\n```\n\n### Red Flags You Haven''t Reached Root Cause\n\n- Your \"fix\" is increasing a timeout or retry count\n- Your \"fix\" addresses the symptom, not what caused it\n- You can still ask \"but why did THAT happen?\"\n- Multiple issues share the same underlying cause\n\n```\nBAD:  \"Helm timed out → increase timeout to 15m\"\nGOOD: \"Helm timed out → ... → Kustomization type error → fix YAML\"\n```\n\n## Investigation Phases\n\n### Phase 1: Triage\n\n1. **Confirm cluster** - Ask user: \"Which cluster? (dev/integration/live)\"\n2. **Assess severity** - P1 (down) / P2 (degraded) / P3 (minor) / P4 (cosmetic)\n3. **Identify scope** - Pod / Deployment / Namespace / Cluster-wide\n\n### Phase 2: Data Collection\n\n```bash\n# Pod status and events\nkubectl get pods -n <namespace>\nkubectl describe pod <pod> -n <namespace>\n\n# Logs (current and previous)\nkubectl logs <pod> -n <namespace> --tail=100\nkubectl logs <pod> -n <namespace> --previous\n\n# Events timeline\nkubectl get events -n <namespace> --sort-by=''.lastTimestamp''\n\n# Resource usage\nkubectl top pods -n <namespace>\n```\n\n**Metrics and alerts via kubectl exec (Prometheus is behind OAuth2 Proxy — DNS URLs won''t work for API queries):**\n\n```bash\n# Check firing alerts\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl exec -n monitoring prometheus-kube-prometheus-stack-0 -c prometheus -- \\\n  wget -qO- ''http://localhost:9090/api/v1/alerts'' | jq ''.data.alerts[] | select(.state == \"firing\")''\n\n# Pod restart metrics\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl exec -n monitoring prometheus-kube-prometheus-stack-0 -c prometheus -- \\\n  wget -qO- ''http://localhost:9090/api/v1/query?query=increase(kube_pod_container_status_restarts_total[1h])>0'' | jq ''.data.result''\n```\n\n### Phase 3: Correlation\n\n1. Extract timestamps from logs, events, metrics\n2. Identify what happened FIRST (root cause)\n3. Trace the cascade of effects\n\n### Phase 4: Root Cause (5 Whys)\n\nApply 5 Whys analysis. Validate:\n- **Temporal**: Did it happen BEFORE the symptom?\n- **Causal**: Does it logically explain the symptom?\n- **Evidence**: Is there supporting data?\n- **Complete**: Have you asked \"why\" enough times?\n\n### Phase 5: Remediation\n\nUse **AskUserQuestion** tool to present fix options when multiple valid approaches exist.\n\nProvide recommendations only (read-only investigation):\n- **Immediate**: Rollback, scale, restart\n- **Permanent**: Code/config fixes\n- **Prevention**: Alerts, quotas, tests\n\n## Quick Diagnosis\n\n| Symptom | First Check | Common Cause |\n|---------|-------------|--------------|\n| `ImagePullBackOff` | `describe pod` events | Wrong image/registry auth |\n| `Pending` | Events, node capacity | Insufficient resources |\n| `CrashLoopBackOff` | `logs --previous` | App error, missing config |\n| `OOMKilled` | Memory limits | Memory leak, limits too low |\n| `Unhealthy` | Probe config | Slow startup, wrong endpoint |\n| Service unreachable | Hubble dropped traffic | **Network policy blocking** |\n| Can''t reach database | Hubble + namespace labels | Missing access label |\n| Gateway returns 503 | Hubble from istio-gateway | Missing profile label |\n\n## Common Failure Chains\n\n**Storage failures cascade:**\n```\nStorageClass missing → PVC Pending → Pod Pending → Helm timeout\n```\n\n**Network failures cascade:**\n```\nDNS failure → Service unreachable → Health check fails → Pod restarted\n```\n\n**Network policy failures cascade:**\n```\nMissing namespace profile label → No ingress allowed → Service unreachable from gateway\nMissing access label → Can''t reach database → App fails health checks → CrashLoopBackOff\n```\n\n**Secret failures cascade:**\n```\nExternalSecret fails → Secret missing → Pod CrashLoopBackOff\n```\n\n## Network Policy Debugging (Cilium + Hubble)\n\n**Network policies are ENFORCED - all traffic is implicitly denied unless allowed.**\n\n### Check for Blocked Traffic\n\n```bash\n# Setup Hubble access (run once per session)\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl port-forward -n kube-system svc/hubble-relay 4245:80 &\n\n# See dropped traffic in a namespace\nhubble observe --verdict DROPPED --namespace <namespace> --since 5m\n\n# See what''s trying to reach a service\nhubble observe --to-namespace <namespace> --verdict DROPPED --since 5m\n\n# Check specific traffic flow\nhubble observe --from-namespace <source> --to-namespace <dest> --since 5m\n```\n\n### Common Network Policy Issues\n\n| Symptom | Check | Fix |\n|---------|-------|-----|\n| Service unreachable from gateway | `kubectl get ns <ns> --show-labels` | Add profile label |\n| Can''t reach database | Check `access.network-policy.homelab/postgres` label | Add access label |\n| Pods can''t resolve DNS | Hubble DNS drops (rare - baseline allows) | Check for custom egress blocking |\n| Inter-pod communication fails | Hubble intra-namespace drops | Baseline should allow - check for overrides |\n\n### Namespace Labels Checklist\n\n```bash\n# Check namespace has required labels\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl get ns <namespace> -o jsonpath=''{.metadata.labels}'' | jq\n\n# Required for app namespaces:\n# - network-policy.homelab/profile: standard|internal|internal-egress|isolated\n\n# Optional access labels:\n# - access.network-policy.homelab/postgres: \"true\"\n# - access.network-policy.homelab/garage-s3: \"true\"\n# - access.network-policy.homelab/kube-api: \"true\"\n```\n\n### Emergency: Disable Network Policies\n\n```bash\n# Escape hatch - disables enforcement for namespace (triggers alert after 5m)\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl label namespace <ns> network-policy.homelab/enforcement=disabled\n\n# Re-enable after fixing\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl label namespace <ns> network-policy.homelab/enforcement-\n```\n\nSee `docs/runbooks/network-policy-escape-hatch.md` for full procedure.\n\n## Kickstarting Stalled HelmReleases\n\nHelmReleases can get stuck in a `Stalled` state with `RetriesExceeded` even after the underlying issue is resolved. This happens because:\n\n1. The HR hit its retry limit (default: 4 attempts)\n2. The failure counter persists even if pods are now healthy\n3. Flux won''t auto-retry once `Stalled` condition is set\n\n**Symptoms:**\n```\nSTATUS: Stalled\nMESSAGE: Failed to install after 4 attempt(s)\nREASON: RetriesExceeded\n```\n\n**Diagnosis:** Check if the underlying resources are actually healthy:\n```bash\n# HR shows Failed, but check if pods are running\nKUBECONFIG=~/.kube/<cluster>.yaml kubectl get pods -n <namespace> -l app.kubernetes.io/name=<app>\n\n# If pods are Running but HR is Stalled, the HR just needs a reset\n```\n\n**Fix:** Suspend and resume to reset the failure counter:\n```bash\nKUBECONFIG=~/.kube/<cluster>.yaml flux suspend helmrelease <name> -n flux-system\nKUBECONFIG=~/.kube/<cluster>.yaml flux resume helmrelease <name> -n flux-system\n```\n\n**Common causes of initial failure (that may have self-healed):**\n- Missing Secret/ConfigMap (ExternalSecret eventually created it)\n- Missing CRD (operator finished installing)\n- Transient network issues during image pull\n- Resource quota temporarily exceeded\n\n**Prevention:** Ensure proper `dependsOn` ordering so prerequisites are ready before HelmRelease installs.\n\n## Promotion Pipeline Debugging\n\n**Symptom: \"Live cluster not updating after merge\"**\n\nThe OCI artifact promotion pipeline has multiple stages where failures can stall deployment.\nWalk through each stage in order to find where the pipeline is stuck.\n\n### Diagnostic Steps\n\n```\n1. PR merged to main\n   └─ Check: Did build-platform-artifact.yaml trigger?\n      └─ GitHub Actions → \"Build Platform Artifact\" workflow\n      └─ If missing: Was kubernetes/ modified? (paths filter)\n\n2. OCI artifact built\n   └─ Check: Is the artifact in GHCR with integration-* tag?\n      └─ flux list artifact oci://ghcr.io/<repo>/platform | grep integration\n\n3. Integration cluster picks up artifact\n   └─ Check: Does OCIRepository see the new version?\n      └─ KUBECONFIG=~/.kube/integration.yaml kubectl get ocirepository -n flux-system\n      └─ Look at .status.artifact.revision — does it match the new RC tag?\n      └─ If stale: Check semver constraint (must be \">= 0.0.0-0\" to accept RCs)\n\n4. Integration reconciliation succeeds\n   └─ Check: Platform Kustomization healthy?\n      └─ KUBECONFIG=~/.kube/integration.yaml flux get kustomizations -n flux-system\n      └─ If failed: Read Kustomization events for the error\n\n5. Flux Alert fires repository_dispatch\n   └─ Check: Did the Alert fire?\n      └─ KUBECONFIG=~/.kube/integration.yaml kubectl describe alert validation-success -n flux-system\n      └─ Check Provider (GitHub) status:\n         KUBECONFIG=~/.kube/integration.yaml kubectl get providers -n flux-system\n\n6. tag-validated-artifact.yaml runs\n   └─ Check: Did the workflow trigger?\n      └─ GitHub Actions → \"Tag Validated Artifact\" workflow\n      └─ If not triggered: repository_dispatch may not have fired\n         (check Provider secret has repo scope)\n      └─ If triggered but failed: Check workflow logs for tagging errors\n\n7. Live cluster picks up validated artifact\n   └─ Check: Does OCIRepository see the stable semver?\n      └─ KUBECONFIG=~/.kube/live.yaml kubectl get ocirepository -n flux-system\n      └─ Semver constraint must be \">= 0.0.0\" (stable only, no RCs)\n```\n\n### Common Failure Modes\n\n| Stage | Symptom | Common Cause |\n|-------|---------|--------------|\n| Build | Workflow did not trigger | `kubernetes/` not in changed paths |\n| Build | Artifact push failed | GHCR auth issue (`GITHUB_TOKEN` permissions) |\n| Integration | OCIRepository not updating | Semver constraint mismatch (not accepting RCs) |\n| Validation | Kustomization failed | Actual config error in the merged PR |\n| Promotion | `repository_dispatch` not received | Provider secret missing `repo` scope |\n| Promotion | Workflow skipped (idempotency guard) | Artifact already tagged as validated |\n| Live | OCIRepository not updating | Stable semver tag not created by tag workflow |\n\n### Manual Promotion (Emergency)\n\nIf the pipeline is stuck and live needs the update:\n\n```bash\n# Authenticate to GHCR\necho $GITHUB_TOKEN | docker login ghcr.io -u $GITHUB_USER --password-stdin\n\n# Find the integration artifact\nflux list artifact oci://ghcr.io/<repo>/platform | grep integration\n\n# Manually tag as validated + stable semver\nflux tag artifact oci://ghcr.io/<repo>/platform:<rc-tag> --tag <stable-semver>\n```\n\nSee `.github/CLAUDE.md` for full pipeline architecture and rollback procedures.\n\n## Common Confusions\n\nBAD: Jump to logs without checking events first\nGOOD: Events provide context, then investigate logs\n\nBAD: Look only at current pod state\nGOOD: Check `--previous` logs if pod restarted\n\nBAD: Assume first error is root cause\nGOOD: Apply 5 Whys to find true root cause\n\nBAD: Investigate without confirming cluster\nGOOD: ALWAYS confirm cluster before any kubectl command\n\n## Keywords\n\nkubernetes, debugging, crashloopbackoff, oomkilled, pending, root cause analysis, 5 whys, incident investigation, pod logs, events, troubleshooting, network policy, hubble, stalled helmrelease, promotion pipeline, live not updating\n"},"lastSynced":"2026-03-06T06:40:56.669Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing advanced Kubernetes incident debugging capabilities using 5 Whys Analysis and Multi-Source Correlation.","zh":"非常适合需要使用5 Whys Analysis和Multi-Source Correlation进行高级Kubernetes故障调试的DevOps Agents。","ja":"DevOpsエージェントがKubernetesのインシデントのデバッグに高度な5 Whys AnalysisおよびMulti-Source Correlationを使用する必要がある場合に最適です。","ko":"5 Whys Analysis 및 Multi-Source Correlation을 사용하여 Kubernetes 고급 인시던트 디버깅이 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para Agentes de DevOps que necesitan capacidades avanzadas de depuración de incidentes de Kubernetes utilizando Análisis de 5 Whys y Correlación de Multi-Fuente.","fr":"Parfait pour les agents DevOps ayant besoin de capacités de débogage avancées d''incidents Kubernetes en utilisant l''Analyse 5 Whys et la Corrélation Multi-Source.","de":"Perfekt für DevOps-Agents, die erweiterte Kubernetes-Incident-Debugging-Funktionen unter Verwendung der 5-Whys-Analyse und der Multi-Quellen-Korrelation benötigen.","pt":"Perfeito para Agentes DevOps que necessitam de capacidades avançadas de depuração de incidentes do Kubernetes usando Análise de 5 Whys e Correlação Multi-Fonte.","ru":"Идеально подходит для агентов DevOps, которым необходимы расширенные возможности отладки инцидентов Kubernetes с помощью анализа 5 Whys и многоисточниковой корреляции.","ar":"مثالي لعمليات وكيل DevOps التي تحتاج إلى إمكانيات متقدمة لتصحيح أعطال حوادث Kubernetes باستخدام تحليل 5 Whys ومرتبطة متعددة المصادر."},"recommendation":{"en":"Empowers agents to debug Kubernetes incidents by combining logs, events, and metrics for complete analysis, leveraging read-only investigation and cluster access via KUBECONFIG patterns.","zh":"通过结合日志、事件和指标以进行完整分析，使用只读调查和通过KUBECONFIG模式的集群访问，赋予代理调试Kubernetes故障的能力。","ja":"ログ、イベント、メトリクスを組み合わせて完全な分析を実行し、KUBECONFIGパターンを使用した読み取り専用の調査およびクラスターアクセスを使用して、エージェントにKubernetesのインシデントをデバッグする能力を付与します。","ko":"로그, 이벤트 및 메트릭스를 결합하여 완전한 분석을 수행하고, KUBECONFIG 패턴을 사용한 읽기 전용 조사 및 클러스터 액세스를 통해 Kubernetes 인시던트를 디버깅할 수 있는 기능을 에이전트에게 부여합니다.","es":"Habilita a los agentes a depurar incidentes de Kubernetes combinando registros, eventos y métricas para un análisis completo, aprovechando la investigación de solo lectura y el acceso al clúster a través de patrones KUBECONFIG.","fr":"Permet aux agents de déboguer les incidents Kubernetes en combinant les journaux, les événements et les métriques pour une analyse complète, en exploitant l''enquête en lecture seule et l''accès au cluster via des modèles KUBECONFIG.","de":"Ermächtigt die Agents, Kubernetes-Incidenten zu debuggen, indem Protokolle, Ereignisse und Metriken für eine vollständige Analyse kombiniert werden, und nutzt die schreibgeschützte Untersuchung und den Clusterzugriff über KUBECONFIG-Muster.","pt":"Habilita os agentes a depurar incidentes do Kubernetes combinando logs, eventos e métricas para uma análise completa, aproveitando investigação somente leitura e acesso ao cluster via padrões KUBECONFIG.","ru":"Наделяет агентов возможностью отладки инцидентов Kubernetes, сочетая журналы, события и метрики для полного анализа, используя только чтение расследования и доступ к кластеру через шаблоны KUBECONFIG.","ar":"تمكين الوكيل من تصحيح أعطال حوادث Kubernetes من خلال الجمع بين سجلات الأحداث والأحداث وأبعاد لتحليل كامل، واستغلال التحقيق للقراءة فقط والوصول إلى المجموعة عبر أنماط KUBECONFIG."},"useCases":{"en":["Debugging Kubernetes incidents using 5 Whys Analysis","Correlating multi-source data for root cause identification","Analyzing cluster access and internal service URLs for issue resolution"],"zh":["使用5 Whys Analysis进行Kubernetes故障调试","通过多源数据关联进行根因识别","分析集群访问和内部服务URL以解决问题"],"ja":["5 Whys Analysisを使用したKubernetesインシデントのデバッグ","マルチソースデータの相関による根本原因の特定","クラスターへのアクセスと内部サービスURLの分析による問題解決"],"ko":["5 Whys Analysis를 사용한 Kubernetes 인시던트 디버깅","다중 소스 데이터 상관 분석을 통한根本 원인 식별","클러스터 액세스 및 내부 서비스 URL 분석을 통한 문제 해결"],"es":["Depuración de incidentes de Kubernetes utilizando Análisis de 5 Whys","Correlación de datos de multi-fuente para la identificación de la causa raíz","Análisis de acceso al clúster y direcciones URL de servicios internos para la resolución de problemas"],"fr":["Débogage d''incidents Kubernetes en utilisant l''Analyse 5 Whys","Corrélation de données multi-sources pour l''identification de la cause profonde","Analyse de l''accès au cluster et des URL de services internes pour la résolution de problèmes"],"de":["Debugging von Kubernetes-Incidenten unter Verwendung der 5-Whys-Analyse","Korrelation von Multi-Quellen-Daten zur Identifizierung der Ursache","Analyse des Cluster-Zugriffs und interner Dienst-URLs zur Problembehebung"],"pt":["Depuração de incidentes do Kubernetes usando Análise de 5 Whys","Correlação de dados multi-fonte para identificação da causa raiz","Análise do acesso ao cluster e URLs de serviços internos para resolução de problemas"],"ru":["Отладка инцидентов Kubernetes с помощью анализа 5 Whys","Корреляция многоисточниковых данных для выявления коренной причины","Анализ доступа к кластеру и внутренних URL-адресов служб для решения проблем"],"ar":["تصحيح أعطال حوادث Kubernetes باستخدام تحليل 5 Whys","مرتبطة بيانات متعددة المصادر لهوية السبب الجذري","تحليل الوصول إلى المجموعة والمواقع الالكترونية الداخلية للخدمات لحل المشكلات"]},"limitations":{"en":["Requires cluster access and KUBECONFIG patterns","Read-only investigation required for live/integration environments","Direct mutations only permitted in dev cluster for debugging"],"zh":["需要集群访问和KUBECONFIG模式","需要只读调查用于live/integration环境","仅允许在dev集群中进行直接变异以进行调试"],"ja":["クラスターへのアクセスとKUBECONFIGパターンが必要","読み取り専用の調査がlive/integration環境に必要","デバッグ用にdevクラスターでのみ直接変異を許可"],"ko":["클러스터 액세스 및 KUBECONFIG 패턴이 필요합니다.","라이브/통합 환경을 위해 읽기 전용 조사 필요","디버깅을 위해 dev 클러스터에서만 직접 변이를 허용"],"es":["Requiere acceso al clúster y patrones KUBECONFIG","Se requiere investigación de solo lectura para entornos en vivo/integración","Mutaciones directas solo permitidas en clúster de desarrollo para depuración"],"fr":["Nécessite un accès au cluster et des modèles KUBECONFIG","Enquête en lecture seule requise pour les environnements en direct/intégration","Mutations directes uniquement autorisées dans le cluster de développement pour le débogage"],"de":["Erfordert Cluster-Zugriff und KUBECONFIG-Muster","Schreibgeschützte Untersuchung erforderlich für Live-/Integrationsumgebungen","Direkte Mutationen nur im Entwicklungscluster für Debugging-Zwecke erlaubt"],"pt":["Requer acesso ao cluster e padrões KUBECONFIG","Investigação somente leitura necessária para ambientes ao vivo/integração","Mutações diretas permitidas apenas no cluster de desenvolvimento para depuração"],"ru":["Требуется доступ к кластеру и шаблоны KUBECONFIG","Только чтение расследования необходимо для живых/интеграционных сред","Прямые мутации разрешены только в кластере разработки для отладки"],"ar":["يتطلب الوصول إلى المجموعة وأنماط KUBECONFIG","التحقيق للقراءة فقط مطلوب للبيئات الحية / التكامل","الطفرات المباشرة مسموح بها فقط في المجموعة التطويرية لتصحيح الأعطال"]},"version":4},"contentHash":"3ecc82e2345263462a1fff3054846a29c1678cd4cf79113c169f6da11c8a322c","qualityScore":50}');
